insert into public.friend_definitions(stable_id,revision_id,name,subtitle,art,metadata,is_placeholder) values('adventure_friend_mm',coalesce((select value from public.app_config where key='app_major_update_content_revision'),'burrow-v1-placeholder'),'Mr Mole','Hm.','{"renderer":"bundled","key":"Mole"}'::jsonb,'{"adventureV2":true,"code":"MM","gender":"he","species":"Mole"}'::jsonb,false) on conflict(stable_id) do update set name=excluded.name,subtitle=excluded.subtitle,art=excluded.art,metadata=excluded.metadata,status='active',updated_at=now();
insert into public.adventure_dialogues_v2(id,friend_id,phase,seq,weight,content) values
('MM-01','adventure_friend_mm','Intro',1,1,'{"id":"MM-01","friendId":"adventure_friend_mm","phase":"Intro","seq":1,"familiarity":"Stranger","type":"Statement","scene":"A pair of round glasses peeks out of a fresh dirt mound.","lines":["Hm. You''re standing on my roof.","...Not complaining. Just saying. Roof. Mine."],"choices":[{"id":"a","label":"Oh! Sorry!","reaction":["Hm. Accepted. Mr Mole. Tunnels, mostly."]},{"id":"b","label":"Nice roof.","reaction":["...Nobody''s said that before. Hm. Best work I''ve done."]},{"id":"c","label":"Tiptoe off quietly","reaction":["Hm. Polite. I like quiet."]}],"outro":null}'::jsonb),
('MM-02','adventure_friend_mm','Intro',2,1,'{"id":"MM-02","friendId":"adventure_friend_mm","phase":"Intro","seq":2,"familiarity":"Familiar Face","type":"Statement","scene":null,"lines":["Been digging this tunnel three weeks. No reason.","Digging helps me think. About nothing. Mostly."],"choices":[{"id":"a","label":"What do you think about?","reaction":["Hm. Dinner. Mostly."]},{"id":"b","label":"That''s kind of cool.","reaction":["Hm. Thanks. Cool''s good."]},{"id":"c","label":"Can I help?","reaction":["...No. But thanks. Maybe next time."]}],"outro":null}'::jsonb),
('MM-03','adventure_friend_mm','Intro',3,1,'{"id":"MM-03","friendId":"adventure_friend_mm","phase":"Intro","seq":3,"familiarity":"Acquaintance","type":"Statement","scene":null,"lines":["Mabel made worm pie today. Best in the burrow.","Don''t tell her I said that. She''ll get ideas."],"choices":[{"id":"a","label":"Why not?","reaction":["She''ll make it every day. Then I''ll have to say ''delicious'' every day."]},{"id":"b","label":"You''re smiling.","reaction":["...Am not. Hm. Maybe a little."]},{"id":"c","label":"Worm pie? ...okay!","reaction":["Don''t knock it till you''ve tried it."]}],"outro":null}'::jsonb),
('MM-04','adventure_friend_mm','Intro',4,1,'{"id":"MM-04","friendId":"adventure_friend_mm","phase":"Intro","seq":4,"familiarity":"Acquaintance","type":"Statement","scene":null,"lines":["Every anniversary I dig Mabel a new window. Nineteen now.","Burrow looks like cheese."],"choices":[{"id":"a","label":"That''s the sweetest thing.","reaction":["Hm. She says thanks every time. I say ''hm.'' That''s our whole conversation."]},{"id":"b","label":"Does she know why?","reaction":["...She knows."]},{"id":"c","label":"Twenty''s coming up, right?","reaction":["Hm. Yes. Thinking about it. Not talking about it."]}],"outro":null}'::jsonb),
('MM-05','adventure_friend_mm','Intro',5,1,'{"id":"MM-05","friendId":"adventure_friend_mm","phase":"Intro","seq":5,"familiarity":"Friend","type":"Ask","scene":null,"lines":["Mabel said last night: ''You never tell me anything.''","I said, ''I dug you a window.'' She said, ''I know. I want words.''","Hm. What do you and your partner say to each other? Normal stuff?"],"choices":[{"id":"a","label":"A lot of ''good morning'' and ''I''m hungry.''","reaction":["Hungry. I can do hungry."]},{"id":"b","label":"Sometimes I just say ''I''m glad it''s you.''","reaction":["...Four words. I can carry four words."]},{"id":"c","label":"Maybe start tiny? One sentence a day?","reaction":["One sentence. Hm. Like a pebble. I give pebbles."]}],"outro":null}'::jsonb),
('MM-06','adventure_friend_mm','Intro',6,1,'{"id":"MM-06","friendId":"adventure_friend_mm","phase":"Intro","seq":6,"familiarity":"Friend","type":"Statement","scene":null,"lines":["I said ''nice dress'' to Mabel yesterday.","She said, ''This is my gardening apron.''","She laughed so hard she cried. Best thing I''ve done in years. Accidentally."],"choices":[{"id":"a","label":"That totally counts!","reaction":["Hm. Counts. Okay."]},{"id":"b","label":"At least she laughed.","reaction":["She did. I wrote it down."]},{"id":"c","label":"Try ''nice apron'' next time.","reaction":["...Hm. Nice apron. Practicing."]}],"outro":null}'::jsonb),
('MM-07','adventure_friend_mm','Intro',7,1,'{"id":"MM-07","friendId":"adventure_friend_mm","phase":"Intro","seq":7,"familiarity":"Close Friend","type":"Confide","scene":"Evening. Mr Mole sits at the tunnel mouth, not digging.","lines":["Can I say something? Don''t laugh.","I think Mabel might be bored of me. She''s bright. Everyone loves her at burrow parties.","I''m the guy near the snacks."],"choices":[{"id":"a","label":"I don''t think she''s bored.","reaction":["Hm. You might be right. I hope."]},{"id":"b","label":"What makes you think that?","reaction":["She laughs more with other people. That''s all. It''s fine. Hm."]},{"id":"c","label":"Sit quietly next to him","reaction":["...Thanks. Not many people know how to do that."]}],"outro":null}'::jsonb),
('MM-08','adventure_friend_mm','Intro',8,1,'{"id":"MM-08","friendId":"adventure_friend_mm","phase":"Intro","seq":8,"familiarity":"Close Friend","type":"Statement","scene":null,"lines":["Mabel''s birthday is Friday. I wrote something.","Three sentences. Been practicing on a worm."],"choices":[{"id":"a","label":"Read it to me!","reaction":["Hm. Okay.","''Mabel. You''re my favorite noise. The house is loud because of you, and I like it.'' ...Too much?"]},{"id":"b","label":"Practice on me, not the worm.","reaction":["Worm''s offended. Fine. Listen.","''Mabel. You''re my favorite noise. The house is loud because of you, and I like it.'' ...Too much?"]},{"id":"c","label":"Three sentences is plenty.","reaction":["Hm. Three is a lot. For me."]}],"outro":"Friday. Wish me luck."}'::jsonb),
('MM-09','adventure_friend_mm','Intro',9,1,'{"id":"MM-09","friendId":"adventure_friend_mm","phase":"Intro","seq":9,"familiarity":"Best Friend","type":"Companion","scene":null,"lines":["Mabel''s at her sister''s for a week.","House is too quiet. Never noticed how much noise she makes. Humming. Pots. Talking to the plants.","I keep setting two cups."],"choices":[{"id":"a","label":"Aw. Send her a note?","reaction":["Already wrote it. Four lines. Scared to send."]},{"id":"b","label":"Tell her you miss her.","reaction":["That''s the thing. I do. I never said it. Twenty years."]},{"id":"c","label":"Want some company tonight?","reaction":["...Yeah. I''d like that."]}],"outro":"I''m sending it. ''Quiet here without you.'' That''s all."}'::jsonb),
('MM-10','adventure_friend_mm','Intro',10,1,'{"id":"MM-10","friendId":"adventure_friend_mm","phase":"Intro","seq":10,"familiarity":"Old Friend","type":"Milestone","scene":null,"lines":["Hm. You came again. Ten times. I counted. Don''t tell anyone I counted.","Mabel read my three sentences. She cried. Then asked who wrote them. I said me. She said, ''Liar.''","...I got that on my own. Mostly.","My turn to ask. How are you and your partner? Honest."],"choices":[{"id":"a","label":"We''re good. Still learning.","reaction":["Hm. Twenty years in and I''m still learning. Come to dinner. Mabel''s been asking."]},{"id":"b","label":"We had a rough week, honestly.","reaction":["Hm. Rough weeks happen. Come by. Mabel will feed you both."]},{"id":"c","label":"Better since I started saying the small things.","reaction":["...You were listening to yourself too. Good. Dinner. Bring your partner."]}],"outro":null}'::jsonb),
('MM-P01','adventure_friend_mm','Pool',1,1,'{"id":"MM-P01","friendId":"adventure_friend_mm","phase":"Pool","seq":1,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["Mabel redid the garden. Asked what I thought. I said ''nice.'' She said ''one more word.''","I said ''nice... flowers.'' Progress."],"choices":[{"id":"a","label":"Look at you go!","reaction":["Hm. Two words. On a streak."]},{"id":"b","label":"She''s training you, huh?","reaction":["Slowly. Gently. Like a mole to a garden."]}],"outro":null}'::jsonb),
('MM-P02','adventure_friend_mm','Pool',2,1,'{"id":"MM-P02","friendId":"adventure_friend_mm","phase":"Pool","seq":2,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["Mabel hums when she cooks. Today I hummed back. Badly.","She stopped, looked at me, and kept humming. Hm."],"choices":[{"id":"a","label":"That''s so cute.","reaction":["It was a disaster. Best disaster."]},{"id":"b","label":"Did you hit the note?","reaction":["No. The note hit me."]}],"outro":null}'::jsonb),
('MM-P03','adventure_friend_mm','Pool',3,1,'{"id":"MM-P03","friendId":"adventure_friend_mm","phase":"Pool","seq":3,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["Tried to say ''I love you'' today. Got as far as ''I lo—''.","Then I sneezed. Mabel said ''bless you.'' Hm. Close one."],"choices":[{"id":"a","label":"Haha!","reaction":["Not funny. Okay, a little."]},{"id":"b","label":"You''ll get there.","reaction":["Hm. Eventually. Possibly by spring."]}],"outro":null}'::jsonb),
('MM-P04','adventure_friend_mm','Pool',4,1,'{"id":"MM-P04","friendId":"adventure_friend_mm","phase":"Pool","seq":4,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["Burrow party last night. Stood near the snacks. Mabel dragged me to dance.","Eight seconds. I counted. Longest eight seconds of my life."],"choices":[{"id":"a","label":"Eight seconds is huge!","reaction":["Hm. Don''t push it."]},{"id":"b","label":"Did you enjoy it?","reaction":["...Hm. Maybe seven of the eight."]}],"outro":null}'::jsonb),
('MM-P05','adventure_friend_mm','Pool',5,1,'{"id":"MM-P05","friendId":"adventure_friend_mm","phase":"Pool","seq":5,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["Neighbor asked my secret to twenty years. I said ''windows.''","He looked confused. I don''t blame him."],"choices":[{"id":"a","label":"That''s actually a good answer.","reaction":["Hm. It''s the only answer I''ve got."]},{"id":"b","label":"You should''ve said ''worm pie.''","reaction":["Also true. Also a secret."]}],"outro":null}'::jsonb),
('MM-P06','adventure_friend_mm','Pool',6,1,'{"id":"MM-P06","friendId":"adventure_friend_mm","phase":"Pool","seq":6,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["Mabel caught a cold. I dug a hot water channel to her bed.","She said ''this is what I love you looks like.'' ...Hm. I felt that one."],"choices":[{"id":"a","label":"Aww, Mr Mole.","reaction":["Don''t. I''ll cry into my glasses."]},{"id":"b","label":"She gets you.","reaction":["Twenty years. She''d better."]}],"outro":null}'::jsonb),
('MM-P07','adventure_friend_mm','Pool',7,1,'{"id":"MM-P07","friendId":"adventure_friend_mm","phase":"Pool","seq":7,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["Forgot to say ''good morning'' today. Just once.","Mabel noticed. She said ''you okay?'' ...I''m really going to say it tomorrow."],"choices":[{"id":"a","label":"She notices everything, huh.","reaction":["Hm. That''s the trouble. And the point."]},{"id":"b","label":"Tomorrow''s a new chance.","reaction":["Hm. Two good mornings. Make up for it."]}],"outro":null}'::jsonb),
('MM-P08','adventure_friend_mm','Pool',8,1,'{"id":"MM-P08","friendId":"adventure_friend_mm","phase":"Pool","seq":8,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["Twentieth window coming up. Thinking east side. For the sunrise.","She likes mornings. I like her liking mornings."],"choices":[{"id":"a","label":"That''s so thoughtful.","reaction":["Hm. It''s a window. But yes."]},{"id":"b","label":"Can I help dig?","reaction":["...Hm. You may hold the lantern."]}],"outro":null}'::jsonb),
('MM-P09','adventure_friend_mm','Pool',9,1,'{"id":"MM-P09","friendId":"adventure_friend_mm","phase":"Pool","seq":9,"familiarity":"Old Friend","type":"Callback","scene":null,"lines":["Still have that pebble from when we first met. On the windowsill.","Hm. Don''t ask why."],"choices":[{"id":"a","label":"Because you like it?","reaction":["...Hm. Maybe."]},{"id":"b","label":"I''m touched, Mr Mole.","reaction":["Don''t be. It''s a rock. A very good rock."]}],"outro":null}'::jsonb),
('MM-P10','adventure_friend_mm','Pool',10,1,'{"id":"MM-P10","friendId":"adventure_friend_mm","phase":"Pool","seq":10,"familiarity":"Old Friend","type":"Callback","scene":null,"lines":["Mabel keeps my three sentences in her apron pocket.","She reads them while she cooks. Thinks I don''t know."],"choices":[{"id":"a","label":"That''s so sweet.","reaction":["Hm. I''m not supposed to know. Act surprised."]},{"id":"b","label":"You should write more.","reaction":["...Hm. I have six. In a drawer."]}],"outro":null}'::jsonb),
('MM-P11','adventure_friend_mm','Pool',11,1,'{"id":"MM-P11","friendId":"adventure_friend_mm","phase":"Pool","seq":11,"familiarity":"Old Friend","type":"Callback","scene":null,"lines":["Nice apron. Said it again today. Mabel said ''thank you.''","No laughing. No crying. Just ''thank you.'' Hm. Growth."],"choices":[{"id":"a","label":"Look at you!","reaction":["Hm. A man of few words and some compliments."]},{"id":"b","label":"Was she smiling?","reaction":["...Yes. Hm. I''ll take it."]}],"outro":null}'::jsonb),
('MM-P12','adventure_friend_mm','Pool',12,1,'{"id":"MM-P12","friendId":"adventure_friend_mm","phase":"Pool","seq":12,"familiarity":"Old Friend","type":"Callback","scene":null,"lines":["Still setting two cups. Even when she''s home. Old habit.","Hm. Good habit."],"choices":[{"id":"a","label":"Good habit.","reaction":["Hm. Agreed."]},{"id":"b","label":"Does she notice?","reaction":["Every time. Never says anything. Hm."]}],"outro":null}'::jsonb),
('MM-P13','adventure_friend_mm','Pool',13,1,'{"id":"MM-P13","friendId":"adventure_friend_mm","phase":"Pool","seq":13,"familiarity":"Old Friend","type":"HotTake","scene":null,"lines":["Hot take. The best love language is a well-ventilated tunnel."],"choices":[{"id":"a","label":"Okay, that''s a vibe.","reaction":["Thank you. Finally."]},{"id":"b","label":"Haha, what?","reaction":["Hm. I''m serious."]}],"outro":null}'::jsonb),
('MM-P14','adventure_friend_mm','Pool',14,1,'{"id":"MM-P14","friendId":"adventure_friend_mm","phase":"Pool","seq":14,"familiarity":"Old Friend","type":"HotTake","scene":null,"lines":["Hot take. Twenty years isn''t about big love. It''s about not leaving dishes."],"choices":[{"id":"a","label":"That''s so real.","reaction":["Hm. Dishes are love."]},{"id":"b","label":"Okay but also big love.","reaction":["Hm. Fine. Both."]}],"outro":null}'::jsonb),
('MM-P15','adventure_friend_mm','Pool',15,1,'{"id":"MM-P15","friendId":"adventure_friend_mm","phase":"Pool","seq":15,"familiarity":"Old Friend","type":"HotTake","scene":null,"lines":["Hot take. Nobody''s good at being loved. We just get better."],"choices":[{"id":"a","label":"Wow. Okay.","reaction":["Hm. Shouldn''t have said it out loud."]},{"id":"b","label":"Pretty deep, Mr Mole.","reaction":["Don''t tell Mabel. She''ll expect it daily."]}],"outro":null}'::jsonb),
('MM-P16','adventure_friend_mm','Pool',16,1,'{"id":"MM-P16","friendId":"adventure_friend_mm","phase":"Pool","seq":16,"familiarity":"Old Friend","type":"AskBack","scene":null,"lines":["You look lighter today.","Good day with your partner?"],"choices":[{"id":"a","label":"Really good, actually.","reaction":["Hm. Hold on to that."]},{"id":"b","label":"It''s been a long week.","reaction":["Hm. Sit. I''ll dig a bench."]}],"outro":null}'::jsonb),
('MM-P17','adventure_friend_mm','Pool',17,1,'{"id":"MM-P17","friendId":"adventure_friend_mm","phase":"Pool","seq":17,"familiarity":"Old Friend","type":"AskBack","scene":null,"lines":["Hm. When did you last say something nice to your partner? Out loud?","No pressure. Asking for a mole."],"choices":[{"id":"a","label":"This morning, actually.","reaction":["Hm. Good. You''re better at it than me."]},{"id":"b","label":"...Probably too long.","reaction":["Hm. Today, then. Short is fine."]}],"outro":null}'::jsonb),
('MM-P18','adventure_friend_mm','Pool',18,1,'{"id":"MM-P18","friendId":"adventure_friend_mm","phase":"Pool","seq":18,"familiarity":"Old Friend","type":"AskBack","scene":null,"lines":["Hm. What''s the dumbest thing that makes your partner laugh?","I''m collecting data."],"choices":[{"id":"a","label":"My terrible puns.","reaction":["Terrible puns. Noted. Hm."]},{"id":"b","label":"When I trip over nothing.","reaction":["I can''t trip on purpose. I''ve tried."]}],"outro":null}'::jsonb),
('MM-P19','adventure_friend_mm','Pool',19,0.25,'{"id":"MM-P19","friendId":"adventure_friend_mm","phase":"Pool","seq":19,"familiarity":"Old Friend","type":"Rare","scene":"Dinner at Mr Mole and Mabel''s. Candlelight. Mabel hums.","lines":["Hm. She''s been humming for three hours. It''s your fault.","Don''t stop coming."],"choices":[{"id":"a","label":"I won''t.","reaction":["Hm. Good."]},{"id":"b","label":"Smile quietly","reaction":["...That works too."]}],"outro":null}'::jsonb),
('MM-P20','adventure_friend_mm','Pool',20,0.25,'{"id":"MM-P20","friendId":"adventure_friend_mm","phase":"Pool","seq":20,"familiarity":"Old Friend","type":"Rare","scene":"Mr Mole leads you to the top of his tunnel at dusk.","lines":["Roof. Mine. You can stand on it now.","View''s not bad."],"choices":[{"id":"a","label":"It''s beautiful.","reaction":["Hm. Thought so. Twenty years, still looking at it."]},{"id":"b","label":"Sit down next to him","reaction":["...Hm. Nice."]}],"outro":null}'::jsonb)
