insert into public.friend_definitions(stable_id,revision_id,name,subtitle,art,metadata,is_placeholder) values('adventure_friend_pk',coalesce((select value from public.app_config where key='app_major_update_content_revision'),'burrow-v1-placeholder'),'Pickles','I''m FINE.','{"renderer":"bundled","key":"Hedgehog"}'::jsonb,'{"adventureV2":true,"code":"PK","gender":"she","species":"Hedgehog"}'::jsonb,false) on conflict(stable_id) do update set name=excluded.name,subtitle=excluded.subtitle,art=excluded.art,metadata=excluded.metadata,status='active',updated_at=now();
insert into public.adventure_dialogues_v2(id,friend_id,phase,seq,weight,content) values
('PK-01','adventure_friend_pk','Intro',1,1,'{"id":"PK-01","friendId":"adventure_friend_pk","phase":"Intro","seq":1,"familiarity":"Stranger","type":"Statement","scene":"A hedgehog stands very still, spikes slightly up.","lines":["Don''t touch. I''m not mad. I''m just... spiky.","It''s a lot. I know."],"choices":[{"id":"a","label":"Noted. No touching.","reaction":["Thank you. Finally someone gets it."]},{"id":"b","label":"I like your spikes.","reaction":["...You do? Weird. I''m Pickles."]},{"id":"c","label":"Are you okay?","reaction":["I''m FINE."]}],"outro":null}'::jsonb),
('PK-02','adventure_friend_pk','Intro',2,1,'{"id":"PK-02","friendId":"adventure_friend_pk","phase":"Intro","seq":2,"familiarity":"Familiar Face","type":"Statement","scene":null,"lines":["I''ve been hugging a pillow for a week.","Practicing. Without poking. It''s not working. I''ve gone through four pillows."],"choices":[{"id":"a","label":"Why the practice?","reaction":["...No reason. A boy. Maybe. I don''t want to talk about it."]},{"id":"b","label":"Four pillows? Respect.","reaction":["Thank you. I''m committed."]},{"id":"c","label":"Want some tips?","reaction":["No. Yes. Maybe. I''m FINE."]}],"outro":null}'::jsonb),
('PK-03','adventure_friend_pk','Intro',3,1,'{"id":"PK-03","friendId":"adventure_friend_pk","phase":"Intro","seq":3,"familiarity":"Acquaintance","type":"Statement","scene":null,"lines":["He showed up wearing oven mitts.","Basil. The boy. He said ''now I can hug you.'' ...I laughed so hard I spiked a leaf."],"choices":[{"id":"a","label":"That''s actually adorable.","reaction":["I KNOW. Stop. I''m blushing. Under the spikes."]},{"id":"b","label":"Did you hug him?","reaction":["...Yes. Mitten hug. Best hug."]},{"id":"c","label":"He sounds like a keeper.","reaction":["Hm. Don''t say that. I''ll start believing it."]}],"outro":null}'::jsonb),
('PK-04','adventure_friend_pk','Intro',4,1,'{"id":"PK-04","friendId":"adventure_friend_pk","phase":"Intro","seq":4,"familiarity":"Acquaintance","type":"Statement","scene":null,"lines":["We have a handshake now. Seven steps. It''s dumb.","I do it every day. Don''t tell him it''s my favorite part of the day."],"choices":[{"id":"a","label":"It''s not dumb.","reaction":["It''s SO dumb. I love it."]},{"id":"b","label":"Show me!","reaction":["Okay. Step one. ...Never mind, I''m shy."]},{"id":"c","label":"You''re so in love.","reaction":["I''m FINE. ...Yes."]}],"outro":null}'::jsonb),
('PK-05','adventure_friend_pk','Intro',5,1,'{"id":"PK-05","friendId":"adventure_friend_pk","phase":"Intro","seq":5,"familiarity":"Friend","type":"Ask","scene":null,"lines":["It''s our one-month. Basil forgot.","I said ''it''s fine.'' He said ''okay cool!'' and went to nap. It''s NOT fine.","How do you tell someone you''re upset without it becoming a fight?"],"choices":[{"id":"a","label":"Say ''I felt sad'' instead of ''you messed up.''","reaction":["''I felt sad.'' Huh. That''s way less scary."]},{"id":"b","label":"Maybe a small hint? He might just be oblivious.","reaction":["Oblivious. Yes. That''s Basil. A very sweet rock."]},{"id":"c","label":"Honestly, I''m still figuring that out.","reaction":["Wait, REALLY? Okay. I feel better."]}],"outro":null}'::jsonb),
('PK-06','adventure_friend_pk','Intro',6,1,'{"id":"PK-06","friendId":"adventure_friend_pk","phase":"Intro","seq":6,"familiarity":"Friend","type":"Statement","scene":null,"lines":["I texted him ''k.'' Just ''k.''","He sent back three hearts and a sunflower. I''ve been staring at my phone for two hours.","He''s too nice for me."],"choices":[{"id":"a","label":"He knows you''re you.","reaction":["Does he? ...I hope so."]},{"id":"b","label":"That''s a lot of hearts.","reaction":["It IS. I screenshotted it."]},{"id":"c","label":"Text him something longer?","reaction":["...Okay. Okay. I''ll try. I have a word. ''Hi.''"]}],"outro":null}'::jsonb),
('PK-07','adventure_friend_pk','Intro',7,1,'{"id":"PK-07","friendId":"adventure_friend_pk","phase":"Intro","seq":7,"familiarity":"Close Friend","type":"Confide","scene":"Pickles sits with spikes flat, which is rare.","lines":["Can I say a thing?","What if Basil finds out I''m a lot? Like... really a lot.","I''m loud and prickly and I overthink. He''s so calm."],"choices":[{"id":"a","label":"He picked you for a reason.","reaction":["Hm. Maybe. I just want to deserve it."]},{"id":"b","label":"Tell him a little of it. Test it.","reaction":["A ''little'' lot. That''s a plan. Thank you."]},{"id":"c","label":"Sit next to her","reaction":["...You''re good at this."]}],"outro":null}'::jsonb),
('PK-08','adventure_friend_pk','Intro',8,1,'{"id":"PK-08","friendId":"adventure_friend_pk","phase":"Intro","seq":8,"familiarity":"Close Friend","type":"Statement","scene":null,"lines":["I said ''I''m sad'' to Basil today. Not ''I''m fine.''","He put his oven mitts on and hugged me for ten minutes.","I think I''m learning."],"choices":[{"id":"a","label":"That''s huge.","reaction":["I know. Don''t make me cry."]},{"id":"b","label":"Ten-minute hug? Wow.","reaction":["I timed it. Best ten minutes."]},{"id":"c","label":"Proud of you.","reaction":["...Shush. Okay. Thank you."]}],"outro":null}'::jsonb),
('PK-09','adventure_friend_pk','Intro',9,1,'{"id":"PK-09","friendId":"adventure_friend_pk","phase":"Intro","seq":9,"familiarity":"Best Friend","type":"Companion","scene":null,"lines":["Basil''s sick. He told me not to come.","I''m standing outside his burrow with soup. Not going in. Just... standing.","I said I was ''passing by.'' I''m not passing by."],"choices":[{"id":"a","label":"Knock softly.","reaction":["...Okay. I''ll knock. Softly."]},{"id":"b","label":"Leave the soup at the door.","reaction":["That''s a good idea. Soup. Door. Love."]},{"id":"c","label":"Stand next to her","reaction":["...Thanks. I wasn''t sure I could do it alone."]}],"outro":null}'::jsonb),
('PK-10','adventure_friend_pk','Intro',10,1,'{"id":"PK-10","friendId":"adventure_friend_pk","phase":"Intro","seq":10,"familiarity":"Old Friend","type":"Milestone","scene":null,"lines":["Okay. Spikes down. Look.","Ten visits. You''ve seen me at my worst. I think we''re friends now.","Basil wants to meet you. I told him you''re the only one who didn''t run.","...How are you and your partner? Real answer."],"choices":[{"id":"a","label":"We''re good. Still figuring it out.","reaction":["Same. Always. Come to our picnic."]},{"id":"b","label":"Some good days, some rough ones.","reaction":["Same. Bring snacks. Bring your partner."]},{"id":"c","label":"Honestly, you''ve helped me say stuff more.","reaction":["...Don''t. I''ll cry. Okay. Picnic. Sunday."]}],"outro":null}'::jsonb),
('PK-P01','adventure_friend_pk','Pool',1,1,'{"id":"PK-P01","friendId":"adventure_friend_pk","phase":"Pool","seq":1,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["Basil made leaf armor for our hug. Full armor. Helmet.","He looked ridiculous. I''m keeping the picture."],"choices":[{"id":"a","label":"That''s the sweetest thing.","reaction":["It''s the dumbest thing. Same thing."]},{"id":"b","label":"Can I see the picture?","reaction":["No. It''s mine. ...Okay, a peek."]}],"outro":null}'::jsonb),
('PK-P02','adventure_friend_pk','Pool',2,1,'{"id":"PK-P02","friendId":"adventure_friend_pk","phase":"Pool","seq":2,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["Said ''I''m sad'' instead of ''I''m fine'' today. Nothing exploded.","Huh."],"choices":[{"id":"a","label":"Told you.","reaction":["Okay. You did. Don''t be smug."]},{"id":"b","label":"What happened after?","reaction":["He just sat with me. That''s it. It was enough."]}],"outro":null}'::jsonb),
('PK-P03','adventure_friend_pk','Pool',3,1,'{"id":"PK-P03","friendId":"adventure_friend_pk","phase":"Pool","seq":3,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["We fought about the blanket. He steals it. I steal it back.","Then we shared. It was warm. I was mad about it."],"choices":[{"id":"a","label":"Blanket politics.","reaction":["The worst politics."]},{"id":"b","label":"That''s so couple.","reaction":["I KNOW. Gross. Love it."]}],"outro":null}'::jsonb),
('PK-P04','adventure_friend_pk','Pool',4,1,'{"id":"PK-P04","friendId":"adventure_friend_pk","phase":"Pool","seq":4,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["Basil''s friends think I''m scary. I was nice for three minutes.","Three. Minutes. I''m exhausted."],"choices":[{"id":"a","label":"Three minutes is a lot!","reaction":["I know! Nobody gives me credit."]},{"id":"b","label":"Were they nice back?","reaction":["Yes. Annoyingly. I might like them."]}],"outro":null}'::jsonb),
('PK-P05','adventure_friend_pk','Pool',5,1,'{"id":"PK-P05","friendId":"adventure_friend_pk","phase":"Pool","seq":5,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["A squirrel keeps texting Basil. ''Hey!!'' with two exclamation points.","I''m not jealous. I''m just... aware."],"choices":[{"id":"a","label":"Ask him about it?","reaction":["I will. Calmly. With a sandwich."]},{"id":"b","label":"Aware is fine.","reaction":["Aware is my default setting."]}],"outro":null}'::jsonb),
('PK-P06','adventure_friend_pk','Pool',6,1,'{"id":"PK-P06","friendId":"adventure_friend_pk","phase":"Pool","seq":6,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["We have matching nicknames now. Don''t ask. Don''t tell."],"choices":[{"id":"a","label":"I won''t tell.","reaction":["Good. They''re ''Spike'' and ''Mitt.'' ...I said don''t ask."]},{"id":"b","label":"Mitt is perfect.","reaction":["I KNOW. He''s so proud."]}],"outro":null}'::jsonb),
('PK-P07','adventure_friend_pk','Pool',7,1,'{"id":"PK-P07","friendId":"adventure_friend_pk","phase":"Pool","seq":7,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["Bought Basil a gift. Hid it for four days.","I''m scared he won''t like it. It''s a scarf. It''s not that deep."],"choices":[{"id":"a","label":"Give it to him!","reaction":["Okay. Tomorrow. Maybe."]},{"id":"b","label":"He''ll love it.","reaction":["You think? ...Okay. Okay."]}],"outro":null}'::jsonb),
('PK-P08','adventure_friend_pk','Pool',8,1,'{"id":"PK-P08","friendId":"adventure_friend_pk","phase":"Pool","seq":8,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["Bad day. Didn''t say anything. Basil came over, sat next to me, said nothing.","That was it. That was the whole thing."],"choices":[{"id":"a","label":"That''s love.","reaction":["I know. It''s annoying how good he is."]},{"id":"b","label":"Sometimes silence is the answer.","reaction":["Okay, wise one."]}],"outro":null}'::jsonb),
('PK-P09','adventure_friend_pk','Pool',9,1,'{"id":"PK-P09","friendId":"adventure_friend_pk","phase":"Pool","seq":9,"familiarity":"Old Friend","type":"Callback","scene":null,"lines":["Still have all four pillows. They''re my ''hug practice'' wall now."],"choices":[{"id":"a","label":"Keep them!","reaction":["Obviously. They''re my trophies."]},{"id":"b","label":"You don''t need them.","reaction":["I know. I''m sentimental. Don''t tell anyone."]}],"outro":null}'::jsonb),
('PK-P10','adventure_friend_pk','Pool',10,1,'{"id":"PK-P10","friendId":"adventure_friend_pk","phase":"Pool","seq":10,"familiarity":"Old Friend","type":"Callback","scene":null,"lines":["Basil still wears the oven mitts sometimes. Out of habit.","I don''t mind. I kind of like the mitten hug."],"choices":[{"id":"a","label":"That''s love.","reaction":["Dumb love. Best love."]},{"id":"b","label":"Make it a tradition.","reaction":["It already is."]}],"outro":null}'::jsonb),
('PK-P11','adventure_friend_pk','Pool',11,1,'{"id":"PK-P11","friendId":"adventure_friend_pk","phase":"Pool","seq":11,"familiarity":"Old Friend","type":"Callback","scene":null,"lines":["That ''k'' text. He still has it saved. He said ''it was your first one.''","I''m fine. I''m FINE."],"choices":[{"id":"a","label":"He kept it? Aww.","reaction":["SO dumb. SO sweet."]},{"id":"b","label":"He''s a keeper.","reaction":["Don''t say it. I''ll say it."]}],"outro":null}'::jsonb),
('PK-P12','adventure_friend_pk','Pool',12,1,'{"id":"PK-P12","friendId":"adventure_friend_pk","phase":"Pool","seq":12,"familiarity":"Old Friend","type":"Callback","scene":null,"lines":["Our one-month anniversary. We redid it. A month late. With a sunflower.","Best anniversary. Worst anniversary. Both."],"choices":[{"id":"a","label":"Better late.","reaction":["Always."]},{"id":"b","label":"Did he remember this time?","reaction":["He wrote it on his hand."]}],"outro":null}'::jsonb),
('PK-P13','adventure_friend_pk','Pool',13,1,'{"id":"PK-P13","friendId":"adventure_friend_pk","phase":"Pool","seq":13,"familiarity":"Old Friend","type":"HotTake","scene":null,"lines":["Hot take. A good partner makes you softer but not smaller."],"choices":[{"id":"a","label":"That''s so true.","reaction":["Don''t compliment my hot take. I''m not ready."]},{"id":"b","label":"That''s deep, Pickles.","reaction":["I''m FINE. Thank you."]}],"outro":null}'::jsonb),
('PK-P14','adventure_friend_pk','Pool',14,1,'{"id":"PK-P14","friendId":"adventure_friend_pk","phase":"Pool","seq":14,"familiarity":"Old Friend","type":"HotTake","scene":null,"lines":["Hot take. ''I''m fine'' should be illegal."],"choices":[{"id":"a","label":"Honestly yes.","reaction":["Right? Everyone lies."]},{"id":"b","label":"Haha, okay.","reaction":["I''m serious. Fine me."]}],"outro":null}'::jsonb),
('PK-P15','adventure_friend_pk','Pool',15,1,'{"id":"PK-P15","friendId":"adventure_friend_pk","phase":"Pool","seq":15,"familiarity":"Old Friend","type":"HotTake","scene":null,"lines":["Hot take. Love is just being a prickly person next to a patient person."],"choices":[{"id":"a","label":"That''s actually accurate.","reaction":["I''ll put it on a mug."]},{"id":"b","label":"Which one are you?","reaction":["...Obviously prickly. Obviously."]}],"outro":null}'::jsonb),
('PK-P16','adventure_friend_pk','Pool',16,1,'{"id":"PK-P16","friendId":"adventure_friend_pk","phase":"Pool","seq":16,"familiarity":"Old Friend","type":"AskBack","scene":null,"lines":["Okay. What''s the nicest thing your partner did this week?","I need ideas. Not for me. Just ideas."],"choices":[{"id":"a","label":"They made me tea when I was tired.","reaction":["Tea. Noted. For a friend."]},{"id":"b","label":"They sent me a random ''miss you.''","reaction":["''Miss you.'' Two words. I can do two words."]}],"outro":null}'::jsonb),
('PK-P17','adventure_friend_pk','Pool',17,1,'{"id":"PK-P17","friendId":"adventure_friend_pk","phase":"Pool","seq":17,"familiarity":"Old Friend","type":"AskBack","scene":null,"lines":["Are you being soft with your partner? Like, really soft?","I''m asking for a friend. The friend is me."],"choices":[{"id":"a","label":"Trying to.","reaction":["Same. We should have a support group."]},{"id":"b","label":"Not always.","reaction":["Honest. Respect."]}],"outro":null}'::jsonb),
('PK-P18','adventure_friend_pk','Pool',18,1,'{"id":"PK-P18","friendId":"adventure_friend_pk","phase":"Pool","seq":18,"familiarity":"Old Friend","type":"AskBack","scene":null,"lines":["How do you two fight? Like... who starts, who ends?"],"choices":[{"id":"a","label":"I usually go quiet.","reaction":["Ooh. That''s me too. Hm. Interesting."]},{"id":"b","label":"We both say sorry at the same time.","reaction":["...That''s adorable. I hate it. I love it."]}],"outro":null}'::jsonb),
('PK-P19','adventure_friend_pk','Pool',19,0.25,'{"id":"PK-P19","friendId":"adventure_friend_pk","phase":"Pool","seq":19,"familiarity":"Old Friend","type":"Rare","scene":"Pickles flattens her spikes slowly.","lines":["Okay. One hug. Just one. Don''t make it weird."],"choices":[{"id":"a","label":"Hug her gently","reaction":["...Okay. That was nice. ONE. Don''t tell anyone."]},{"id":"b","label":"I''m good, thanks.","reaction":["...You''re good at respecting boundaries. I might hug you anyway."]}],"outro":null}'::jsonb),
('PK-P20','adventure_friend_pk','Pool',20,0.25,'{"id":"PK-P20","friendId":"adventure_friend_pk","phase":"Pool","seq":20,"familiarity":"Old Friend","type":"Rare","scene":"Pickles and Basil have laid out a picnic. Basil''s wearing oven mitts.","lines":["Basil, this is my friend. The one I told you about.","Be nice."],"choices":[{"id":"a","label":"Hi Basil!","reaction":["Basil waves with a mitten. Hi! I''ve heard so much."]},{"id":"b","label":"Wave with both paws","reaction":["Basil waves back with both mittens. Hi! Welcome to the mitten club."]}],"outro":null}'::jsonb)
