insert into public.friend_definitions(stable_id,revision_id,name,subtitle,art,metadata,is_placeholder) values('adventure_friend_tw',coalesce((select value from public.app_config where key='app_major_update_content_revision'),'burrow-v1-placeholder'),'Twig','Nice weather.','{"renderer":"bundled","key":"Mouse"}'::jsonb,'{"adventureV2":true,"code":"TW","gender":"she","species":"Mouse"}'::jsonb,false) on conflict(stable_id) do update set name=excluded.name,subtitle=excluded.subtitle,art=excluded.art,metadata=excluded.metadata,status='active',updated_at=now();
insert into public.adventure_dialogues_v2(id,friend_id,phase,seq,weight,content) values
('TW-01','adventure_friend_tw','Intro',1,1,'{"id":"TW-01","friendId":"adventure_friend_tw","phase":"Intro","seq":1,"familiarity":"Stranger","type":"Statement","scene":"A tiny mouse dashes out, skids, stops.","lines":["Hi! Sorry! I was thinking. I do that. A lot.","Do I know you? I don''t think I know you. Hi."],"choices":[{"id":"a","label":"Hi! I''m new.","reaction":["New! Great! I''m Twig. I overthink. Nice to meet you."]},{"id":"b","label":"You okay?","reaction":["Totally! Mostly! Slightly spiraling. It''s fine."]},{"id":"c","label":"Slow down.","reaction":["Can''t. Brain''s too fast. But thanks."]}],"outro":null}'::jsonb),
('TW-02','adventure_friend_tw','Intro',2,1,'{"id":"TW-02","friendId":"adventure_friend_tw","phase":"Intro","seq":2,"familiarity":"Familiar Face","type":"Statement","scene":null,"lines":["I know someone''s schedule. Not in a creepy way.","He goes to the berry stand at 3. I also go at 3. By coincidence. Every day."],"choices":[{"id":"a","label":"That''s definitely coincidence.","reaction":["RIGHT. Thank you. Someone gets it."]},{"id":"b","label":"Bold of you.","reaction":["Is it? Is it bold? I thought it was subtle."]},{"id":"c","label":"Does the person know?","reaction":["Absolutely not. I''d die."]}],"outro":null}'::jsonb),
('TW-03','adventure_friend_tw','Intro',3,1,'{"id":"TW-03","friendId":"adventure_friend_tw","phase":"Intro","seq":3,"familiarity":"Acquaintance","type":"Statement","scene":null,"lines":["Sage said ''hi'' to me today.","Just ''hi.'' One syllable. I''ve been analyzing it for three hours."],"choices":[{"id":"a","label":"Maybe it was just ''hi.''","reaction":["Nothing is ''just.'' It had a TONE."]},{"id":"b","label":"What tone?","reaction":["Warm. Slightly curious. 70% friendly, 30% maybe."]},{"id":"c","label":"Did you say hi back?","reaction":["I said ''ha.'' I don''t know why."]}],"outro":null}'::jsonb),
('TW-04','adventure_friend_tw','Intro',4,1,'{"id":"TW-04","friendId":"adventure_friend_tw","phase":"Intro","seq":4,"familiarity":"Acquaintance","type":"Statement","scene":null,"lines":["I wrote eleven drafts of a confession.","Draft three was too intense. Draft seven was just ''hey.'' Draft eleven was a poem about cheese."],"choices":[{"id":"a","label":"Poem about cheese?!","reaction":["It was surprisingly romantic."]},{"id":"b","label":"Which one''s your favorite?","reaction":["Five. It said ''I like talking to you.'' Which is true. And scary."]},{"id":"c","label":"Maybe skip the drafts and wing it?","reaction":["Wing it. Hah. Ha. Hah. No."]}],"outro":null}'::jsonb),
('TW-05','adventure_friend_tw','Intro',5,1,'{"id":"TW-05","friendId":"adventure_friend_tw","phase":"Intro","seq":5,"familiarity":"Friend","type":"Ask","scene":null,"lines":["Okay. Real question.","How did you tell your partner you liked them? Like, the first time?","I need data. Not advice. Data."],"choices":[{"id":"a","label":"I just said it. It was awkward.","reaction":["Awkward. Okay. I can do awkward."]},{"id":"b","label":"Honestly, it kind of happened slowly.","reaction":["Slowly. Hm. That''s less scary."]},{"id":"c","label":"I wrote them a note.","reaction":["A NOTE. Drafts are my specialty."]}],"outro":null}'::jsonb),
('TW-06','adventure_friend_tw','Intro',6,1,'{"id":"TW-06","friendId":"adventure_friend_tw","phase":"Intro","seq":6,"familiarity":"Friend","type":"Statement","scene":null,"lines":["I almost talked to Sage today. Like, really almost.","I said ''nice weather.'' It was raining. Sage said ''it IS nice weather.'' ...I don''t know what happened."],"choices":[{"id":"a","label":"That''s kind of sweet.","reaction":["Sweet?! Okay. Okay. Sweet. I can work with sweet."]},{"id":"b","label":"Sage went along with it!","reaction":["HE DID. I''m a genius. Accidentally."]},{"id":"c","label":"Next time, say one more word.","reaction":["One more. Okay. ''Nice weather. And you.''"]}],"outro":null}'::jsonb),
('TW-07','adventure_friend_tw','Intro',7,1,'{"id":"TW-07","friendId":"adventure_friend_tw","phase":"Intro","seq":7,"familiarity":"Close Friend","type":"Confide","scene":"Twig sits quietly, for once.","lines":["What if I say it and he says no?","And then I can''t go to the berry stand ever again. Berries are my whole thing."],"choices":[{"id":"a","label":"Berries aren''t going anywhere.","reaction":["True. True. Okay. I''ll keep the berries."]},{"id":"b","label":"It''s okay to be scared.","reaction":["...Thanks. I needed someone to say that."]},{"id":"c","label":"Sit beside Twig","reaction":["...Thank you. It''s weirdly calming."]}],"outro":null}'::jsonb),
('TW-08','adventure_friend_tw','Intro',8,1,'{"id":"TW-08","friendId":"adventure_friend_tw","phase":"Intro","seq":8,"familiarity":"Close Friend","type":"Statement","scene":null,"lines":["I left a berry on Sage''s step today. Anonymous.","Just a berry. No note. Just a red berry.","Now I''m hiding behind a leaf."],"choices":[{"id":"a","label":"Stay hidden.","reaction":["I''m very good at hiding. It''s my second best skill."]},{"id":"b","label":"They''ll love it.","reaction":["Do you think? Do you REALLY think?"]},{"id":"c","label":"What''s the first skill?","reaction":["Overthinking. Obviously."]}],"outro":null}'::jsonb),
('TW-09','adventure_friend_tw','Intro',9,1,'{"id":"TW-09","friendId":"adventure_friend_tw","phase":"Intro","seq":9,"familiarity":"Best Friend","type":"Companion","scene":null,"lines":["Sage saw me. Saw me leave the berry.","He said ''I recognized the handwriting.'' I said ''berries don''t have handwriting.'' He smiled.","I think my heart left my body."],"choices":[{"id":"a","label":"That''s a smile!","reaction":["It was a good smile. I analyzed it. 85% good."]},{"id":"b","label":"What did you say?","reaction":["I said ''ha.'' Again. It''s a problem."]},{"id":"c","label":"Grin quietly","reaction":["...Don''t. I''ll scream. Quietly."]}],"outro":null}'::jsonb),
('TW-10','adventure_friend_tw','Intro',10,1,'{"id":"TW-10","friendId":"adventure_friend_tw","phase":"Intro","seq":10,"familiarity":"Old Friend","type":"Milestone","scene":null,"lines":["Okay. Ten visits. I owe you a real update.","Sage asked if I wanted to walk with him tomorrow. Just walk. No agenda.","I said yes. I said it normally. I don''t know how.","...How are you and your partner? Seriously. Tell me."],"choices":[{"id":"a","label":"We''re good. Still learning.","reaction":["Learning. I love that. I''ll learn too."]},{"id":"b","label":"Honestly, a lot of nervous energy still.","reaction":["SAME. We should start a club."]},{"id":"c","label":"I''m really happy, honestly.","reaction":["Honestly?? That''s the best news. I''m going to cry in a leaf."]}],"outro":null}'::jsonb),
('TW-P01','adventure_friend_tw','Pool',1,1,'{"id":"TW-P01","friendId":"adventure_friend_tw","phase":"Pool","seq":1,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["Sage said ''see you tomorrow.'' Which implies there''s a tomorrow.","I''ve been thinking about that for two hours."],"choices":[{"id":"a","label":"That''s a good sign.","reaction":["Right?? Okay. I''ll take it."]},{"id":"b","label":"It might just be polite.","reaction":["Polite. Hm. Polite is a type of nice."]}],"outro":null}'::jsonb),
('TW-P02','adventure_friend_tw','Pool',2,1,'{"id":"TW-P02","friendId":"adventure_friend_tw","phase":"Pool","seq":2,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["We walked together for twelve minutes.","I counted. I think we''re friends. Or something. Or friends-plus-minus."],"choices":[{"id":"a","label":"Plus!","reaction":["Don''t say plus. I''ll start believing it."]},{"id":"b","label":"Twelve minutes is great.","reaction":["It was! I almost said a full sentence."]}],"outro":null}'::jsonb),
('TW-P03','adventure_friend_tw','Pool',3,1,'{"id":"TW-P03","friendId":"adventure_friend_tw","phase":"Pool","seq":3,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["Sage laughed at my joke today.","It wasn''t even a good joke. It was about cheese. I think it was a good laugh."],"choices":[{"id":"a","label":"Cheese jokes are underrated.","reaction":["THANK YOU."]},{"id":"b","label":"That''s cute.","reaction":["It WAS."]}],"outro":null}'::jsonb),
('TW-P04','adventure_friend_tw','Pool',4,1,'{"id":"TW-P04","friendId":"adventure_friend_tw","phase":"Pool","seq":4,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["Saw Sage with another mouse. I panicked.","It was his cousin. I know because I asked. Very casually. In a voice I''ve never used."],"choices":[{"id":"a","label":"Relief?","reaction":["Huge. I need to lie down."]},{"id":"b","label":"You asked casually, right?","reaction":["I asked like a detective."]}],"outro":null}'::jsonb),
('TW-P05','adventure_friend_tw','Pool',5,1,'{"id":"TW-P05","friendId":"adventure_friend_tw","phase":"Pool","seq":5,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["Sage texted me at 11 PM. ''Do you have the notes?''","That''s it. But it was 11 PM. Which means he thought of me at 11 PM."],"choices":[{"id":"a","label":"They thought of you.","reaction":["HE DID."]},{"id":"b","label":"Did you send the notes?","reaction":["In six seconds. I''m not proud."]}],"outro":null}'::jsonb),
('TW-P06','adventure_friend_tw','Pool',6,1,'{"id":"TW-P06","friendId":"adventure_friend_tw","phase":"Pool","seq":6,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["Rehearsed ''hi'' in the mirror for ten minutes. It still came out wrong."],"choices":[{"id":"a","label":"Hi is hard.","reaction":["Hi is the hardest word."]},{"id":"b","label":"Say it to me.","reaction":["Okay. Hi. ...That was fine. Why was that fine?"]}],"outro":null}'::jsonb),
('TW-P07','adventure_friend_tw','Pool',7,1,'{"id":"TW-P07","friendId":"adventure_friend_tw","phase":"Pool","seq":7,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["Sage borrowed my scarf. Still hasn''t returned it.","I don''t want it back. Is that weird?"],"choices":[{"id":"a","label":"Not weird.","reaction":["Okay. Okay. I''ll let it live there."]},{"id":"b","label":"Ask for it. Gently.","reaction":["Gently. Hm. A reason to talk. Genius."]}],"outro":null}'::jsonb),
('TW-P08','adventure_friend_tw','Pool',8,1,'{"id":"TW-P08","friendId":"adventure_friend_tw","phase":"Pool","seq":8,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["Sage said I have ''good energy.'' What does that MEAN.","Is it romantic? Is it friend? Is it ''you smell nice''?"],"choices":[{"id":"a","label":"It''s a compliment!","reaction":["A compliment. Yes. I''ll frame it."]},{"id":"b","label":"Ask them what they meant.","reaction":["ASK. Hah. Hahaha. ...Maybe."]}],"outro":null}'::jsonb),
('TW-P09','adventure_friend_tw','Pool',9,1,'{"id":"TW-P09","friendId":"adventure_friend_tw","phase":"Pool","seq":9,"familiarity":"Old Friend","type":"Callback","scene":null,"lines":["Still have all eleven drafts. In a box.","Someday I''ll read them all out loud. To a wall."],"choices":[{"id":"a","label":"Read me draft seven.","reaction":["''Hey.'' ...That''s it. That''s the draft."]},{"id":"b","label":"Keep them forever.","reaction":["Obviously."]}],"outro":null}'::jsonb),
('TW-P10','adventure_friend_tw','Pool',10,1,'{"id":"TW-P10","friendId":"adventure_friend_tw","phase":"Pool","seq":10,"familiarity":"Old Friend","type":"Callback","scene":null,"lines":["Sage said he ''knew the handwriting.'' I still think about that.","He noticed me noticing him."],"choices":[{"id":"a","label":"They noticed you.","reaction":["I KNOW."]},{"id":"b","label":"That''s so sweet.","reaction":["I think I''m going to be okay."]}],"outro":null}'::jsonb),
('TW-P11','adventure_friend_tw','Pool',11,1,'{"id":"TW-P11","friendId":"adventure_friend_tw","phase":"Pool","seq":11,"familiarity":"Old Friend","type":"Callback","scene":null,"lines":["Remember ''nice weather''? Sage brings it up sometimes.","Like a joke between us. A joke we share. Between us."],"choices":[{"id":"a","label":"That''s a thing now!","reaction":["It''s OUR thing. Probably. Maybe."]},{"id":"b","label":"Aw.","reaction":["I''m fine. I''m okay. It''s fine."]}],"outro":null}'::jsonb),
('TW-P12','adventure_friend_tw','Pool',12,1,'{"id":"TW-P12","friendId":"adventure_friend_tw","phase":"Pool","seq":12,"familiarity":"Old Friend","type":"Callback","scene":null,"lines":["I still go to the berry stand at three.","Not because of Sage. Because of the berries. ...Mostly the berries."],"choices":[{"id":"a","label":"Mostly?","reaction":["I''m working on it."]},{"id":"b","label":"Berries are good.","reaction":["They really are."]}],"outro":null}'::jsonb),
('TW-P13','adventure_friend_tw','Pool',13,1,'{"id":"TW-P13","friendId":"adventure_friend_tw","phase":"Pool","seq":13,"familiarity":"Old Friend","type":"HotTake","scene":null,"lines":["Hot take. The scariest part of liking someone is being seen liking them."],"choices":[{"id":"a","label":"That''s so true.","reaction":["I should write that down. Draft twelve."]},{"id":"b","label":"Deep, Twig.","reaction":["Overthinking pays off sometimes."]}],"outro":null}'::jsonb),
('TW-P14','adventure_friend_tw','Pool',14,1,'{"id":"TW-P14","friendId":"adventure_friend_tw","phase":"Pool","seq":14,"familiarity":"Old Friend","type":"HotTake","scene":null,"lines":["Hot take. Crushes are just anxiety wearing a cute outfit."],"choices":[{"id":"a","label":"Haha, true.","reaction":["I''m serious. A very cute outfit."]},{"id":"b","label":"Facts.","reaction":["Thank you. I contain wisdom."]}],"outro":null}'::jsonb),
('TW-P15','adventure_friend_tw','Pool',15,1,'{"id":"TW-P15","friendId":"adventure_friend_tw","phase":"Pool","seq":15,"familiarity":"Old Friend","type":"HotTake","scene":null,"lines":["Hot take. ''Nice weather'' is the most romantic phrase in any language."],"choices":[{"id":"a","label":"Honestly, yes.","reaction":["Right?!"]},{"id":"b","label":"It was raining though.","reaction":["Details."]}],"outro":null}'::jsonb),
('TW-P16','adventure_friend_tw','Pool',16,1,'{"id":"TW-P16","friendId":"adventure_friend_tw","phase":"Pool","seq":16,"familiarity":"Old Friend","type":"AskBack","scene":null,"lines":["Be honest. Did you overthink everything when you started liking your partner?"],"choices":[{"id":"a","label":"Constantly.","reaction":["I feel so seen."]},{"id":"b","label":"Only a little.","reaction":["Teach me your ways."]}],"outro":null}'::jsonb),
('TW-P17','adventure_friend_tw','Pool',17,1,'{"id":"TW-P17","friendId":"adventure_friend_tw","phase":"Pool","seq":17,"familiarity":"Old Friend","type":"AskBack","scene":null,"lines":["What''s the best first thing to say to someone you like?","I need a script. Please."],"choices":[{"id":"a","label":"Just ask about their day.","reaction":["Their DAY. Genius. Boring. Genius."]},{"id":"b","label":"Say something true.","reaction":["True. Hm. ''I like berries.'' That''s true."]}],"outro":null}'::jsonb),
('TW-P18','adventure_friend_tw','Pool',18,1,'{"id":"TW-P18","friendId":"adventure_friend_tw","phase":"Pool","seq":18,"familiarity":"Old Friend","type":"AskBack","scene":null,"lines":["How do you know when someone likes you back?","I''m gathering evidence."],"choices":[{"id":"a","label":"They go out of their way for you.","reaction":["Oh no. Sage did ask for my notes at 11 PM."]},{"id":"b","label":"You just kind of feel it.","reaction":["I feel it. I also feel dizzy. Is that the same?"]}],"outro":null}'::jsonb),
('TW-P19','adventure_friend_tw','Pool',19,0.25,'{"id":"TW-P19","friendId":"adventure_friend_tw","phase":"Pool","seq":19,"familiarity":"Old Friend","type":"Rare","scene":"Twig pulls you aside, whispering.","lines":["Can I practice a confession? On you? Just practice.","Pretend you''re Sage. Ready? ...Okay. Sage. I—I like you. A lot. Like, a lot a lot."],"choices":[{"id":"a","label":"Nod slowly","reaction":["...Okay. That was horrible. But also kind of good?"]},{"id":"b","label":"That was really sweet.","reaction":["Really? ...Okay. I''m taking that to the berry stand."]}],"outro":null}'::jsonb),
('TW-P20','adventure_friend_tw','Pool',20,0.25,'{"id":"TW-P20","friendId":"adventure_friend_tw","phase":"Pool","seq":20,"familiarity":"Old Friend","type":"Rare","scene":"Twig freezes. Sage appears at the edge of the path, waving. ''Hi Twig!'' Twig whispers to you.","lines":["...That''s him."],"choices":[{"id":"a","label":"Nudge Twig gently","reaction":["Hi, Sage. Nice weather."]},{"id":"b","label":"Wave at Sage too","reaction":["Sage waves back. Is that your friend? Nice to meet you!"]}],"outro":null}'::jsonb)
