insert into public.friend_definitions(stable_id,revision_id,name,subtitle,art,metadata,is_placeholder) values('adventure_friend_hz',coalesce((select value from public.app_config where key='app_major_update_content_revision'),'burrow-v1-placeholder'),'Hazel','Okay, so...','{"renderer":"bundled","key":"Squirrel"}'::jsonb,'{"adventureV2":true,"code":"HZ","gender":"she","species":"Squirrel"}'::jsonb,false) on conflict(stable_id) do update set name=excluded.name,subtitle=excluded.subtitle,art=excluded.art,metadata=excluded.metadata,status='active',updated_at=now();
insert into public.adventure_dialogues_v2(id,friend_id,phase,seq,weight,content) values
('HZ-01','adventure_friend_hz','Intro',1,1,'{"id":"HZ-01","friendId":"adventure_friend_hz","phase":"Intro","seq":1,"familiarity":"Stranger","type":"Statement","scene":"A squirrel zips down a trunk carrying three acorns and a rolled-up map, then freezes.","lines":["Oh! Hi! Sorry, I''m Hazel, I was just counting, it''s a thing, I count when I''m nervous, and I''m nervous, and also happy, it''s complicated.","Do you have a minute? ...Or three? I talk a lot."],"choices":[{"id":"a","label":"Take all the time you need.","reaction":["Okay, great, wow, you''re nice. I might actually need all of it.","Everyone says I talk the way I run, which is everywhere at once."]},{"id":"b","label":"You''re carrying a lot of acorns.","reaction":["Right?! Two hundred at home. Okay, one-fifty. I count them every night.","It''s a whole system, and I''ll explain it, but not right now."]},{"id":"c","label":"Is that a map?","reaction":["Yes! A floor plan! Okay, that''s a story for later.","Next time I''ll tell you everything, I promise. I mean it. I always mean it."]}],"outro":null}'::jsonb),
('HZ-02','adventure_friend_hz','Intro',2,1,'{"id":"HZ-02","friendId":"adventure_friend_hz","phase":"Intro","seq":2,"familiarity":"Familiar Face","type":"Statement","scene":null,"lines":["I have a spreadsheet for everything. Snacks, naps, weather, how many times I''ve looked at this map today.","It''s forty-one. It''s only noon."],"choices":[{"id":"a","label":"That''s a lot of looks.","reaction":["I know! But every time I find something new. Like a window I forgot about.","Yesterday it was a very small closet. I got emotional."]},{"id":"b","label":"Can I see the spreadsheet?","reaction":["Yes! No. Maybe. It''s color-coded, and you can''t judge the colors. The pink column is feelings.","It''s the longest one."]},{"id":"c","label":"What''s on the map?","reaction":["A little burrow. Mine. Well. Ours.","I''m still getting used to saying that, so please be patient with me."]}],"outro":null}'::jsonb),
('HZ-03','adventure_friend_hz','Intro',3,1,'{"id":"HZ-03","friendId":"adventure_friend_hz","phase":"Intro","seq":3,"familiarity":"Acquaintance","type":"Statement","scene":null,"lines":["Okay, so, Walnut asked me something big yesterday. He asked me while we were sharing a nut, which is very romantic in squirrel culture.","I said yes before he finished the sentence. I''m still processing that I said yes."],"choices":[{"id":"a","label":"What did he ask?","reaction":["To move in together! Same door, same pillow, same everything.","I''m so excited, and I''m also thinking about it very loudly. Mostly in my chest."]},{"id":"b","label":"Congratulations!","reaction":["Thank you!! I''ve been waiting for someone to say that out loud.","It makes it feel real, which is great and also a little terrifying."]},{"id":"c","label":"You said yes before he finished?","reaction":["Okay, so, I do that. Walnut laughed so hard he dropped the nut.","We spent an hour looking for it, and it was one of the best hours."]}],"outro":null}'::jsonb),
('HZ-04','adventure_friend_hz','Intro',4,1,'{"id":"HZ-04","friendId":"adventure_friend_hz","phase":"Intro","seq":4,"familiarity":"Acquaintance","type":"Statement","scene":null,"lines":["We have a plan for the move. A very flexible plan. Walnut wrote ''figure it out'' on page one.","I wrote nine pages. We compromised. His page goes first."],"choices":[{"id":"a","label":"Page one: ''figure it out''?","reaction":["Right?? I almost fainted.","But then he drew a tiny heart next to it and I couldn''t be mad.","He knows exactly what he''s doing."]},{"id":"b","label":"Nine pages is impressive.","reaction":["Thank you. Walnut says it''s ''a lot.'' He says it with love. I think.","I''m choosing to believe it was love."]},{"id":"c","label":"Whose page is better?","reaction":["Mine. Obviously.","But his has a drawing of a squirrel in a hat, so it''s a closer call than I''d like to admit."]}],"outro":null}'::jsonb),
('HZ-05','adventure_friend_hz','Intro',5,1,'{"id":"HZ-05","friendId":"adventure_friend_hz","phase":"Intro","seq":5,"familiarity":"Friend","type":"Ask","scene":null,"lines":["Okay, real question, and I need a real answer.","What''s the best thing you and your partner did when you first started sharing more space? Or, like, more time together?","I''m collecting wisdom. I''m putting it on page ten."],"choices":[{"id":"a","label":"We set aside one evening that was just ours.","reaction":["One evening. Just ours. I love that. Okay, I''m writing ''Ours Night'' on the calendar.","It has a name now, which makes it official."]},{"id":"b","label":"We talked about the small annoying stuff early.","reaction":["The small annoying stuff. Yes. Okay. I''ll start a list. I already have a list.","It''s mostly about his socks. I''ll add a second column."]},{"id":"c","label":"Honestly, we figured it out as we went.","reaction":["Figured it out as you went. Hm. That''s Walnut''s whole philosophy.","Okay, maybe I need to hear it twice. Maybe three times."]}],"outro":null}'::jsonb),
('HZ-06','adventure_friend_hz','Intro',6,1,'{"id":"HZ-06","friendId":"adventure_friend_hz","phase":"Intro","seq":6,"familiarity":"Friend","type":"Statement","scene":null,"lines":["We went to look at the burrow today.","Walnut measured the doorway and said ''it''s fine.'' I measured and said ''it''s three centimeters too narrow.'' We argued for an hour.","Then we realized we were measuring different doors."],"choices":[{"id":"a","label":"Different doors?!","reaction":["Different doors! We laughed so hard.","Turns out the whole argument was about nothing, and I''m keeping that story forever."]},{"id":"b","label":"Who was right?","reaction":["Neither! Both! It''s a draw.","I put it in the spreadsheet under ''Wins.'' Everybody gets a win, that''s my new policy."]},{"id":"c","label":"That''s so couple.","reaction":["I know, right? We argue and then we''re best friends again in five minutes.","It''s honestly the best part of the whole thing."]}],"outro":null}'::jsonb),
('HZ-07','adventure_friend_hz','Intro',7,1,'{"id":"HZ-07","friendId":"adventure_friend_hz","phase":"Intro","seq":7,"familiarity":"Close Friend","type":"Confide","scene":"Hazel sits on a branch, not moving. This is rare.","lines":["Can I tell you something? I''m not counting right now. That''s how you know it''s serious.","I''ve lived alone my whole life. I know where everything is. I know where every acorn lives.","What if I''m bad at sharing? What if I''m better alone?"],"choices":[{"id":"a","label":"Being nervous doesn''t mean it''s wrong.","reaction":["Okay. Okay. That''s a good point. Nervous isn''t a no. I''m writing that down.","Not on page ten. On a good page, near the front."]},{"id":"b","label":"Have you asked Walnut how he feels about it?","reaction":["I never asked. I just assumed he''s fine. He probably has a spreadsheet too.","A secret one. With feelings in it."]},{"id":"c","label":"Sit beside Hazel.","reaction":["...Thanks. I stopped counting. That never happens.","It''s kind of quiet in my head right now, and I actually like it."]}],"outro":null}'::jsonb),
('HZ-08','adventure_friend_hz','Intro',8,1,'{"id":"HZ-08","friendId":"adventure_friend_hz","phase":"Intro","seq":8,"familiarity":"Close Friend","type":"Statement","scene":null,"lines":["I told Walnut I was scared. Not ''I have concerns,'' scared.","He said, ''Me too. I haven''t eaten in two days.'' We sat there. Two scared squirrels on a branch.","Then we ordered pizza. It helped."],"choices":[{"id":"a","label":"That''s honest.","reaction":["It really was. I feel lighter. Okay, still scared, but lighter.","Like a scared squirrel with a better view."]},{"id":"b","label":"Two scared squirrels is adorable.","reaction":["We were SO bad at it. He kept offering me crumbs.","I kept saying ''I''m not hungry'' and eating them. It was a very quiet disaster."]},{"id":"c","label":"Pizza fixes everything.","reaction":["It does not fix everything, but it fixes dinner.","And dinner is like seventy percent of a day. I''ll take those odds."]}],"outro":null}'::jsonb),
('HZ-09','adventure_friend_hz','Intro',9,1,'{"id":"HZ-09","friendId":"adventure_friend_hz","phase":"Intro","seq":9,"familiarity":"Best Friend","type":"Companion","scene":null,"lines":["We moved the first box today.","Just one. A small one. Walnut carried it very slowly, like it was a baby.","I stood in the empty room and I didn''t count anything. I just stood there. It felt like a held breath."],"choices":[{"id":"a","label":"That sounds like a good moment.","reaction":["It was. I''m usually so busy planning that I forget to feel it.","Today I felt it. It was big and warm and a little bit wobbly."]},{"id":"b","label":"How did it feel?","reaction":["Like standing on the edge of a good thing. Scary and soft at the same time.","I think that''s what ''home'' feels like before it''s home."]},{"id":"c","label":"Smile and listen.","reaction":["...You''re good at this.","I could say the whole thing out loud because you just let me. Thank you.","I didn''t even count the pauses."]}],"outro":null}'::jsonb),
('HZ-10','adventure_friend_hz','Intro',10,1,'{"id":"HZ-10","friendId":"adventure_friend_hz","phase":"Intro","seq":10,"familiarity":"Old Friend","type":"Milestone","scene":null,"lines":["Okay, so. Ten visits. I counted. Obviously.","We moved in last weekend. The dishes are already a thing. Walnut loads them like it''s a puzzle. I rearrange them. We both pretend it''s fine.","It IS fine. It''s more than fine. It''s messy and loud and I''d never go back.","Your turn. How are you and your partner doing? I mean it."],"choices":[{"id":"a","label":"We''re good. Still figuring it out.","reaction":["Figuring it out is the whole thing. I''m so glad. Come visit!","Walnut will pretend he cleaned, and I''ll pretend I believe him."]},{"id":"b","label":"A bit tired, but we''re okay.","reaction":["Tired and okay is real. Come over, I''ll make tea, you can complain.","I''m an expert in complaining. I mean listening. Both."]},{"id":"c","label":"You''ve inspired me to talk more.","reaction":["Ahh! Really?? That''s the nicest thing anyone''s said. Okay, I''m writing that on page one.","Right next to ''figure it out.''"]}],"outro":null}'::jsonb),
('HZ-P01','adventure_friend_hz','Pool',1,1,'{"id":"HZ-P01","friendId":"adventure_friend_hz","phase":"Pool","seq":1,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["We made a chore chart. Walnut added stickers. I''m now emotionally invested in the star system.","He gets a star when he does the dishes. I get a star when I don''t alphabetize the pantry."],"choices":[{"id":"a","label":"That''s cute.","reaction":["It IS cute. And dangerous. I''m competitive, so I''ve been eyeing the dishes.","He''s been eyeing the pantry. It''s a love war with glitter."]},{"id":"b","label":"Who''s winning?","reaction":["Walnut. By seven stars. He knows, and he''s insufferable about it. I love him.","I also want a rematch, and I have a plan."]}],"outro":null}'::jsonb),
('HZ-P02','adventure_friend_hz','Pool',2,1,'{"id":"HZ-P02","friendId":"adventure_friend_hz","phase":"Pool","seq":2,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["Walnut snores. I didn''t know. We''ve shared a nap before, but never a whole night.","It''s like a tiny motor. I can''t decide if I hate it or I''m in love with it."],"choices":[{"id":"a","label":"Maybe both?","reaction":["Both. Definitely both.","Last night I put a pillow over my ears and then took it off, because it was weirdly comforting.","I''m a mess."]},{"id":"b","label":"Earplugs?","reaction":["Tried those. I woke up, couldn''t find him, panicked, and pulled them out.","Turns out the snore is my sleep signal now. That''s very annoying."]}],"outro":null}'::jsonb),
('HZ-P03','adventure_friend_hz','Pool',3,1,'{"id":"HZ-P03","friendId":"adventure_friend_hz","phase":"Pool","seq":3,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["I found three of Walnut''s socks in the kitchen. Three. He only has two feet.","I put them in a basket. A basket of lonely socks. It''s art now."],"choices":[{"id":"a","label":"Gallery-worthy.","reaction":["Right?? I''m calling it ''Still Life with Missing Partner.'' Walnut says it''s a metaphor for us.","It''s not. But I let him have it."]},{"id":"b","label":"Did you tell him?","reaction":["I did, lovingly. He said, ''those are decorations.'' We both laughed.","I love that we have our own language for chaos."]}],"outro":null}'::jsonb),
('HZ-P04','adventure_friend_hz','Pool',4,1,'{"id":"HZ-P04","friendId":"adventure_friend_hz","phase":"Pool","seq":4,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["I let Walnut organize the pantry today. By himself. I went on a walk and didn''t look.","When I came back everything was in the wrong place. And somehow it was also exactly right."],"choices":[{"id":"a","label":"That takes courage.","reaction":["It really did. I held onto a branch the whole walk.","But when I opened the cabinet, I could see his brain.","It was kind of sweet, in a messy way."]},{"id":"b","label":"Did you fix it?","reaction":["I moved one jar. Then I stopped. Then I put it back.","I''m learning that ''his way'' can also be ''our way.'' Slowly. With deep breaths."]}],"outro":null}'::jsonb),
('HZ-P05','adventure_friend_hz','Pool',5,1,'{"id":"HZ-P05","friendId":"adventure_friend_hz","phase":"Pool","seq":5,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["We hosted our first dinner. For two guests. I made a spreadsheet.","Walnut made the soup. It was perfect. I overcooked the nuts. We pretended it was a feature."],"choices":[{"id":"a","label":"Sounds like a success.","reaction":["It was! Two guests, one near-disaster, zero fights.","Walnut squeezed my paw under the table at the exact moment I started to panic.","How does he know?"]},{"id":"b","label":"Overcooked nuts are a feature.","reaction":["Right? ''Extra roasted.'' The guests loved it, honestly. Walnut called me a genius.","I put that in the spreadsheet under ''Quotes to Keep.''"]}],"outro":null}'::jsonb),
('HZ-P06','adventure_friend_hz','Pool',6,1,'{"id":"HZ-P06","friendId":"adventure_friend_hz","phase":"Pool","seq":6,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["I took the left side of the bed. Walnut took the left side of the bed. We had a standoff.","We settled it with a coin toss. I won. He then said, ''Fine, but I get the good blanket.'' Evil."],"choices":[{"id":"a","label":"Fair trade.","reaction":["Is it though? The good blanket is SO good.","But he looked so pleased that I''m letting it slide. This time.","I have a pending request on file."]},{"id":"b","label":"Who won the blanket?","reaction":["Walnut. Obviously. But I''m sneaky. I''ve been slowly stealing it one corner per night.","He hasn''t noticed. I think. I hope."]}],"outro":null}'::jsonb),
('HZ-P07','adventure_friend_hz','Pool',7,1,'{"id":"HZ-P07","friendId":"adventure_friend_hz","phase":"Pool","seq":7,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["I got home late and Walnut left the lamp on for me. Just the lamp. No note.","It''s the smallest thing. I stood at the door and almost cried. It''s a lamp."],"choices":[{"id":"a","label":"That''s not just a lamp.","reaction":["No, it isn''t. It''s a whole sentence.","It says ''I''m here, come home.'' I didn''t know a lamp could talk.","Walnut doesn''t even know he''s good at this."]},{"id":"b","label":"That''s so sweet.","reaction":["It''s SO sweet. I took a picture of it. Then I felt silly.","Then I took another one. I''m keeping both forever."]}],"outro":null}'::jsonb),
('HZ-P08','adventure_friend_hz','Pool',8,1,'{"id":"HZ-P08","friendId":"adventure_friend_hz","phase":"Pool","seq":8,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["We have a Sunday ritual now. We walk to the berry stand together and don''t talk. Just walk.","I didn''t know I needed that. A silent walk. With somebody who doesn''t need me to fill the silence."],"choices":[{"id":"a","label":"That sounds peaceful.","reaction":["It IS. And it''s weird, because I''m usually the loud one.","But with him, quiet feels like a hug. I never thought I''d say that out loud."]},{"id":"b","label":"Don''t you miss talking?","reaction":["Not at all. We talk plenty the rest of the week.","This part is a little pocket of calm. I''ve started protecting it like a rare acorn."]}],"outro":null}'::jsonb),
('HZ-P09','adventure_friend_hz','Pool',9,1,'{"id":"HZ-P09","friendId":"adventure_friend_hz","phase":"Pool","seq":9,"familiarity":"Old Friend","type":"Callback","scene":null,"lines":["Remember page one? ''Figure it out''? Walnut framed it.","It''s in the hallway. Right next to my nine-page plan. Both on the wall. Both ours."],"choices":[{"id":"a","label":"That''s adorable.","reaction":["Right? Visitors always ask.","I say ''it''s our philosophy.'' Walnut says ''it''s my art.'' We don''t agree on the explanation, and it works."]},{"id":"b","label":"He framed it?!","reaction":["He framed it! With a little gold border.","He said, ''this was the beginning.'' I almost cried into the pantry. Again."]}],"outro":null}'::jsonb),
('HZ-P10','adventure_friend_hz','Pool',10,1,'{"id":"HZ-P10","friendId":"adventure_friend_hz","phase":"Pool","seq":10,"familiarity":"Old Friend","type":"Callback","scene":null,"lines":["I still count my acorns at night. Walnut counts with me now. He gets it wrong on purpose.","''Two hundred and... a hat?'' He thinks it''s funny. It is. I''m annoyed. I''m in love."],"choices":[{"id":"a","label":"That''s a good bit.","reaction":["It''s the best bit.","Counting used to be my anxiety thing, and now it''s our bedtime thing.","Weird how that happens."]},{"id":"b","label":"Does it still calm you?","reaction":["Even more, actually. The counting is the same, but now there''s somebody to mess it up.","That''s the part I didn''t know I needed."]}],"outro":null}'::jsonb),
('HZ-P11','adventure_friend_hz','Pool',11,1,'{"id":"HZ-P11","friendId":"adventure_friend_hz","phase":"Pool","seq":11,"familiarity":"Old Friend","type":"Callback","scene":null,"lines":["Remember the two scared squirrels on the branch? Walnut brought it up yesterday.","He said, ''I''m glad we were scared together.'' Then he went to do the dishes like he hadn''t just wrecked me."],"choices":[{"id":"a","label":"He''s a keeper.","reaction":["He really is. He drops these little bombs and walks away.","I''m left standing there holding a spoon, completely undone."]},{"id":"b","label":"That''s lovely.","reaction":["It is. I wrote it on a sticky note and put it on the fridge.","He''s seen it and pretended not to. We''re a good team."]}],"outro":null}'::jsonb),
('HZ-P12','adventure_friend_hz','Pool',12,1,'{"id":"HZ-P12","friendId":"adventure_friend_hz","phase":"Pool","seq":12,"familiarity":"Old Friend","type":"Callback","scene":null,"lines":["We started a thing on Thursdays. Just us. No plans. No spreadsheet.","Last week we lay in blankets and watched the ceiling. Best date ever."],"choices":[{"id":"a","label":"That sounds perfect.","reaction":["It was. I love having a night that doesn''t need to be anything.","Thursday is basically my favorite day now. I didn''t even bring a notebook."]},{"id":"b","label":"No plan at all?","reaction":["None. Zero. I let the evening happen.","I think it might be the first time in my life.","Walnut said ''good job.'' I said ''thanks.'' We lost it."]}],"outro":null}'::jsonb),
('HZ-P13','adventure_friend_hz','Pool',13,1,'{"id":"HZ-P13","friendId":"adventure_friend_hz","phase":"Pool","seq":13,"familiarity":"Old Friend","type":"HotTake","scene":null,"lines":["Hot take: Planning is a love language. So is forgetting the plan and laughing."],"choices":[{"id":"a","label":"Both feel true.","reaction":["Right? I''m learning the second one from Walnut. It''s way harder than it looks.","But the laughing part is the good part."]},{"id":"b","label":"Plan or laugh, which wins?","reaction":["Laugh. Every time. But I''ll make a plan to laugh.","Okay, that''s the real problem, isn''t it. I''m working on it."]}],"outro":null}'::jsonb),
('HZ-P14','adventure_friend_hz','Pool',14,1,'{"id":"HZ-P14","friendId":"adventure_friend_hz","phase":"Pool","seq":14,"familiarity":"Old Friend","type":"HotTake","scene":null,"lines":["Hot take: Sharing a home isn''t about sharing space. It''s about sharing mornings."],"choices":[{"id":"a","label":"That''s real.","reaction":["It really is. Mornings are where I see him most honestly.","Hair a mess, voice low, asking if I want tea. That''s the good stuff."]},{"id":"b","label":"Mornings are hard though.","reaction":["They are! Walnut is a zombie until the second cup.","But there''s something about a zombie handing me tea that I''d trade a whole acorn for."]}],"outro":null}'::jsonb),
('HZ-P15','adventure_friend_hz','Pool',15,1,'{"id":"HZ-P15","friendId":"adventure_friend_hz","phase":"Pool","seq":15,"familiarity":"Old Friend","type":"HotTake","scene":null,"lines":["Hot take: The first fight in a new home is basically a housewarming gift."],"choices":[{"id":"a","label":"Ha, that''s a take.","reaction":["I stand by it! You learn each other''s rules. We fought about towels.","Now we have a towel treaty. It''s the most romantic document I own."]},{"id":"b","label":"I''d return that gift.","reaction":["Fair! But honestly, the towel fight showed me how Walnut handles being wrong.","He apologized with a snack. I''d marry that."]}],"outro":null}'::jsonb),
('HZ-P16','adventure_friend_hz','Pool',16,1,'{"id":"HZ-P16","friendId":"adventure_friend_hz","phase":"Pool","seq":16,"familiarity":"Old Friend","type":"AskBack","scene":null,"lines":["Okay, I want a house rule from you.","What''s one tiny habit you and your partner have that makes your days better?"],"choices":[{"id":"a","label":"We always say goodnight, even if we''re annoyed.","reaction":["Oh, I love that. Even annoyed. It''s like a safety net. I''m stealing it.","Walnut and I will have a goodnight clause."]},{"id":"b","label":"We take turns choosing dinner.","reaction":["Turns. I love it. Equal and tasty. I''m going to make a rotating calendar.","Walnut''s going to groan. Then he''ll love it."]}],"outro":null}'::jsonb),
('HZ-P17','adventure_friend_hz','Pool',17,1,'{"id":"HZ-P17","friendId":"adventure_friend_hz","phase":"Pool","seq":17,"familiarity":"Old Friend","type":"AskBack","scene":null,"lines":["Do you and your partner have a thing where you read each other''s moods without talking?","Walnut does it with me, and I''m still trying to learn his."],"choices":[{"id":"a","label":"Yeah, mostly.","reaction":["Mostly. That''s the honest answer. I''ll take ''mostly.'' Okay. I''m going to watch Walnut''s ears more.","They twitch when he''s thinking."]},{"id":"b","label":"Still working on it.","reaction":["Same. We''re all out here squinting at each other''s faces. It''s reassuring, honestly.","Thank you for saying that."]}],"outro":null}'::jsonb),
('HZ-P18','adventure_friend_hz','Pool',18,1,'{"id":"HZ-P18","friendId":"adventure_friend_hz","phase":"Pool","seq":18,"familiarity":"Old Friend","type":"AskBack","scene":null,"lines":["What''s something you did for your partner that was small but landed huge?","I''m collecting these for Walnut''s birthday. Don''t tell him."],"choices":[{"id":"a","label":"I left a note in their pocket.","reaction":["A note. In a pocket. That''s so simple and so good. I''m going to do three.","One for every pocket. He''s going to be so confused."]},{"id":"b","label":"I made their favorite snack, no reason.","reaction":["No reason. Those are the best ones. I''m going to make his favorite nut loaf.","Burnt edges and all. It''s practically a love letter."]}],"outro":null}'::jsonb),
('HZ-P19','adventure_friend_hz','Pool',19,0.25,'{"id":"HZ-P19","friendId":"adventure_friend_hz","phase":"Pool","seq":19,"familiarity":"Old Friend","type":"Rare","scene":"Hazel invites you into the new burrow. Boxes everywhere. One lamp is on.","lines":["Okay, so, this is it. This is ours. Please ignore the boxes.","Walnut''s in the kitchen pretending he knows where the mugs are."],"choices":[{"id":"a","label":"It feels like a home already.","reaction":["Does it? Okay, that makes me so happy. I think it''s the lamp. Or the boxes.","Or Walnut. Probably Walnut."]},{"id":"b","label":"Where do you want me to sit?","reaction":["Anywhere! Wait, not there. That''s the ''maybe'' chair. It''s holding my plant. Sit here. Yes. Perfect.","You look right at home."]}],"outro":null}'::jsonb),
('HZ-P20','adventure_friend_hz','Pool',20,0.25,'{"id":"HZ-P20","friendId":"adventure_friend_hz","phase":"Pool","seq":20,"familiarity":"Old Friend","type":"Rare","scene":"Hazel stops mid-sentence, takes a breath, and just looks at you.","lines":["I just realized I haven''t counted anything today.","Not once. I think that''s because I''m... okay. Really okay."],"choices":[{"id":"a","label":"That''s a big deal.","reaction":["It really is. I almost didn''t notice. Okay, I''ll count how long it lasts. Wait. No.","I won''t. Look at me, growing."]},{"id":"b","label":"Smile at Hazel.","reaction":["Thank you for being here for all of it. I mean it. Okay, now I''m counting.","Three. Three nice things about today. That''s allowed."]}],"outro":null}'::jsonb)
