insert into public.friend_definitions(stable_id,revision_id,name,subtitle,art,metadata,is_placeholder) values('adventure_friend_dl',coalesce((select value from public.app_config where key='app_major_update_content_revision'),'burrow-v1-placeholder'),'Dillon','...Maybe.','{"renderer":"bundled","key":"Armadillo"}'::jsonb,'{"adventureV2":true,"code":"DL","gender":"he","species":"Armadillo"}'::jsonb,false) on conflict(stable_id) do update set name=excluded.name,subtitle=excluded.subtitle,art=excluded.art,metadata=excluded.metadata,status='active',updated_at=now();
insert into public.adventure_dialogues_v2(id,friend_id,phase,seq,weight,content) values
('DL-01','adventure_friend_dl','Intro',1,1,'{"id":"DL-01","friendId":"adventure_friend_dl","phase":"Intro","seq":1,"familiarity":"Stranger","type":"Statement","scene":"An armadillo rolls out from behind a rock, uncurls slowly, and watches you.","lines":["...Hi.","I''m Dillon. I''m just... out for a walk. Slowly. You don''t have to talk if you don''t want to."],"choices":[{"id":"a","label":"Hi, Dillon. No rush.","reaction":["Thanks. Most people rush. You don''t. That''s... nice. I''ll stay for a bit. Maybe."]},{"id":"b","label":"Nice shell.","reaction":["Thanks. It''s been through a lot. It''s thick for a reason.","But it''s also kind of comfortable. Don''t tell anyone I said that."]},{"id":"c","label":"Wait quietly.","reaction":["...Okay. That''s a good start. Most folks fill the silence. You didn''t. That tells me something.","Not sure what yet. But something good."]}],"outro":null}'::jsonb),
('DL-02','adventure_friend_dl','Intro',2,1,'{"id":"DL-02","friendId":"adventure_friend_dl","phase":"Intro","seq":2,"familiarity":"Familiar Face","type":"Statement","scene":null,"lines":["I keep a list of things I trust. It''s short.","The sun. A good rock. My shell. A very specific kind of berry."],"choices":[{"id":"a","label":"What''s the berry?","reaction":["Blue-ish. Slightly tart. It never lies about its flavor. That''s all I ask of a berry.","Or anyone, really."]},{"id":"b","label":"Is the list getting longer?","reaction":["Slowly. Maybe. There''s one new item I''m not ready to talk about. It''s... a person."]},{"id":"c","label":"Short lists are fine.","reaction":["Thank you. Everyone says I should trust more.","I say I trust exactly as much as I should. It''s just a carefully chosen amount."]}],"outro":null}'::jsonb),
('DL-03','adventure_friend_dl','Intro',3,1,'{"id":"DL-03","friendId":"adventure_friend_dl","phase":"Intro","seq":3,"familiarity":"Acquaintance","type":"Statement","scene":null,"lines":["Someone''s been leaving tea outside my burrow. Every morning for a month.","Her name''s Ash. I don''t know what to do with that kindness. I''m... not used to it."],"choices":[{"id":"a","label":"What do you do with the tea?","reaction":["Drink it. Obviously. It''s very good tea. I haven''t said thank you yet.","I''m working on it. It''s a surprisingly big step."]},{"id":"b","label":"That''s really sweet.","reaction":["Yeah. It is. It''s also a little scary.","Sweet things can feel suspicious when you''ve been surprised before.","But I''m trying to let it be sweet."]},{"id":"c","label":"Maybe say thank you?","reaction":["...Yeah. Maybe. I wrote it on a note. I haven''t left it yet.","It''s in my shell. Next to my other emergency notes."]}],"outro":null}'::jsonb),
('DL-04','adventure_friend_dl','Intro',4,1,'{"id":"DL-04","friendId":"adventure_friend_dl","phase":"Intro","seq":4,"familiarity":"Acquaintance","type":"Statement","scene":null,"lines":["I left a note for Ash. It said ''thanks.'' Just that.","She left one back. It said ''you''re welcome. No pressure.'' I read it eleven times."],"choices":[{"id":"a","label":"No pressure is a good phrase.","reaction":["It''s the best phrase. Most people say ''no pressure'' and then apply pressure.","Ash actually means it. I can tell. The tea kept coming. No questions."]},{"id":"b","label":"Eleven times?","reaction":["I counted. It''s a lot.","But it''s the first note in a long time that didn''t make me nervous.","It made me... warm. A weird feeling."]},{"id":"c","label":"Ash sounds kind.","reaction":["Kind, steady, quiet. A little like a good rock. I mean that as a huge compliment.","Rocks are my favorite thing."]}],"outro":null}'::jsonb),
('DL-05','adventure_friend_dl','Intro',5,1,'{"id":"DL-05","friendId":"adventure_friend_dl","phase":"Intro","seq":5,"familiarity":"Friend","type":"Ask","scene":null,"lines":["Can I ask you something? It''s a weird one.","How do you know someone''s safe? Not ''nice.'' Safe.","I''ve been wrong before. I''d like a better method."],"choices":[{"id":"a","label":"Their words match their actions.","reaction":["Words match actions. That''s... practical. Not romantic, but real. I like that. I''ll watch for it.","Quietly."]},{"id":"b","label":"Go slow and notice how they treat you when it''s inconvenient.","reaction":["When it''s inconvenient. Yes. That''s the test. Anyone''s kind when it''s easy.","I''ll keep an eye out. Thank you."]},{"id":"c","label":"Honestly, you just have to take small risks.","reaction":["Small risks. Hm. Like leaving a note. I did that. So I''m technically a risk-taker.","That''s a bold sentence for an armadillo."]}],"outro":null}'::jsonb),
('DL-06','adventure_friend_dl','Intro',6,1,'{"id":"DL-06","friendId":"adventure_friend_dl","phase":"Intro","seq":6,"familiarity":"Friend","type":"Statement","scene":null,"lines":["Ash came by today. We sat on a log and said nothing.","It was the longest silence I''ve had with another person in years. I didn''t curl up once."],"choices":[{"id":"a","label":"That''s big.","reaction":["It felt big. Like a door that didn''t need to be opened, but was left unlatched.","I didn''t feel the urge to leave. That''s rare."]},{"id":"b","label":"Did it feel safe?","reaction":["...It did. It felt like sitting next to a warm rock.","A rock that happens to care. I don''t have a better comparison. Sorry."]},{"id":"c","label":"Silence can say a lot.","reaction":["It really can. I used to think silence meant trouble. Today it meant company.","That''s a very different thing. I''m still adjusting."]}],"outro":null}'::jsonb),
('DL-07','adventure_friend_dl','Intro',7,1,'{"id":"DL-07","friendId":"adventure_friend_dl","phase":"Intro","seq":7,"familiarity":"Close Friend","type":"Confide","scene":"Dillon sits with his shell half-closed, looking at the ground.","lines":["Can I tell you something? It''s the heavy kind.","Someone I trusted once lied to me. For a long time. I found out in a way that... I won''t describe.","I keep waiting for it to happen again. Even though Ash has given me no reason."],"choices":[{"id":"a","label":"That makes sense, and you''re allowed to take your time.","reaction":["...Thank you.","Most people say ''just trust.'' You said ''take your time.'' That''s the first time anyone''s said it that way.","I think I needed it."]},{"id":"b","label":"Have you told Ash?","reaction":["A little. I said ''I''m slow to trust.'' She said ''okay.'' Just ''okay.'' No questions.","Maybe I should tell her more. Slowly. In pieces."]},{"id":"c","label":"Sit beside Dillon.","reaction":["...Thanks. It''s easier to say heavy things when someone''s just sitting there. Not fixing. Just sitting.","It''s weirdly comforting."]}],"outro":null}'::jsonb),
('DL-08','adventure_friend_dl','Intro',8,1,'{"id":"DL-08","friendId":"adventure_friend_dl","phase":"Intro","seq":8,"familiarity":"Close Friend","type":"Statement","scene":null,"lines":["I told Ash. The heavy thing. Not all of it. Some of it.","She didn''t flinch. She said ''thank you for trusting me with that.'' Then she asked if I wanted more tea.","I said yes. And then I almost cried into the cup."],"choices":[{"id":"a","label":"That''s a good response.","reaction":["It''s the best response. No pity. No panic. Just ''thank you'' and tea.","I don''t know how she knew exactly what I needed. Maybe she just cares. Quietly."]},{"id":"b","label":"Ash sounds really kind.","reaction":["She is. I''m learning that kindness doesn''t have to be loud. It can be tea.","It can be a note. It can be someone who stays when the story gets heavy."]},{"id":"c","label":"You were brave.","reaction":["I didn''t feel brave. I felt like a snail crossing a road. But I did it.","Maybe that''s what brave is. Moving slowly while scared."]}],"outro":null}'::jsonb),
('DL-09','adventure_friend_dl','Intro',9,1,'{"id":"DL-09","friendId":"adventure_friend_dl","phase":"Intro","seq":9,"familiarity":"Best Friend","type":"Companion","scene":null,"lines":["I opened my shell a little today.","Not all the way. Just a crack. Enough for Ash to see a bit of me. She said ''hi.'' I said ''hi.'' We sat there like two shy rocks.","It was perfect."],"choices":[{"id":"a","label":"That sounds beautiful.","reaction":["It was. A crack is a lot, when you''ve been closed for a long time.","Light comes in through a crack. I never knew that before."]},{"id":"b","label":"How did it feel?","reaction":["Terrifying. Warm. A little silly. Like stepping outside after a long rain. The air smelled different.","I think it was hope."]},{"id":"c","label":"Smile and listen.","reaction":["Thanks. I''m not used to saying things out loud. But you listen well.","Maybe I''m learning that I can say things. Slowly."]}],"outro":null}'::jsonb),
('DL-10','adventure_friend_dl','Intro',10,1,'{"id":"DL-10","friendId":"adventure_friend_dl","phase":"Intro","seq":10,"familiarity":"Old Friend","type":"Milestone","scene":null,"lines":["...Ten visits.","I counted. I don''t tell people that. It means you matter. A little.","Ash and I are... something. We haven''t named it. We just keep showing up. It''s enough. For now.","Your turn. How are you and your partner doing? Honestly. I can handle honest."],"choices":[{"id":"a","label":"We''re good. Still learning.","reaction":["Learning. Good. Keep doing that. Come by sometime. Ash makes tea. I make silence.","It''s a good combo."]},{"id":"b","label":"We''ve had some tough moments.","reaction":["Tough moments don''t mean the end. I''m proof. Take your time with them.","And if you need to sit quietly, I''m good at that."]},{"id":"c","label":"You''ve helped me open up too.","reaction":["...Hm. That''s... nice. Thank you.","I think I''ll let that sit in my shell for a while.","A good thing to keep in there."]}],"outro":null}'::jsonb),
('DL-P01','adventure_friend_dl','Pool',1,1,'{"id":"DL-P01","friendId":"adventure_friend_dl","phase":"Pool","seq":1,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["Ash left tea at my door again. This time with a tiny cookie.","I stared at it for a full minute. Then I ate it. It was good. I''m not used to good things being simple."],"choices":[{"id":"a","label":"Simple is nice.","reaction":["It really is. I used to think good things had to be complicated.","Ash taught me that a cookie can just be a cookie.","And a gesture can just be a gesture."]},{"id":"b","label":"How was the cookie?","reaction":["Perfect. Slightly crumbly. A bit of cinnamon. I''m convinced Ash read my mind. Or paid attention.","Which is almost the same thing."]}],"outro":null}'::jsonb),
('DL-P02','adventure_friend_dl','Pool',2,1,'{"id":"DL-P02","friendId":"adventure_friend_dl","phase":"Pool","seq":2,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["I walked with Ash through the berry field.","I didn''t curl up once. I did check the exit twice. But I''m calling it a win."],"choices":[{"id":"a","label":"That''s a win.","reaction":["Thanks. Two exit checks is a record low. Ash noticed and squeezed my paw. No words.","Just a squeeze. It said ''you''re okay.'' I almost believed it."]},{"id":"b","label":"Exit checks are normal.","reaction":["They are for me. It''s a habit from before.","I''m slowly retraining my brain to look at the view instead. It''s working.","The view is better."]}],"outro":null}'::jsonb),
('DL-P03','adventure_friend_dl','Pool',3,1,'{"id":"DL-P03","friendId":"adventure_friend_dl","phase":"Pool","seq":3,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["Ash asked me to come to a small gathering. Four people. Maybe five.","I said ''maybe.'' Then I said ''yes.'' Then I curled up for ten minutes. Then I went."],"choices":[{"id":"a","label":"Proud of you.","reaction":["Thanks. It was... fine. Actually it was nice. A little loud.","But Ash stayed next to me the whole time. I didn''t feel alone in the room.","That''s new."]},{"id":"b","label":"Did you enjoy it?","reaction":["About sixty percent. Which is a lot for me.","The other forty percent was me sitting by the snack table. It''s a good spot.","I recommend it."]}],"outro":null}'::jsonb),
('DL-P04','adventure_friend_dl','Pool',4,1,'{"id":"DL-P04","friendId":"adventure_friend_dl","phase":"Pool","seq":4,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["Ash forgot to message me yesterday. Just once.","I felt the old worry. The loud one. But I said to myself, ''Ash is probably busy.'' And I was right. She was napping. A big nap."],"choices":[{"id":"a","label":"That''s growth.","reaction":["It is. Old Dillon would have spiraled.","This Dillon sent a ''hope you''re resting.'' Ash replied with a heart. It was fine.","It was just fine."]},{"id":"b","label":"How did you calm down?","reaction":["I counted breaths. Four in, four out. And I reminded myself that Ash has been consistent.","Consistent is my favorite word. It''s a good anchor."]}],"outro":null}'::jsonb),
('DL-P05','adventure_friend_dl','Pool',5,1,'{"id":"DL-P05","friendId":"adventure_friend_dl","phase":"Pool","seq":5,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["I told Ash I like her. Out loud.","Just ''I like you.'' Four words. It took me six tries. Ash said ''I like you too'' immediately. I curled up. Then uncurled. Then curled."],"choices":[{"id":"a","label":"That''s beautiful.","reaction":["It felt like a small explosion in my chest. A gentle one. Warm, not scary.","I still can''t believe I said it. Ash keeps smiling at me. I keep curling."]},{"id":"b","label":"Four words is perfect.","reaction":["Four words, total. It felt like a speech. I might do it again someday.","When I''m brave. Or when there''s tea. Probably tea."]}],"outro":null}'::jsonb),
('DL-P06','adventure_friend_dl','Pool',6,1,'{"id":"DL-P06","friendId":"adventure_friend_dl","phase":"Pool","seq":6,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["Ash and I made a pact. If either of us needs space, we say ''shell time.''","No explanation needed. No guilt. Just ''shell time,'' and the other person says ''okay.'' It''s the best rule we have."],"choices":[{"id":"a","label":"That''s genius.","reaction":["It''s Ash''s idea.","She said ''I want you to feel safe saying no.'' Nobody''s ever said that to me.","I curled up for a long time after that. But it was a good curl."]},{"id":"b","label":"Do you use it a lot?","reaction":["Twice. Both times Ash said ''okay'' and checked in later. She didn''t take it personally.","That''s the thing that gets me. She just respected it."]}],"outro":null}'::jsonb),
('DL-P07','adventure_friend_dl','Pool',7,1,'{"id":"DL-P07","friendId":"adventure_friend_dl","phase":"Pool","seq":7,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["I made Ash a tiny stone cup. It''s crooked.","I left it on her doorstep with a note. ''For tea.'' She''s used it every day since."],"choices":[{"id":"a","label":"That''s so sweet.","reaction":["It leaks a little.","Ash says ''it''s a feature.'' I think she''s being kind, but I''m choosing to believe it.","Every time she drinks from it, I feel something warm. In my shell."]},{"id":"b","label":"A crooked cup is the best.","reaction":["Right? It''s imperfect, like me. And Ash uses it anyway. That''s the whole thing, isn''t it?","Using the imperfect things and loving them."]}],"outro":null}'::jsonb),
('DL-P08','adventure_friend_dl','Pool',8,1,'{"id":"DL-P08","friendId":"adventure_friend_dl","phase":"Pool","seq":8,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["I had a hard day. The old kind. I didn''t tell Ash right away.","I told her the next morning. She said ''I''m glad you told me.'' No lecture. No hurt. Just that."],"choices":[{"id":"a","label":"That''s a good response.","reaction":["It was. I keep expecting some kind of penalty for being late with my feelings.","There isn''t one. Ash is just... soft. In the best way."]},{"id":"b","label":"Telling later still counts.","reaction":["I''m starting to believe that. A slow ''I''m struggling'' is better than a silent one.","Ash agrees. She said ''whenever you''re ready.''"]}],"outro":null}'::jsonb),
('DL-P09','adventure_friend_dl','Pool',9,1,'{"id":"DL-P09","friendId":"adventure_friend_dl","phase":"Pool","seq":9,"familiarity":"Old Friend","type":"Callback","scene":null,"lines":["Remember my list? The things I trust?","It''s longer. I added ''Ash.'' And ''tea.'' And ''a crooked cup.'' It''s now seven things."],"choices":[{"id":"a","label":"That''s lovely.","reaction":["It''s the longest list I''ve had. I keep it in my shell.","Next to the note Ash wrote. It''s getting crowded in there. In a good way."]},{"id":"b","label":"Seven is a lot.","reaction":["It''s a lot. I''m shocked. I''m still the same careful Dillon. But the list is growing.","Slowly. Like a plant I keep forgetting to water but somehow thrives."]}],"outro":null}'::jsonb),
('DL-P10','adventure_friend_dl','Pool',10,1,'{"id":"DL-P10","friendId":"adventure_friend_dl","phase":"Pool","seq":10,"familiarity":"Old Friend","type":"Callback","scene":null,"lines":["Ash still brings tea every morning. Even now.","I don''t flinch anymore. I just say ''thanks'' and drink. It''s the best part of my day."],"choices":[{"id":"a","label":"That''s consistent.","reaction":["Consistent. My favorite word. Ash is a living example. Every morning, same time, same smile.","I''ve started waiting at the door. Don''t tell anyone."]},{"id":"b","label":"Do you leave notes back?","reaction":["Sometimes. Little ones. ''Good tea.'' ''Thanks.'' ''It rained.'' Ash keeps them in a jar.","I know because I saw the jar. It''s half-full."]}],"outro":null}'::jsonb),
('DL-P11','adventure_friend_dl','Pool',11,1,'{"id":"DL-P11","friendId":"adventure_friend_dl","phase":"Pool","seq":11,"familiarity":"Old Friend","type":"Callback","scene":null,"lines":["''No pressure.'' Ash said it again yesterday.","I told her I wanted to sit closer. She said ''no pressure.'' And I realized I wasn''t feeling any. That''s rare."],"choices":[{"id":"a","label":"That''s the magic phrase.","reaction":["It is. And the reason it works is that Ash means it.","You can feel when someone''s pushing and when they''re not. Ash never pushes. It''s very soothing."]},{"id":"b","label":"You were comfortable.","reaction":["Surprisingly. I sat close and didn''t curl.","I''m trying to remember how it felt, so I can find it again. It was warm.","Like leaning on a patient wall."]}],"outro":null}'::jsonb),
('DL-P12','adventure_friend_dl','Pool',12,1,'{"id":"DL-P12","friendId":"adventure_friend_dl","phase":"Pool","seq":12,"familiarity":"Old Friend","type":"Callback","scene":null,"lines":["''Shell time.'' We used it again. It''s still working.","Ash said ''okay,'' and later brought me a snack without a word. I''d say it''s a perfect system."],"choices":[{"id":"a","label":"That''s smart.","reaction":["Smart and gentle. It lets me protect myself without hurting her. Before, I''d just vanish.","Now I ask. And she says okay. That''s all I ever wanted. A simple ''okay.''"]},{"id":"b","label":"Snacks help.","reaction":["Snacks always help. A snack says ''I''m here, I''m not mad.'' I''ve started leaving snacks too.","Ash says ''you''re getting good at this.'' I''m still not sure I am."]}],"outro":null}'::jsonb),
('DL-P13','adventure_friend_dl','Pool',13,1,'{"id":"DL-P13","friendId":"adventure_friend_dl","phase":"Pool","seq":13,"familiarity":"Old Friend","type":"HotTake","scene":null,"lines":["Hot take: Trust isn''t a leap. It''s a lot of tiny steps in the same direction."],"choices":[{"id":"a","label":"That''s a good way to see it.","reaction":["I think so too. I''ve never been good at leaps. But steps? I can do steps.","One tea, one note, one ''okay.'' It adds up."]},{"id":"b","label":"Some people leap though.","reaction":["Some do. I admire that. I just think the people who step slowly can also arrive.","It just takes longer. And it''s usually quieter."]}],"outro":null}'::jsonb),
('DL-P14','adventure_friend_dl','Pool',14,1,'{"id":"DL-P14","friendId":"adventure_friend_dl","phase":"Pool","seq":14,"familiarity":"Old Friend","type":"HotTake","scene":null,"lines":["Hot take: Being guarded isn''t the same as being closed."],"choices":[{"id":"a","label":"That''s a good distinction.","reaction":["It took me years to realize that. A guard is just a gate.","A gate can open. A wall can''t. I''m a gate. Ash knows the code. Slowly."]},{"id":"b","label":"Hm, interesting.","reaction":["Thanks. I''m still working on it. Some days I feel like a wall.","Some days like a gate. Most days like a gate with a nap."]}],"outro":null}'::jsonb),
('DL-P15','adventure_friend_dl','Pool',15,1,'{"id":"DL-P15","friendId":"adventure_friend_dl","phase":"Pool","seq":15,"familiarity":"Old Friend","type":"HotTake","scene":null,"lines":["Hot take: The best love stories have a lot of boring, kind moments in them."],"choices":[{"id":"a","label":"Totally.","reaction":["The boring ones are the real ones. Tea. A nod. A shared silence.","I''d take a thousand of those over one big dramatic scene."]},{"id":"b","label":"I like some drama too.","reaction":["Fair. Drama has its charms. But for me, drama feels like a storm.","Boring feels like shelter. I''ve had enough storms. I''ll take the shelter."]}],"outro":null}'::jsonb),
('DL-P16','adventure_friend_dl','Pool',16,1,'{"id":"DL-P16","friendId":"adventure_friend_dl","phase":"Pool","seq":16,"familiarity":"Old Friend","type":"AskBack","scene":null,"lines":["What''s something small your partner does that makes you feel safe?","I''m trying to learn what ''safe'' looks like for other people."],"choices":[{"id":"a","label":"They check in on me.","reaction":["Check-ins. Yes. Ash does that. A quick ''how are you?'' that doesn''t need a long answer.","Just a tiny hello for the heart."]},{"id":"b","label":"They keep their promises.","reaction":["Keeping promises. That''s my number one. Even the small ones.","''I''ll bring tea.'' And then she does. That''s the whole foundation of trust. Tea."]}],"outro":null}'::jsonb),
('DL-P17','adventure_friend_dl','Pool',17,1,'{"id":"DL-P17","friendId":"adventure_friend_dl","phase":"Pool","seq":17,"familiarity":"Old Friend","type":"AskBack","scene":null,"lines":["Do you and your partner ever need space from each other?","I''m curious how other people ask for it."],"choices":[{"id":"a","label":"We just say it honestly.","reaction":["Honestly. That''s it. No big speech.","Just ''I need a little space.'' It''s simple, but it''s hard. I''m practicing.","Ash and I have ''shell time.''"]},{"id":"b","label":"It''s tricky, we''re still figuring it out.","reaction":["Same. It''s a skill. Like walking on stilts. You wobble, and then you improve.","Please be gentle with yourself. I''m trying to do the same."]}],"outro":null}'::jsonb),
('DL-P18','adventure_friend_dl','Pool',18,1,'{"id":"DL-P18","friendId":"adventure_friend_dl","phase":"Pool","seq":18,"familiarity":"Old Friend","type":"AskBack","scene":null,"lines":["What does your partner do that makes you feel seen?","I''m collecting. For a project."],"choices":[{"id":"a","label":"They notice small things.","reaction":["Small things. I like that. Ash noticed I like my tea at exactly the right temperature.","I never said it. She just knew. It made me feel like a person."]},{"id":"b","label":"They remember what I said.","reaction":["Remembering. That''s huge. People forget so easily. Ash remembers I said I dislike loud noises.","So she brings a quiet picnic. That''s what attention looks like."]}],"outro":null}'::jsonb),
('DL-P19','adventure_friend_dl','Pool',19,0.25,'{"id":"DL-P19","friendId":"adventure_friend_dl","phase":"Pool","seq":19,"familiarity":"Old Friend","type":"Rare","scene":"Dillon uncurls fully, which you''ve never seen before.","lines":["Okay. I want you to see this.","This is my shell, open. All the way. Just for a second. It''s a lot. Please don''t make it weird."],"choices":[{"id":"a","label":"Thank you for showing me.","reaction":["...Okay. That''s enough. That felt like jumping off a small cliff.","But it was a soft one. I''m curling back up now. But thank you.","For being kind about it."]},{"id":"b","label":"Smile gently.","reaction":["...That''s all I needed. A gentle smile. No comment.","You''re very good at not making things weird. I''m going to remember this. Maybe."]}],"outro":null}'::jsonb),
('DL-P20','adventure_friend_dl','Pool',20,0.25,'{"id":"DL-P20","friendId":"adventure_friend_dl","phase":"Pool","seq":20,"familiarity":"Old Friend","type":"Rare","scene":"Ash appears carrying two cups of tea and sets one down quietly next to Dillon.","lines":["Hi. You must be the friend. Dillon told me about you.","Thanks for being patient with Dillon. It means a lot. I''m Ash."],"choices":[{"id":"a","label":"Dillon''s lovely.","reaction":["I know. Dillon doesn''t say it, but I think so too.","Dillon has a very careful heart. I''m honored to be near it."]},{"id":"b","label":"Nice to meet you, Ash.","reaction":["Nice to meet you. Want some tea? Dillon will pretend not to be nervous.","He''s very good at it. He''s also very bad at it. It''s endearing."]}],"outro":null}'::jsonb)
