insert into public.friend_definitions(stable_id,revision_id,name,subtitle,art,metadata,is_placeholder) values('adventure_friend_dc',coalesce((select value from public.app_config where key='app_major_update_content_revision'),'burrow-v1-placeholder'),'Duchess','Oh, dear.','{"renderer":"bundled","key":"Badger"}'::jsonb,'{"adventureV2":true,"code":"DC","gender":"she","species":"Badger"}'::jsonb,false) on conflict(stable_id) do update set name=excluded.name,subtitle=excluded.subtitle,art=excluded.art,metadata=excluded.metadata,status='active',updated_at=now();
insert into public.adventure_dialogues_v2(id,friend_id,phase,seq,weight,content) values
('DC-01','adventure_friend_dc','Intro',1,1,'{"id":"DC-01","friendId":"adventure_friend_dc","phase":"Intro","seq":1,"familiarity":"Stranger","type":"Statement","scene":"An elderly badger in round spectacles adjusts a knitting bag and nods slowly as you approach.","lines":["Ah. A new face. Sit, sit. I don''t bite. Much.","I''m Duchess. I''ve been wandering these tunnels longer than most of these trees have been standing."],"choices":[{"id":"a","label":"It''s lovely to meet you.","reaction":["Likewise, dear. You have kind eyes. I can always tell.","It''s a gift that comes with age, along with sore knees and strong opinions."]},{"id":"b","label":"You must have stories.","reaction":["Oh, I have plenty. Some are even true.","I''ll tell you a few, if you promise to listen. It''s all I ask.","That and a good biscuit."]},{"id":"c","label":"Do you need help with the bag?","reaction":["How thoughtful. I can manage, but I appreciate the offer.","Most young people just stare at the knitting. You, my dear, are polite.","I like you already."]}],"outro":null}'::jsonb),
('DC-02','adventure_friend_dc','Intro',2,1,'{"id":"DC-02","friendId":"adventure_friend_dc","phase":"Intro","seq":2,"familiarity":"Familiar Face","type":"Statement","scene":null,"lines":["I''ve been knitting a scarf for forty years. It''s about nine feet long.","It''s for nobody in particular. Or perhaps for everybody. I haven''t decided. It keeps growing."],"choices":[{"id":"a","label":"That''s a lot of scarf.","reaction":["It''s a lot of life, dear. Each row remembers something.","Row nine hundred is the day my knee gave out.","Row two thousand is my sister''s wedding. It''s a sweater of memories."]},{"id":"b","label":"Who is it for?","reaction":["I suspect, in the end, it''s for me. Or for the one who sits by me.","I''m not sure yet. Knitting doesn''t ask for conclusions. It just asks for the next stitch."]},{"id":"c","label":"Can I see it?","reaction":["Of course. Careful, it''s a bit tangled. So am I.","But isn''t that the charm of anything worth keeping? A little tangle, a lot of warmth."]}],"outro":null}'::jsonb),
('DC-03','adventure_friend_dc','Intro',3,1,'{"id":"DC-03","friendId":"adventure_friend_dc","phase":"Intro","seq":3,"familiarity":"Acquaintance","type":"Statement","scene":null,"lines":["My husband''s name is Bartholomew. We''ve been together for forty years.","He''s out in the garden right now. Probably talking to a turnip. He does that."],"choices":[{"id":"a","label":"Forty years! That''s amazing.","reaction":["Isn''t it?","Sometimes I look at him and think ''who is this old badger?'' And then I remember: oh yes, the one I picked.","Over and over. Every day. It''s a choice, you know."]},{"id":"b","label":"A turnip?","reaction":["He says turnips are good listeners. I say it''s because they don''t answer back.","We''ve both been right for four decades."]},{"id":"c","label":"How did you meet?","reaction":["At a harvest dance. He stepped on my foot.","I said ''watch it.'' He said ''I''ll try.'' We''ve been negotiating ever since. Quite happily."]}],"outro":null}'::jsonb),
('DC-04','adventure_friend_dc','Intro',4,1,'{"id":"DC-04","friendId":"adventure_friend_dc","phase":"Intro","seq":4,"familiarity":"Acquaintance","type":"Statement","scene":null,"lines":["Bartholomew and I have a quiet routine. Morning tea. Evening crossword.","We rarely speak during either. We just sit. It''s comfortable. Perhaps too comfortable."],"choices":[{"id":"a","label":"That sounds peaceful.","reaction":["It is. It''s very peaceful.","But lately I''ve been wondering if peace and distance share a front door. Hm.","I''m not sure. I''m still thinking about it."]},{"id":"b","label":"What''s wrong with comfortable?","reaction":["Nothing, dear. Truly. It''s a gift. But comfort has a way of quietly erasing curiosity.","And I miss being curious about him. That''s all."]},{"id":"c","label":"Do you do the crossword together?","reaction":["He does the across. I do the down. We never compare.","It''s a perfectly designed division of silence. We''ve never solved one entirely. Perhaps that''s the secret."]}],"outro":null}'::jsonb),
('DC-05','adventure_friend_dc','Intro',5,1,'{"id":"DC-05","friendId":"adventure_friend_dc","phase":"Intro","seq":5,"familiarity":"Friend","type":"Ask","scene":null,"lines":["Let me ask you something, little one.","When you''ve been with someone a long time, how do you keep from taking them for granted?","I''m not asking for myself. Well. I am. Don''t tell Bartholomew."],"choices":[{"id":"a","label":"I try to notice one new thing about them every day.","reaction":["One new thing. Every day. That''s beautiful. It''s like a very small adventure.","I might try it. I''ll start with his ears. They''ve changed. Tufts. Magnificent."]},{"id":"b","label":"We say thank you for small things.","reaction":["Small thank-yous. Yes. We''ve gotten lazy with those.","''Pass the salt'' has replaced ''thank you for the salt.'' I miss the ''thank you.'' I''ll bring it back."]},{"id":"c","label":"Honestly, I''m still working on that.","reaction":["Ah, honest. I like honest. It''s good to know that even young ones struggle with that.","Perhaps nobody ever finishes learning. It would be rather dull if we did."]}],"outro":null}'::jsonb),
('DC-06','adventure_friend_dc','Intro',6,1,'{"id":"DC-06","friendId":"adventure_friend_dc","phase":"Intro","seq":6,"familiarity":"Friend","type":"Statement","scene":null,"lines":["I tried something odd today. I asked Bartholomew what he dreamed about last night.","He looked at me for a full minute. Then he said, ''a giant turnip.'' We both laughed. First real laugh in weeks."],"choices":[{"id":"a","label":"That''s wonderful.","reaction":["It was! A giant turnip. Of course.","He''d never admit it, but I think he dreams about vegetables affectionately.","It was a lovely little crack in the routine."]},{"id":"b","label":"What did you dream about?","reaction":["I dreamed about my first dance. With him.","He still stepped on my foot in the dream. I found it deeply romantic.","I may have woken up smiling."]},{"id":"c","label":"A giant turnip, really?","reaction":["Really. The size of a house. He was walking toward it with tea.","I''m told it was ''dignified.'' I''m told many things by that man, and I treasure every one."]}],"outro":null}'::jsonb),
('DC-07','adventure_friend_dc','Intro',7,1,'{"id":"DC-07","friendId":"adventure_friend_dc","phase":"Intro","seq":7,"familiarity":"Close Friend","type":"Confide","scene":"Duchess sets down her knitting and looks out at the tunnel.","lines":["May I be honest with you? It''s the kind of honesty one saves for strangers.","Sometimes I wonder if we''ve run out of things to learn about each other.","It frightens me. A little."],"choices":[{"id":"a","label":"That''s a very human fear.","reaction":["Thank you, dear.","It''s easier to admit to a stranger than to the person asleep beside you.","But I think it''s the beginning of something, not the end."]},{"id":"b","label":"Maybe there''s more to discover.","reaction":["Perhaps. There''s always more. That''s the strange thing about people.","Forty years in, and Bartholomew still surprised me with a turnip dream.","There may be a few more."]},{"id":"c","label":"Sit beside Duchess.","reaction":["...Thank you. It''s been a while since someone simply sat with me.","I forget how much comfort a quiet moment can give. You''re a rare young one."]}],"outro":null}'::jsonb),
('DC-08','adventure_friend_dc','Intro',8,1,'{"id":"DC-08","friendId":"adventure_friend_dc","phase":"Intro","seq":8,"familiarity":"Close Friend","type":"Statement","scene":null,"lines":["I told Bartholomew. About feeling distant.","He put down his crossword. That''s the biggest gesture he''s made in years. He said, ''I thought it was just me.''","We talked until midnight. It was our longest conversation in a decade."],"choices":[{"id":"a","label":"That''s moving.","reaction":["It was. Two old badgers discovering the same worry.","We were both too polite to mention it. Isn''t that absurd?","Forty years, and we still hide things to be kind."]},{"id":"b","label":"Midnight is a good length.","reaction":["It was a lovely stretch of time. We sat up. We had cocoa.","He brought a blanket.","At one point he held my paw and I thought, ''ah. There he is.''"]},{"id":"c","label":"You both felt it.","reaction":["We did. Sometimes the bravest thing isn''t a grand gesture.","It''s saying ''I miss you'' to someone sitting three feet away. Oh, how silly. How necessary."]}],"outro":null}'::jsonb),
('DC-09','adventure_friend_dc','Intro',9,1,'{"id":"DC-09","friendId":"adventure_friend_dc","phase":"Intro","seq":9,"familiarity":"Best Friend","type":"Companion","scene":null,"lines":["We went stargazing last night. Just the two of us.","He pointed at a star and said, ''that one''s new.'' I said, ''it''s older than both of us.'' He said, ''new to me.'' I held his paw.","I think that''s the whole of love, really. Being new to each other, even after forty years."],"choices":[{"id":"a","label":"That''s beautiful.","reaction":["Thank you, dear. I''m still smiling.","I think that''s what I want to say to every young couple: stay new to each other.","It''s the secret to a long marriage. And excellent cocoa."]},{"id":"b","label":"A new star, really?","reaction":["A new star, to him. And I decided to believe him. Why not?","He''s been seeing the world for eighty years and still finds something new.","That''s the man I married."]},{"id":"c","label":"Smile and listen.","reaction":["Thank you for listening, dear. These stories are lovelier when shared.","I''ll tell you more some day. Perhaps about the turnip. It''s a long one."]}],"outro":null}'::jsonb),
('DC-10','adventure_friend_dc','Intro',10,1,'{"id":"DC-10","friendId":"adventure_friend_dc","phase":"Intro","seq":10,"familiarity":"Old Friend","type":"Milestone","scene":null,"lines":["Ten visits, little one. I''ve been counting. Old habit.","Bartholomew and I have started a new tradition. Every Sunday, we try something neither of us has done. Last week it was pottery. We made a lopsided bowl. It''s glorious.","It isn''t perfect. But it''s ours.","Now, you. How are you and your partner? I''ve shared enough. Tell me."],"choices":[{"id":"a","label":"We''re good. Still learning.","reaction":["Still learning. That is the right answer, my dear. Come to tea.","Bartholomew will show you the bowl. He''s insufferably proud of it. It leaks."]},{"id":"b","label":"We''ve been a bit distant lately.","reaction":["Distance is part of any long road. Don''t be afraid of it.","Ask a small question tonight. Something you don''t know. You may be surprised. I certainly was."]},{"id":"c","label":"You''ve shown me what to hope for.","reaction":["Oh, that''s the kindest thing, dear. I may need to sit down. I''m already sitting.","I may need to sit down more. Thank you."]}],"outro":null}'::jsonb),
('DC-P01','adventure_friend_dc','Pool',1,1,'{"id":"DC-P01","friendId":"adventure_friend_dc","phase":"Pool","seq":1,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["We tried a dance class. A real one, with a teacher and everything.","Bartholomew stepped on my foot. On the second beat. Forty years of consistency. I wept with laughter."],"choices":[{"id":"a","label":"That''s perfect.","reaction":["It really was.","The instructor said ''it takes practice.'' I said ''we''ve had forty years.'' He said ''then you''re advanced.'' I''ve never felt so honored by a dance teacher."]},{"id":"b","label":"Did you enjoy it?","reaction":["Immensely. My hips complained for three days. My heart didn''t.","We held each other''s paws the whole time. I think we looked ridiculous and enchanting."]}],"outro":null}'::jsonb),
('DC-P02','adventure_friend_dc','Pool',2,1,'{"id":"DC-P02","friendId":"adventure_friend_dc","phase":"Pool","seq":2,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["Bartholomew wrote me a letter. A real one. With ink.","He left it under my teacup. It said, ''You''re still my favorite surprise.'' I read it fourteen times and then I put it in my knitting bag."],"choices":[{"id":"a","label":"That''s so romantic.","reaction":["It''s the most romantic thing he''s done since the turnip. He''s not a poet.","He''s a crossword man. But those words were poetry. Better than any sonnet."]},{"id":"b","label":"Fourteen times?","reaction":["I counted. It''s an old habit. Fourteen readings, and each time I noticed something new.","The way he crossed his T. A tiny smudge. He must have been nervous."]}],"outro":null}'::jsonb),
('DC-P03','adventure_friend_dc','Pool',3,1,'{"id":"DC-P03","friendId":"adventure_friend_dc","phase":"Pool","seq":3,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["We rearranged the living room. Together. Without arguing.","I moved the armchair. He moved it back. I moved it again. Eventually we agreed it looked best by the window. We both pretended it was my idea."],"choices":[{"id":"a","label":"Compromise at its finest.","reaction":["Indeed. Forty years of practice. We argue like old friends now.","It''s less a fight and more a dance with furniture. I rather like it."]},{"id":"b","label":"That''s very couple.","reaction":["It is, isn''t it? A little push, a little pull.","The chair ended up exactly where it started.","Which means all that effort was just a very elaborate form of flirting."]}],"outro":null}'::jsonb),
('DC-P04','adventure_friend_dc','Pool',4,1,'{"id":"DC-P04","friendId":"adventure_friend_dc","phase":"Pool","seq":4,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["We made pottery. A bowl. A very lopsided bowl.","Bartholomew said it looks like a ''rebellious pancake.'' I said it looks like us. He considered that for a moment and said, ''fair.''"],"choices":[{"id":"a","label":"A bowl that looks like you two.","reaction":["It''s perfect. Slightly crooked, held together by stubbornness, and surprisingly sturdy.","We use it for fruit now. Mostly it holds apples and our sense of humor."]},{"id":"b","label":"Rebellious pancake?","reaction":["He has a flair for names.","Last week he called the kettle ''sir.'' I''m told it''s affection. I''ve decided to believe him.","It makes mornings more interesting."]}],"outro":null}'::jsonb),
('DC-P05','adventure_friend_dc','Pool',5,1,'{"id":"DC-P05","friendId":"adventure_friend_dc","phase":"Pool","seq":5,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["We took a walk at dusk. Hand in hand. Like teenagers.","A young couple passed us and smiled. I felt a little proud. And a little shy. A badger can still blush, you know."],"choices":[{"id":"a","label":"That''s lovely.","reaction":["It was. We walked all the way to the pond and back.","He told me about his day for the first time in months.","I told him about mine. It was a small conversation. A great one."]},{"id":"b","label":"Like teenagers!","reaction":["Without the nervous giggling. Mostly. I may have giggled once. He pretended not to notice.","It''s one of the kindest things he does."]}],"outro":null}'::jsonb),
('DC-P06','adventure_friend_dc','Pool',6,1,'{"id":"DC-P06","friendId":"adventure_friend_dc","phase":"Pool","seq":6,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["I surprised Bartholomew with breakfast in bed. He nearly fell out of it.","He said, ''what''s the occasion?'' I said, ''Tuesday.'' He cried. Just a little. I pretended I didn''t notice."],"choices":[{"id":"a","label":"That''s so sweet.","reaction":["It was. Sometimes the best occasions are plain ones.","He said it was the nicest Tuesday of his life.","I thought, ''good. Let''s have more Tuesdays.''"]},{"id":"b","label":"He cried?","reaction":["A single tear. A very dignified one. He blamed it on the pepper.","There wasn''t any pepper. I let him have his excuse. Love includes graceful lies."]}],"outro":null}'::jsonb),
('DC-P07','adventure_friend_dc','Pool',7,1,'{"id":"DC-P07","friendId":"adventure_friend_dc","phase":"Pool","seq":7,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["We told each other three new things today. Things we''d never shared.","He told me he''s afraid of butterflies. After forty years! I told him I used to want to be a painter. He said, ''you still could.''"],"choices":[{"id":"a","label":"That''s so touching.","reaction":["It is. We''ve started a little game. Three new things a week.","It''s turned into the best thing we do.","I never thought I''d discover butterfly phobias at this age. Life is wonderful."]},{"id":"b","label":"He''s afraid of butterflies?","reaction":["Terrified. He says it''s their wings.","I said ''what about wings?'' He said ''they''re too... flappy.'' I''ve lived with this man for forty years and he''s still a surprise."]}],"outro":null}'::jsonb),
('DC-P08','adventure_friend_dc','Pool',8,1,'{"id":"DC-P08","friendId":"adventure_friend_dc","phase":"Pool","seq":8,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["I painted a little picture today. A watercolor of our porch.","Bartholomew hung it on the wall and told everyone it''s a masterpiece. It''s a blob with a chair. But I''ll take it."],"choices":[{"id":"a","label":"That''s adorable.","reaction":["He''s my biggest critic and my loudest fan.","I''ve never seen a man so proud of a blob.","I''m going to make him another one. Perhaps a turnip."]},{"id":"b","label":"Keep painting!","reaction":["I intend to. My hands shake a little, but the colors still sing.","I think that''s what age gives you. A shaky hand and a fearless brush."]}],"outro":null}'::jsonb),
('DC-P09','adventure_friend_dc','Pool',9,1,'{"id":"DC-P09","friendId":"adventure_friend_dc","phase":"Pool","seq":9,"familiarity":"Old Friend","type":"Callback","scene":null,"lines":["Remember the turnip dream? Bartholomew''s started a turnip garden.","He says it''s for ''research.'' I say it''s for love. We both pretend to be right. He talks to them. I think they listen."],"choices":[{"id":"a","label":"That''s so funny.","reaction":["It''s the tenderest thing. A man planting vegetables after a dream. He gave one a name.","''Sir Percival.'' I''m not sure how to feel. Mostly amused. And touched."]},{"id":"b","label":"Turnip research?","reaction":["He keeps notes. A tiny notebook.","''Day nine: Sir Percival looks thoughtful.'' It''s the most endearing document I''ve ever read.","I''m saving it for our grandchildren. If we ever have any."]}],"outro":null}'::jsonb),
('DC-P10','adventure_friend_dc','Pool',10,1,'{"id":"DC-P10","friendId":"adventure_friend_dc","phase":"Pool","seq":10,"familiarity":"Old Friend","type":"Callback","scene":null,"lines":["The Sunday tradition continues. Last week it was kite flying.","My kite got stuck in a tree. Bartholomew climbed it. At his age. I screamed. He waved. Then he fell. Gently. Onto a bush. We laughed for an hour."],"choices":[{"id":"a","label":"Is he okay?","reaction":["He''s fine. A bit scratched, mostly proud.","He says he was ''rescuing the kite.'' I say he was ''impressing me.'' Either way, it worked.","I''m still impressed."]},{"id":"b","label":"That''s quite an adventure.","reaction":["It truly was.","I think the secret to a long love is a regular supply of mild chaos.","Not the dangerous kind. The ''kite in a tree'' kind. It keeps the heart honest."]}],"outro":null}'::jsonb),
('DC-P11','adventure_friend_dc','Pool',11,1,'{"id":"DC-P11","friendId":"adventure_friend_dc","phase":"Pool","seq":11,"familiarity":"Old Friend","type":"Callback","scene":null,"lines":["I still have that scarf. Nine feet and growing.","I added a row for the stargazing night. A little silver thread. It''s the loveliest row yet."],"choices":[{"id":"a","label":"That''s beautiful.","reaction":["I think so too. The scarf is like a diary written in wool.","If someone unrolled it, they''d read forty years of tea, laughter, and the occasional argument about turnips."]},{"id":"b","label":"Is it almost done?","reaction":["Never. And I like that. A finished thing is a sort of ending.","I prefer to keep adding. A row for each good day.","It may end up reaching the moon."]}],"outro":null}'::jsonb),
('DC-P12','adventure_friend_dc','Pool',12,1,'{"id":"DC-P12","friendId":"adventure_friend_dc","phase":"Pool","seq":12,"familiarity":"Old Friend","type":"Callback","scene":null,"lines":["The three-new-things game? We''re up to forty-two.","Today I learned he once ate a whole pie in a bet. He lost the bet. But he won the pie. A questionable victory, but a delicious one."],"choices":[{"id":"a","label":"Forty-two!","reaction":["Isn''t it grand? I think we''ll still be playing at ninety.","We''ll say, ''I never told you about the pie.'' And the other will say, ''tell me everything.''"]},{"id":"b","label":"That sounds like a fun game.","reaction":["It''s the best thing we''ve done in years.","A weekly peek into a person you thought you knew. Turns out there are many rooms.","Some are full of pie."]}],"outro":null}'::jsonb),
('DC-P13','adventure_friend_dc','Pool',13,1,'{"id":"DC-P13","friendId":"adventure_friend_dc","phase":"Pool","seq":13,"familiarity":"Old Friend","type":"HotTake","scene":null,"lines":["Hot take: Long love isn''t about never getting bored. It''s about getting curious again."],"choices":[{"id":"a","label":"That''s wise.","reaction":["Thank you, dear. It took me forty years to put it into a sentence.","And I''m still not sure I''ve got it right. But I like how it sounds."]},{"id":"b","label":"I think both matter.","reaction":["Indeed. A little boredom is natural. It''s like fallow soil.","It just needs a bit of attention and a few seeds. Or a turnip."]}],"outro":null}'::jsonb),
('DC-P14','adventure_friend_dc','Pool',14,1,'{"id":"DC-P14","friendId":"adventure_friend_dc","phase":"Pool","seq":14,"familiarity":"Old Friend","type":"HotTake","scene":null,"lines":["Hot take: A good partner is someone who still surprises you at breakfast."],"choices":[{"id":"a","label":"I love that.","reaction":["Me too. Bartholomew once served me toast in the shape of a heart. It was burnt.","It was perfect. I still have the crumbs. In a tiny box. Don''t tell anyone."]},{"id":"b","label":"Breakfast is important.","reaction":["Terribly important. A day that begins with tenderness has a chance.","A day that begins with a cold biscuit is a gamble.","I''m a gambler, but I prefer warm toast."]}],"outro":null}'::jsonb),
('DC-P15','adventure_friend_dc','Pool',15,1,'{"id":"DC-P15","friendId":"adventure_friend_dc","phase":"Pool","seq":15,"familiarity":"Old Friend","type":"HotTake","scene":null,"lines":["Hot take: Growing old together is the greatest adventure, and no one warns you how funny it is."],"choices":[{"id":"a","label":"That''s so true.","reaction":["Funny, tender, and sometimes tragic about knees. But mostly funny.","I wouldn''t trade a creak for anything. Not even the creak in my left hip."]},{"id":"b","label":"It sounds fun.","reaction":["It really is. Don''t let anyone tell you otherwise. There''s mischief in old love.","We play tricks. We hide each other''s glasses. It''s a game that never ends."]}],"outro":null}'::jsonb),
('DC-P16','adventure_friend_dc','Pool',16,1,'{"id":"DC-P16","friendId":"adventure_friend_dc","phase":"Pool","seq":16,"familiarity":"Old Friend","type":"AskBack","scene":null,"lines":["What do you and your partner do that no one else knows about?","Bartholomew and I have a secret handshake. Four taps and a wink. Don''t tell."],"choices":[{"id":"a","label":"We have a nickname for each other.","reaction":["A nickname! How delightful. Private names are the heartbeat of intimacy. Bartholomew calls me ''Duchess'' still.","Forty years of royalty. It never gets old."]},{"id":"b","label":"We share a silly ritual.","reaction":["Silly rituals are the very best kind. They''re like secret tunnels between two hearts.","I hope you keep it forever. Even when you forget why it started."]}],"outro":null}'::jsonb),
('DC-P17','adventure_friend_dc','Pool',17,1,'{"id":"DC-P17","friendId":"adventure_friend_dc","phase":"Pool","seq":17,"familiarity":"Old Friend","type":"AskBack","scene":null,"lines":["How do you comfort each other when things are hard?","I''m curious. I never tire of learning how others do it."],"choices":[{"id":"a","label":"We just stay close.","reaction":["Staying close. The simplest and the hardest thing. Bartholomew does that. No words.","Just a hand on my shoulder. It''s all I''ve ever needed. I think."]},{"id":"b","label":"We try to make each other laugh.","reaction":["Laughter. A noble medicine. We have a joke about a turnip that works every time.","I won''t explain it. It involves a hat. And Sir Percival."]}],"outro":null}'::jsonb),
('DC-P18','adventure_friend_dc','Pool',18,1,'{"id":"DC-P18","friendId":"adventure_friend_dc","phase":"Pool","seq":18,"familiarity":"Old Friend","type":"AskBack","scene":null,"lines":["What''s something you want to do with your partner someday?","I love a good plan. A dream, I mean. The older I get, the more I love dreams."],"choices":[{"id":"a","label":"Travel somewhere new together.","reaction":["Travel. Oh, yes. Bartholomew and I always said we''d see the sea. We never did.","Perhaps this year. I''ll pack the knitting. He''ll pack the crossword. And a very large turnip."]},{"id":"b","label":"Learn something new together.","reaction":["A marvelous idea. We''ve started pottery. Perhaps next year, a language. French, I think.","''Je t''aime'' sounds better with a badger accent. Don''t you agree?"]}],"outro":null}'::jsonb),
('DC-P19','adventure_friend_dc','Pool',19,0.25,'{"id":"DC-P19","friendId":"adventure_friend_dc","phase":"Pool","seq":19,"familiarity":"Old Friend","type":"Rare","scene":"Duchess hands you a small, slightly crooked bowl.","lines":["This is the bowl Bartholomew and I made. The rebellious pancake.","I want you to have it. Fill it with anything. Apples. Pebbles. Love letters. It holds all of them."],"choices":[{"id":"a","label":"I''ll treasure it.","reaction":["I know you will. That''s why I''m giving it to you.","Some things are best passed along. It''s a bit lopsided, but so is life.","And so, my dear, is love. In the best way."]},{"id":"b","label":"Are you sure?","reaction":["Quite sure. We made another. It''s even more crooked. It''s our masterpiece.","Please keep it, and think of two old badgers who learned to laugh again."]}],"outro":null}'::jsonb),
('DC-P20','adventure_friend_dc','Pool',20,0.25,'{"id":"DC-P20","friendId":"adventure_friend_dc","phase":"Pool","seq":20,"familiarity":"Old Friend","type":"Rare","scene":"Bartholomew shuffles in, adjusts his hat, and tips it to you with great ceremony.","lines":["Ah. The friend. Duchess speaks highly of you.","She says you listen. A rare gift. Thank you for it. I''m not always so good at it myself. But I''m learning. Slowly. Like a turnip."],"choices":[{"id":"a","label":"Duchess is wonderful.","reaction":["She is. She is quite simply the best part of every day.","I forget to say so, you know. I''m going to say it tonight.","Possibly with a heart-shaped toast."]},{"id":"b","label":"It''s nice to meet you, Bartholomew.","reaction":["And you, dear. Please, sit. I''ll put the kettle on.","Duchess will tell stories and I''ll pretend I haven''t heard them.","Forty years, and I still laugh at the good ones."]}],"outro":null}'::jsonb)
