insert into public.friend_definitions(stable_id,revision_id,name,subtitle,art,metadata,is_placeholder) values('adventure_friend_ar',coalesce((select value from public.app_config where key='app_major_update_content_revision'),'burrow-v1-placeholder'),'Arlo','Small thing, but...','{"renderer":"bundled","key":"Aardvark"}'::jsonb,'{"adventureV2":true,"code":"AR","gender":"he","species":"Aardvark"}'::jsonb,false) on conflict(stable_id) do update set name=excluded.name,subtitle=excluded.subtitle,art=excluded.art,metadata=excluded.metadata,status='active',updated_at=now();
insert into public.adventure_dialogues_v2(id,friend_id,phase,seq,weight,content) values
('AR-01','adventure_friend_ar','Intro',1,1,'{"id":"AR-01","friendId":"adventure_friend_ar","phase":"Intro","seq":1,"familiarity":"Stranger","type":"Statement","scene":"Arlo is sniffing at a hole in the tunnel wall, looking tired but happy.","lines":["Oh! A new face. Sorry, I''m checking if this hole is mine or Pia''s.","Three years living together. We still own two of everything.","Small thing, but she squeezes the toothpaste from the MIDDLE."],"choices":[{"id":"a","label":"That''s a crime, honestly.","reaction":["Right?! Thank you. She''ll say it''s tradition.","Anyway, it''s cute. I think."]},{"id":"b","label":"Do they at least do the dishes?","reaction":["She does! With a song. A bad song.","I''d miss it if she stopped."]},{"id":"c","label":"Nod slowly.","reaction":["You get it. You really do.","Okay, I''m gonna go fix the toothpaste. Gently."]}],"outro":null}'::jsonb),
('AR-02','adventure_friend_ar','Intro',2,1,'{"id":"AR-02","friendId":"adventure_friend_ar","phase":"Intro","seq":2,"familiarity":"Familiar Face","type":"Statement","scene":null,"lines":["Hey, it''s you again! Toothpaste update.","I bought a second tube. Hers and mine. A peace treaty.","Small thing, but she STILL uses mine."],"choices":[{"id":"a","label":"Maybe she likes yours.","reaction":["...Oh. Huh. I never thought of that.","Mine is the minty one. She might just like mint."]},{"id":"b","label":"Hide yours.","reaction":["I tried. She found it in four minutes.","She has a nose for toothpaste. It''s scary."]},{"id":"c","label":"Laugh quietly.","reaction":["Go ahead, it''s funny.","Tube war, day nine hundred and something."]}],"outro":null}'::jsonb),
('AR-03','adventure_friend_ar','Intro',3,1,'{"id":"AR-03","friendId":"adventure_friend_ar","phase":"Intro","seq":3,"familiarity":"Acquaintance","type":"Statement","scene":"Arlo is lining up single socks along a wall like a tiny exhibit.","lines":["Pia leaves one sock on the floor. Always one. Never a pair.","I found seventeen single socks this week. So I started a museum."],"choices":[{"id":"a","label":"A sock museum?","reaction":["Admission is free. Gift shop is also socks.","Pia loves it. She donated one this morning."]},{"id":"b","label":"Does she know?","reaction":["She''s the curator. She names them.","That one is ''Gerald.'' Don''t ask."]},{"id":"c","label":"Pick up a sock.","reaction":["Careful. That''s an early piece.","...You have a good eye for socks."]}],"outro":null}'::jsonb),
('AR-04','adventure_friend_ar','Intro',4,1,'{"id":"AR-04","friendId":"adventure_friend_ar","phase":"Intro","seq":4,"familiarity":"Acquaintance","type":"Statement","scene":null,"lines":["Pia hums while she cooks. Off-key. Every single time.","Small thing, but yesterday she stopped humming and I panicked.","She was just tasting the soup. I almost asked if she was okay."],"choices":[{"id":"a","label":"You noticed the quiet.","reaction":["I did. I always notice the tiny stuff.","It turns out I''d miss the off-key more than any silence."]},{"id":"b","label":"Aww.","reaction":["Don''t aww me. I''m trying to be mad about the humming.","...I''m not mad. I lost that fight a long time ago."]},{"id":"c","label":"Hum along a little.","reaction":["Oh no, you''re off-key too.","Welcome to the family. Gently."]}],"outro":null}'::jsonb),
('AR-05','adventure_friend_ar','Intro',5,1,'{"id":"AR-05","friendId":"adventure_friend_ar","phase":"Intro","seq":5,"familiarity":"Friend","type":"Ask","scene":null,"lines":["Quick question. When your partner does something small and annoying, do you say it or let it go?","I never know which one is the right move."],"choices":[{"id":"a","label":"Let it go, mostly.","reaction":["Same, same. Until it''s the fortieth time.","Then it comes out as a weird joke. Pia hates my weird jokes."]},{"id":"b","label":"I say it, gently.","reaction":["Gently. Okay. I''m bad at gently.","I do loud and then I apologize with snacks."]},{"id":"c","label":"Depends on the day.","reaction":["Honestly? Fair.","Some days a sock is a sock. Some days it''s a whole mood."]}],"outro":null}'::jsonb),
('AR-06','adventure_friend_ar','Intro',6,1,'{"id":"AR-06","friendId":"adventure_friend_ar","phase":"Intro","seq":6,"familiarity":"Friend","type":"Statement","scene":"Arlo is wearing a slightly too small apron that says WORLD''S OKAYEST COOK.","lines":["Pia says I hum when I eat. Loudly. A little growl.","I had no idea! Three years! Nobody told me!","Turns out I have annoying things too. Small thing, but... fair."],"choices":[{"id":"a","label":"What does the growl sound like?","reaction":["She says it''s like a tiny engine. A happy engine.","...I think that''s a compliment?"]},{"id":"b","label":"Equal rights for annoyances.","reaction":["Exactly. A balanced household.","We keep a tally on the wall. It''s tied, mostly."]},{"id":"c","label":"Pretend you didn''t hear it.","reaction":["Too late. I know what I sound like now.","Hm. Hm-hm-hm. Hm. Okay, I''ll be normal."]}],"outro":null}'::jsonb),
('AR-07','adventure_friend_ar','Intro',7,1,'{"id":"AR-07","friendId":"adventure_friend_ar","phase":"Intro","seq":7,"familiarity":"Close Friend","type":"Confide","scene":"Arlo sits down slowly, quiet for once.","lines":["Sometimes I wonder if the small things add up.","Like thirty tiny annoyances, and then one day it''s a big one.","But last night Pia fell asleep on my shoulder mid-sentence. Tiny thing. It erased all thirty."],"choices":[{"id":"a","label":"Tiny things work both ways.","reaction":["Yeah. They do. I keep forgetting that.","The good ones are small too. I just have to notice them."]},{"id":"b","label":"Did you tell her?","reaction":["...No. I just stayed very still so she wouldn''t wake up.","Maybe I''ll tell her tomorrow. With a snack."]},{"id":"c","label":"Listen quietly.","reaction":["Thanks. Not everything needs a fix.","Sometimes it just needs a shoulder. Mine was numb for an hour. Worth it."]}],"outro":null}'::jsonb),
('AR-08','adventure_friend_ar','Intro',8,1,'{"id":"AR-08","friendId":"adventure_friend_ar","phase":"Intro","seq":8,"familiarity":"Close Friend","type":"Statement","scene":null,"lines":["We made a rule. Anything annoying gets said with a snack.","It''s silly. It works. Pia brings the snack first, then the sentence.","Yesterday she brought three snacks. I was nervous. It was about the sock museum."],"choices":[{"id":"a","label":"A snack warning system.","reaction":["Exactly. A small crunch before a big feeling.","I''ve started making the snack before I even know what to say."]},{"id":"b","label":"What was the sock thing?","reaction":["She wants to retire Gerald. I said no. We compromised.","Gerald stays. In a smaller frame."]},{"id":"c","label":"Ask for a snack.","reaction":["Ha! Here. Ant crackers. Don''t tell Pia I''ve been sharing.","You can''t tell her anything is annoying, okay? Rule''s rule."]}],"outro":null}'::jsonb),
('AR-09','adventure_friend_ar','Intro',9,1,'{"id":"AR-09","friendId":"adventure_friend_ar","phase":"Intro","seq":9,"familiarity":"Best Friend","type":"Companion","scene":"Arlo spreads a leaf on the ground and sets out tiny carved bug-shaped crackers.","lines":["I made a practice picnic! Pia''s at work. We''re doing one tomorrow.","Just sit with me. Tell me if the tiny sandwiches look weird."],"choices":[{"id":"a","label":"They look great.","reaction":["Really? I''m so nervous it''s silly.","She''s going to say ''aww'' and then eat the whole plate."]},{"id":"b","label":"Add a flower.","reaction":["Ooh. A flower. That''s a Pia move. Good eye.","See, this is why I show you things."]},{"id":"c","label":"Take a bite.","reaction":["Well? ...Good? Great. I''m cooking for you forever.","Kidding. Mostly. I''ll do the hum."]}],"outro":null}'::jsonb),
('AR-10','adventure_friend_ar','Intro',10,1,'{"id":"AR-10","friendId":"adventure_friend_ar","phase":"Intro","seq":10,"familiarity":"Old Friend","type":"Milestone","scene":null,"lines":["Ten times. That''s more than the pairs of socks Pia owns.","She told me yesterday I''m her favorite weird. Small thing, but I keep it in my chest.","Your turn. How are you and your partner doing? Honest."],"choices":[{"id":"a","label":"We''re good. Still learning.","reaction":["Learning is the whole thing, I think.","Come over. We''ll do the picnic. Pia will insist on a toast."]},{"id":"b","label":"We had a rough week, honestly.","reaction":["Rough weeks are real. Small things stack up. I know.","Come by. We''ll feed you both, no questions."]},{"id":"c","label":"Better since I started noticing small things.","reaction":["Yes! That''s it! That''s the whole secret.","Okay, picnic. Tomorrow. You''re in."]}],"outro":null}'::jsonb),
('AR-P01','adventure_friend_ar','Pool',1,1,'{"id":"AR-P01","friendId":"adventure_friend_ar","phase":"Pool","seq":1,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["Pia rearranged our burrow while I was out. Moved the bed. Moved the lamp. Moved ME.","I walked into the wall in the dark."],"choices":[{"id":"a","label":"Did you fall?","reaction":["Gently. Like a leaf. A very confused leaf.","She said ''sorry'' and laughed for ten minutes. I laughed too."]},{"id":"b","label":"Rearranging is a love language.","reaction":["It''s a chaos language. But okay, I''ll take it.","The new layout is actually better. Don''t tell her."]}],"outro":null}'::jsonb),
('AR-P02','adventure_friend_ar','Pool',2,1,'{"id":"AR-P02","friendId":"adventure_friend_ar","phase":"Pool","seq":2,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["I forgot our anniversary by one day. I panicked and wrote ''sorry'' in ant trails on the floor.","Pia stepped on it. Then she cried laughing."],"choices":[{"id":"a","label":"A cute apology.","reaction":["I thought so. Ants did all the work.","She said it was the best apology she''s gotten. Low bar. High effort."]},{"id":"b","label":"Did she forgive you?","reaction":["Before I finished the second ''r''.","She just wanted the dinner we skipped. We had it at midnight."]}],"outro":null}'::jsonb),
('AR-P03','adventure_friend_ar','Pool',3,1,'{"id":"AR-P03","friendId":"adventure_friend_ar","phase":"Pool","seq":3,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["Pia and I tried a no-phones dinner. We lasted six minutes.","Then she put hers in a drawer. I put mine in the sock museum."],"choices":[{"id":"a","label":"The sock museum holds phones now?","reaction":["Only for emergencies. And dinner. Both fancy.","It felt weirdly romantic. Two phones, side by side. Sleeping.","We might try again Sunday. With a timer shaped like a snail."]},{"id":"b","label":"Six minutes is a start.","reaction":["Right? Next time, nine.","We''re gonna be monks by spring.","Baby steps. Tiny, slightly clumsy ones. That''s our whole thing."]}],"outro":null}'::jsonb),
('AR-P04','adventure_friend_ar','Pool',4,1,'{"id":"AR-P04","friendId":"adventure_friend_ar","phase":"Pool","seq":4,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["I tried to fix a leaky tunnel roof by myself. To impress Pia.","It leaked faster. She found me under a bucket."],"choices":[{"id":"a","label":"Bucket hat energy.","reaction":["She said that exact thing! I''m wearing it now. Officially.","She fixed the roof in two minutes. Humbling."]},{"id":"b","label":"Did she laugh?","reaction":["Yes. Then she held the bucket while I fixed it.","We were both soaked. Best date of the month."]}],"outro":null}'::jsonb),
('AR-P05','adventure_friend_ar','Pool',5,1,'{"id":"AR-P05","friendId":"adventure_friend_ar","phase":"Pool","seq":5,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["Pia asked what I wanted for my birthday. I said ''nothing.'' She looked at me for a full minute.","So I said ''okay, one dumb thing.'' She wrote it down."],"choices":[{"id":"a","label":"What was the dumb thing?","reaction":["A little jar of dirt from where we first met.","I know. Embarrassing. She''s making it a jar with a ribbon."]},{"id":"b","label":"That''s not dumb.","reaction":["You''re kind. It''s a little dumb. It''s also the best gift.","I might cry on my birthday. I''m warning you."]}],"outro":null}'::jsonb),
('AR-P06','adventure_friend_ar','Pool',6,1,'{"id":"AR-P06","friendId":"adventure_friend_ar","phase":"Pool","seq":6,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["We argued about whose turn it was to cook. Neither wanted to. Neither wanted to say it.","We ate crackers for dinner and watched the ceiling."],"choices":[{"id":"a","label":"Cracker night is underrated.","reaction":["Ceiling night too. That''s a whole genre.","We made up shapes in the cracks. Pia found a bunny."]},{"id":"b","label":"Did you say sorry?","reaction":["We both did. At the same time. Same words.","Then we argued about who said it first. Peak us."]}],"outro":null}'::jsonb),
('AR-P07','adventure_friend_ar','Pool',7,1,'{"id":"AR-P07","friendId":"adventure_friend_ar","phase":"Pool","seq":7,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["Pia caught me practicing a compliment in the mirror.","I was saying ''you look nice'' with different faces."],"choices":[{"id":"a","label":"Which face won?","reaction":["The soft one. The ''I mean it'' one.","She said all three worked. Then asked why I needed three."]},{"id":"b","label":"That''s really sweet.","reaction":["It''s embarrassing and sweet. Both. At once.","I''m going to do it again next week.","I''m adding a fourth face. Tender but also slightly goofy."]}],"outro":null}'::jsonb),
('AR-P08','adventure_friend_ar','Pool',8,1,'{"id":"AR-P08","friendId":"adventure_friend_ar","phase":"Pool","seq":8,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["Pia surprised me with new socks. A matching pair. Her first ever.","I didn''t know what to do. I held them like a baby."],"choices":[{"id":"a","label":"A matching pair!","reaction":["For the sock museum. ''Exhibit One: The Pair.''","She''s growing. We both are.","She also got me tiny gloves, for no reason at all."]},{"id":"b","label":"Wear them to dinner.","reaction":["I did. She noticed and pretended not to.","That''s how I knew she noticed.","I wore them on a walk. We matched our steps."]}],"outro":null}'::jsonb),
('AR-P09','adventure_friend_ar','Pool',9,1,'{"id":"AR-P09","friendId":"adventure_friend_ar","phase":"Pool","seq":9,"familiarity":"Old Friend","type":"Callback","scene":null,"lines":["Remember the toothpaste thing? We''re up to three tubes now.","Pia''s, mine, and a ''neutral zone'' tube we both use."],"choices":[{"id":"a","label":"A peace tube.","reaction":["Diplomatic toothpaste. Very mature.","Last week she squeezed it from the middle. I said nothing. Growth.","Pia says we should write a treaty. I''m drafting the preamble."]},{"id":"b","label":"Still a crime.","reaction":["Always. But a loving crime.","Some crimes you just let slide.","Pia agrees. She still does it and she''s proud of it."]}],"outro":null}'::jsonb),
('AR-P10','adventure_friend_ar','Pool',10,1,'{"id":"AR-P10","friendId":"adventure_friend_ar","phase":"Pool","seq":10,"familiarity":"Old Friend","type":"Callback","scene":null,"lines":["Gerald the sock got his own tiny frame. Pia wrote a plaque.","''Gerald. Beloved. Missing his other half since Spring.''"],"choices":[{"id":"a","label":"Poor Gerald.","reaction":["I know. We keep an eye out for him.","If you find a match, I''ll know. And I''ll cry."]},{"id":"b","label":"Best museum ever.","reaction":["High praise. The reviews are in: five stars.","One review is from Pia. It''s mostly emojis.","We''re thinking of a gift shop. It would only sell used socks."]}],"outro":null}'::jsonb),
('AR-P11','adventure_friend_ar','Pool',11,1,'{"id":"AR-P11","friendId":"adventure_friend_ar","phase":"Pool","seq":11,"familiarity":"Old Friend","type":"Callback","scene":null,"lines":["I still think about the snack rule. It''s the best thing we ever did.","Yesterday I said ''I felt left out'' and passed a cracker. She just hugged me."],"choices":[{"id":"a","label":"That''s so sweet.","reaction":["I thought I''d mess it up. I didn''t.","The cracker did half the work. Honestly.","Next up: a rule for apologies. Cookies are involved."]},{"id":"b","label":"A cracker is a tiny white flag.","reaction":["Yes! A flag with sesame seeds.","Maybe I should design flags. Small thing, but I have ideas.","I want to draw a flag with an ant on it. Strong branding."]}],"outro":null}'::jsonb),
('AR-P12','adventure_friend_ar','Pool',12,1,'{"id":"AR-P12","friendId":"adventure_friend_ar","phase":"Pool","seq":12,"familiarity":"Old Friend","type":"Callback","scene":null,"lines":["Remember the practice picnic? We did the real one.","Pia ate the whole plate and said ''aww'' exactly like I predicted."],"choices":[{"id":"a","label":"Called it.","reaction":["I know her patterns now. Small thing, big win.","She also left a note in the basket. I''m keeping it forever."]},{"id":"b","label":"Did she cry?","reaction":["A little. Happy crying. The best crying.","I did too. We looked like two leaky roofs.","We stayed until the stars came out. Nobody talked much."]}],"outro":null}'::jsonb),
('AR-P13','adventure_friend_ar','Pool',13,1,'{"id":"AR-P13","friendId":"adventure_friend_ar","phase":"Pool","seq":13,"familiarity":"Old Friend","type":"HotTake","scene":null,"lines":["Hot take: love is mostly noticing.","Not big gestures. Just noticing when they''re tired or humming or sad.","Don''t quote me. I''m an aardvark."],"choices":[{"id":"a","label":"That''s a good take.","reaction":["Thanks. I came up with it in the tunnel.","It took me nine tunnels. Worth it.","I learned it from Pia. She notices everything, even my sock count."]},{"id":"b","label":"What if you don''t notice?","reaction":["Then you say ''hey, I missed it, tell me.''","That counts as noticing too. I''m pretty sure.","Noticing counts too. Even asking for help. Especially that."]}],"outro":null}'::jsonb),
('AR-P14','adventure_friend_ar','Pool',14,1,'{"id":"AR-P14","friendId":"adventure_friend_ar","phase":"Pool","seq":14,"familiarity":"Old Friend","type":"HotTake","scene":null,"lines":["Hot take: you can love someone and still hate how they chew.","Both things are true. At the same time. In my ears."],"choices":[{"id":"a","label":"Fair. Totally fair.","reaction":["Thank you! Chewing is a lot.","I chew like a small thunderstorm, apparently.","We recorded each other chewing once. We cried laughing."]},{"id":"b","label":"Does she say it?","reaction":["She says ''chewing, babe.'' With a smile. It works.","We''re both weird chewers. It evens out.","Love means making peace with each other''s noises."]}],"outro":null}'::jsonb),
('AR-P15','adventure_friend_ar','Pool',15,1,'{"id":"AR-P15","friendId":"adventure_friend_ar","phase":"Pool","seq":15,"familiarity":"Old Friend","type":"HotTake","scene":null,"lines":["Hot take: tidying up their mess without saying anything is romantic.","But also the second time, you can ask for a thank-you."],"choices":[{"id":"a","label":"A silent thank-you counts.","reaction":["Exactly. A look. A kiss on the head. Something.","Even a cracker. I''m easy.","She says thank you with a loud kiss. Hard to top."]},{"id":"b","label":"Ask for the thank-you.","reaction":["Yes. Loudly. With a snack.","Balance. Always balance.","We keep it light. Nobody keeps score except the sock museum."]}],"outro":null}'::jsonb),
('AR-P16','adventure_friend_ar','Pool',16,1,'{"id":"AR-P16","friendId":"adventure_friend_ar","phase":"Pool","seq":16,"familiarity":"Old Friend","type":"AskBack","scene":null,"lines":["Okay, important question. What''s your partner''s tiniest annoying habit?","The one you secretly love. Go."],"choices":[{"id":"a","label":"They hum while they cook.","reaction":["Pia hums too! Cooking hummers unite.","I could listen to that forever. Don''t tell her I said that."]},{"id":"b","label":"They leave doors open.","reaction":["The classic. A little draft, a little love.","Close one. Open one. Repeat. It''s a whole dance.","Open doors and hummed songs. They''re love in small clothes."]}],"outro":null}'::jsonb),
('AR-P17','adventure_friend_ar','Pool',17,1,'{"id":"AR-P17","friendId":"adventure_friend_ar","phase":"Pool","seq":17,"familiarity":"Old Friend","type":"AskBack","scene":null,"lines":["How do you and your partner say sorry? Words? Snacks? Silence?","I''m collecting methods. For science."],"choices":[{"id":"a","label":"Mostly words.","reaction":["Words. Good. Strong. Direct.","I''m learning to use more words and fewer crackers.","Words are brave. Mine just need a snack in between."]},{"id":"b","label":"A hug first.","reaction":["Hug first. Words later. That''s smart.","Sometimes my words come out wrong. Hugs never do.","Hugs fix half the words. The other half need crackers."]}],"outro":null}'::jsonb),
('AR-P18','adventure_friend_ar','Pool',18,1,'{"id":"AR-P18","friendId":"adventure_friend_ar","phase":"Pool","seq":18,"familiarity":"Old Friend","type":"AskBack","scene":null,"lines":["What''s something small your partner did recently that made you smile?","I need happy stories. Today was a socks day."],"choices":[{"id":"a","label":"They made me tea.","reaction":["Tea. Simple. Perfect. I''m tearing up.","Pia makes tea too. Burned. I drink it anyway.","Tea is a hug you can drink. Pia taught me that."]},{"id":"b","label":"They saved me a seat.","reaction":["Saving a seat is the best love language.","It means ''I thought about you while you weren''t here.''"]}],"outro":null}'::jsonb),
('AR-P19','adventure_friend_ar','Pool',19,0.25,'{"id":"AR-P19","friendId":"adventure_friend_ar","phase":"Pool","seq":19,"familiarity":"Old Friend","type":"Rare","scene":"Arlo is holding a tiny glowing jar of soil and trying to look casual.","lines":["Okay. So. This is the dirt from where Pia and I first met.","I carry it in my pocket on bad days.","It''s silly. It''s also the only thing that works."],"choices":[{"id":"a","label":"It''s not silly at all.","reaction":["Thank you. I needed someone to say that.","I''ll carry it a little taller today.","I''ll keep carrying it. Smaller than a sock, bigger than a worry."]},{"id":"b","label":"Hold it with Arlo.","reaction":["Oh. You''re holding the jar. That''s... that''s big.","We''re a very small club now. Welcome.","Some days we carry things together. That''s all it is."]}],"outro":null}'::jsonb),
('AR-P20','adventure_friend_ar','Pool',20,0.25,'{"id":"AR-P20","friendId":"adventure_friend_ar","phase":"Pool","seq":20,"familiarity":"Old Friend","type":"Rare","scene":"Arlo''s eyes are shiny. He stands very straight.","lines":["I wrote Pia a letter. A real one. Three lines.","Line one: thank you. Line two: I notice you. Line three: I''m still here.","I''m scared to give it to her."],"choices":[{"id":"a","label":"Give it to her tonight.","reaction":["Tonight. Okay. Tonight. With a snack.","If I faint, tell the sock museum I loved them.","I''ll leave it under her pillow. She''ll find it in the morning."]},{"id":"b","label":"Three lines is perfect.","reaction":["Three lines. Small thing, but it''s everything.","You''re a good friend. I''m saying that out loud.","I''ll sign it with a tiny paw print. Extra credit."]}],"outro":null}'::jsonb)
