insert into public.friend_definitions(stable_id,revision_id,name,subtitle,art,metadata,is_placeholder) values('adventure_friend_fn',coalesce((select value from public.app_config where key='app_major_update_content_revision'),'burrow-v1-placeholder'),'Fenn','It''s a SIGN.','{"renderer":"bundled","key":"Frog"}'::jsonb,'{"adventureV2":true,"code":"FN","gender":"he","species":"Frog"}'::jsonb,false) on conflict(stable_id) do update set name=excluded.name,subtitle=excluded.subtitle,art=excluded.art,metadata=excluded.metadata,status='active',updated_at=now();
insert into public.adventure_dialogues_v2(id,friend_id,phase,seq,weight,content) values
('FN-01','adventure_friend_fn','Intro',1,1,'{"id":"FN-01","friendId":"adventure_friend_fn","phase":"Intro","seq":1,"familiarity":"Stranger","type":"Statement","scene":"Fenn is staring at a puddle, holding a single pebble.","lines":["Shh. Look. The puddle is shaped like a heart.","Lily and I met at the exact same kind of puddle. It''s a SIGN.","I''m gonna ask her on a walk. Do you think that''s too much?"],"choices":[{"id":"a","label":"Not too much. It''s sweet.","reaction":["You think? Okay, I''m doing it.","I already wrote a speech. Don''t tell her."]},{"id":"b","label":"Maybe skip the speech?","reaction":["...The speech is four pages.","Okay, three. Maybe."]},{"id":"c","label":"Look at the puddle too.","reaction":["See?! You see it!","You''re officially in the sign club."]}],"outro":null}'::jsonb),
('FN-02','adventure_friend_fn','Intro',2,1,'{"id":"FN-02","friendId":"adventure_friend_fn","phase":"Intro","seq":2,"familiarity":"Familiar Face","type":"Statement","scene":null,"lines":["It''s you! The one from the heart puddle!","Lily said yes to the walk. We walked. Eleven steps.","Then it rained, and I took that as a SIGN."],"choices":[{"id":"a","label":"A sign for what?","reaction":["That we should dance in it. So we did.","I''m still wet. I''ve never been happier."]},{"id":"b","label":"Eleven steps?","reaction":["Eleven steps of pure romance. Each one counted.","I''m framing the footprints."]},{"id":"c","label":"Cheer quietly.","reaction":["Thank you. Cheering is the correct response.","I may cry. Nobody look."]}],"outro":null}'::jsonb),
('FN-03','adventure_friend_fn','Intro',3,1,'{"id":"FN-03","friendId":"adventure_friend_fn","phase":"Intro","seq":3,"familiarity":"Acquaintance","type":"Statement","scene":"Fenn is arranging pebbles into letters on a lily pad.","lines":["I''m writing Lily a message in pebbles.","It says ''I love you'' but the ''v'' keeps rolling away.","Is that a sign? That ''v'' doesn''t want to be said?"],"choices":[{"id":"a","label":"It''s just a rolling pebble.","reaction":["...Fair. Pebbles roll. It''s their job.","Still. I''m going to glue the ''v''."]},{"id":"b","label":"Maybe it''s a sign to say it out loud.","reaction":["Out loud?! Like with my mouth?!","Okay. Okay. Deep breath. Ribbit."]},{"id":"c","label":"Hold the ''v'' in place.","reaction":["Yes! Thank you! Don''t let go. I''m taking a photo.","We''re making history. A tiny pebble history."]}],"outro":null}'::jsonb),
('FN-04','adventure_friend_fn','Intro',4,1,'{"id":"FN-04","friendId":"adventure_friend_fn","phase":"Intro","seq":4,"familiarity":"Acquaintance","type":"Statement","scene":null,"lines":["Lily forgot our little anniversary. The one for our first puddle.","I said ''it''s fine!'' in a very high voice.","It is NOT fine. But it''s also a small thing. Right?"],"choices":[{"id":"a","label":"It''s okay to feel sad.","reaction":["Thank you. I was pretending so hard.","I''ll tell her tonight. In a calm voice. Not the high one."]},{"id":"b","label":"Forgetting happens.","reaction":["I know. I forget things too. Her birthday socks last year.","Okay. I''ll let it go. Mostly. Eighty percent."]},{"id":"c","label":"Offer a snack.","reaction":["...A fly snack. Yes. Thank you.","Snacks and sadness. Classic combo."]}],"outro":null}'::jsonb),
('FN-05','adventure_friend_fn','Intro',5,1,'{"id":"FN-05","friendId":"adventure_friend_fn","phase":"Intro","seq":5,"familiarity":"Friend","type":"Ask","scene":null,"lines":["Quick question. Do you and your partner have a thing? Like a song, a place, a word?","Something that''s just yours."],"choices":[{"id":"a","label":"We have a song.","reaction":["A SONG. Tell me it''s cheesy. Please be cheesy.","Cheesy is the best. Cheesy is romantic."]},{"id":"b","label":"A silly inside joke.","reaction":["Inside jokes are the best love language. They''re tiny secrets.","I bet it''s super dumb and perfect."]},{"id":"c","label":"Not sure we do.","reaction":["That''s okay. You could start one today.","Say a weird word. Whatever you say first. That''s it."]}],"outro":null}'::jsonb),
('FN-06','adventure_friend_fn','Intro',6,1,'{"id":"FN-06","friendId":"adventure_friend_fn","phase":"Intro","seq":6,"familiarity":"Friend","type":"Statement","scene":"Fenn is wearing a tiny crown of clover and trying to look casual.","lines":["I made Lily a crown. It took nine hours.","It fell apart twice. I made it again. Out of spite and love.","She wore it to dinner. In public. In FRONT of people."],"choices":[{"id":"a","label":"That''s so romantic.","reaction":["Isn''t it?! I almost fainted into the soup.","Everyone clapped. It was a small clap. A kind clap."]},{"id":"b","label":"Nine hours?","reaction":["Nine hours. Four clovers per hour. I did the math. Twice.","Worth every petal."]},{"id":"c","label":"Applaud softly.","reaction":["Thank you. Applause accepted.","I bow to the crown. Not to myself. Mostly."]}],"outro":null}'::jsonb),
('FN-07','adventure_friend_fn','Intro',7,1,'{"id":"FN-07","friendId":"adventure_friend_fn","phase":"Intro","seq":7,"familiarity":"Close Friend","type":"Confide","scene":"Fenn sits at the edge of the water, looking at his reflection.","lines":["Can I tell you something un-sign-like?","Sometimes I think I''m too much. Too many feelings. Too many speeches.","What if Lily gets tired of it?"],"choices":[{"id":"a","label":"Too much is how you love.","reaction":["...Oh. That''s nice. I might write that down.","Maybe I''ll tone it down to two pages."]},{"id":"b","label":"Does she say that?","reaction":["No. She says ''keep going.'' Which is worse and better.","She blushes when I do the big stuff. I think she loves it."]},{"id":"c","label":"Sit with him.","reaction":["Thank you. It''s nice not being alone with my feelings.","They''re loud ones. They can be shy around you."]}],"outro":null}'::jsonb),
('FN-08','adventure_friend_fn','Intro',8,1,'{"id":"FN-08","friendId":"adventure_friend_fn","phase":"Intro","seq":8,"familiarity":"Close Friend","type":"Statement","scene":null,"lines":["I asked Lily if she believes in signs.","She said ''I believe in you showing up.'' And then she kissed my forehead.","Is THAT a sign?! A sign about signs?!"],"choices":[{"id":"a","label":"Sign inception.","reaction":["Exactly. The sign of signs. I''m reeling.","I think she''s saying: actions count. Not just puddles."]},{"id":"b","label":"I think she''s right.","reaction":["Me too. I''m gonna show up more. And still do the puddles.","Both. I want both."]},{"id":"c","label":"Smile and nod.","reaction":["You get it. You really get it.","I''m adding you to the sign club newsletter."]}],"outro":null}'::jsonb),
('FN-09','adventure_friend_fn','Intro',9,1,'{"id":"FN-09","friendId":"adventure_friend_fn","phase":"Intro","seq":9,"familiarity":"Best Friend","type":"Companion","scene":"Fenn lays a leaf on the ground and sits down with a happy sigh.","lines":["I don''t have a speech today. I just want to sit with you.","No signs. No plans. Just us, and a puddle.","...Is that weird?"],"choices":[{"id":"a","label":"Not weird at all.","reaction":["Good. I''m learning that quiet also counts.","Lily says it''s my best quality. Don''t tell her I told you."]},{"id":"b","label":"Splash the puddle.","reaction":["Ahh! Splash war! You''re on my team!","This is a sign. I''m not even looking. It''s a SIGN."]},{"id":"c","label":"Watch the clouds together.","reaction":["That one looks like a heart. That one looks like a sandwich.","Both are signs. Both are good."]}],"outro":null}'::jsonb),
('FN-10','adventure_friend_fn','Intro',10,1,'{"id":"FN-10","friendId":"adventure_friend_fn","phase":"Intro","seq":10,"familiarity":"Old Friend","type":"Milestone","scene":null,"lines":["Ten times. I wrote it on a pebble. It''s in my pocket.","Lily asked what I''m doing with all these pebbles. I said ''building a love castle.''","She said, ''Count me in.'' Sign. Sign. SIGN.","Your turn. How are you and your partner doing? Honest."],"choices":[{"id":"a","label":"We''re good. Still learning.","reaction":["Still learning is the best sign.","Come visit. We''ll walk a puddle. Lily makes crowns."]},{"id":"b","label":"We had a rough week, honestly.","reaction":["Rough weeks happen. Even in love castles.","Bring your partner to the next puddle. We''ll start fresh."]},{"id":"c","label":"Better since I paid attention to little things.","reaction":["YES. Little things are everything.","Okay, I''m crying. Hand me a lily pad."]}],"outro":null}'::jsonb),
('FN-P01','adventure_friend_fn','Pool',1,1,'{"id":"FN-P01","friendId":"adventure_friend_fn","phase":"Pool","seq":1,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["Lily and I tried to watch a sunset. It was cloudy.","I said it was a sign that we should make our own sun."],"choices":[{"id":"a","label":"Did you make a sun?","reaction":["We drew one. On a leaf. It''s very yellow.","It''s on our wall. It''s the best sunset we ever had."]},{"id":"b","label":"Cloudy sunsets still count.","reaction":["They do. The clouds blushed. It was lovely.","I took that as a sign. Obviously.","We stayed until the stars did the rest."]}],"outro":null}'::jsonb),
('FN-P02','adventure_friend_fn','Pool',2,1,'{"id":"FN-P02","friendId":"adventure_friend_fn","phase":"Pool","seq":2,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["I wrote Lily a poem. It rhymes ''love'' with ''dove,'' ''glove,'' and ''above.''","It also rhymes ''Lily'' with ''silly.'' Twice."],"choices":[{"id":"a","label":"Read it to me.","reaction":["Okay. Ahem. ''Lily, you are silly, willy-nilly...''","I stopped there. It gets worse.","Please never repeat that last line. Lily framed it anyway."]},{"id":"b","label":"What did she say?","reaction":["She said, ''Again, but softer.'' So I whispered it.","She cried. A happy cry. A poem cry.","She asked for a copy. I printed twelve, just in case."]}],"outro":null}'::jsonb),
('FN-P03','adventure_friend_fn','Pool',3,1,'{"id":"FN-P03","friendId":"adventure_friend_fn","phase":"Pool","seq":3,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["Lily gave me a pebble. Just a plain one.","I held it for an hour. Then I realized it was a sign. Of her."],"choices":[{"id":"a","label":"Cute.","reaction":["It''s not just a pebble. It''s HER pebble.","I''m sleeping with it. Don''t judge.","She grinned and said, ''See? Round and slightly confused.''"]},{"id":"b","label":"What''s special about it?","reaction":["Nothing. That''s the point. She picked it because it reminded her of me.","Round. Slightly confused. Perfect.","She keeps one for me too. We trade on Fridays."]}],"outro":null}'::jsonb),
('FN-P04','adventure_friend_fn','Pool',4,1,'{"id":"FN-P04","friendId":"adventure_friend_fn","phase":"Pool","seq":4,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["We had a fight about whose turn it was to pick the lily pad.","I said ''it''s a sign we need a bigger pad.'' We both laughed."],"choices":[{"id":"a","label":"Problem solved.","reaction":["A bigger pad. Obviously.","Now there''s room for two. And a snack. And an argument. All good.","I measured the pad twice. Lily just stood on it."]},{"id":"b","label":"Fights can be funny.","reaction":["Sometimes. The key is to look for the funny.","If the pad sinks, we laugh. Same energy.","The new pad is lopsided. We call it ''ours.''"]}],"outro":null}'::jsonb),
('FN-P05','adventure_friend_fn','Pool',5,1,'{"id":"FN-P05","friendId":"adventure_friend_fn","phase":"Pool","seq":5,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["I tried to sing Lily a serenade. A frog sings by default. It was… loud.","The neighbors clapped. Politely. Through their windows."],"choices":[{"id":"a","label":"A loud serenade is a good serenade.","reaction":["Thank you! Volume is love. That''s my motto.","Lily said she heard it from three tunnels away. She was smiling."]},{"id":"b","label":"Did she join in?","reaction":["She did. We were awful. It was perfect.","The neighbors are now asking for an encore.","We were awful, but the lilies seemed to sway along."]}],"outro":null}'::jsonb),
('FN-P06','adventure_friend_fn','Pool',6,1,'{"id":"FN-P06","friendId":"adventure_friend_fn","phase":"Pool","seq":6,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["I forgot to bring flowers on our date. So I handed her a leaf.","She said ''it''s perfect.'' I think she meant it. Her eyes were doing the thing."],"choices":[{"id":"a","label":"Leaves are romantic.","reaction":["They''re green. They''re free. They''re honest.","She pressed it in a book. I''m so happy I''m dizzy.","Next time I''ll bring a leaf and a tiny speech."]},{"id":"b","label":"What thing?","reaction":["The shiny thing. The ''I love you'' shine.","Can''t explain it. Just look for it in your partner."]}],"outro":null}'::jsonb),
('FN-P07','adventure_friend_fn','Pool',7,1,'{"id":"FN-P07","friendId":"adventure_friend_fn","phase":"Pool","seq":7,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["Lily and I decided to try silence for an hour. Together. No talking.","We lasted twelve minutes. Then I whispered ''sign.'' She giggled."],"choices":[{"id":"a","label":"Twelve minutes is great.","reaction":["It''s a record. We''re framing the hour glass.","Silence with Lily feels like warm water.","We''re aiming for twenty minutes next time. Wish us luck."]},{"id":"b","label":"What was the sign?","reaction":["A beetle crossing our path. It looked like it was in love.","Don''t ask how I know. It had a tiny tie."]}],"outro":null}'::jsonb),
('FN-P08','adventure_friend_fn','Pool',8,1,'{"id":"FN-P08","friendId":"adventure_friend_fn","phase":"Pool","seq":8,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["Lily said ''I love you'' first today. For the first time.","I fell off my lily pad. I''m still wet. I''m still smiling."],"choices":[{"id":"a","label":"Congrats! That''s huge.","reaction":["It IS huge! The biggest sign of all!","I said it back four times. In a row. Just to be safe."]},{"id":"b","label":"Are you okay?","reaction":["I''m fantastic. I''m a puddle of happiness.","I''ll dry out in a week. Maybe.","I''ll dry in a week. Lily says I''m adorable damp."]}],"outro":null}'::jsonb),
('FN-P09','adventure_friend_fn','Pool',9,1,'{"id":"FN-P09","friendId":"adventure_friend_fn","phase":"Pool","seq":9,"familiarity":"Old Friend","type":"Callback","scene":null,"lines":["Remember the heart puddle? It dried up.","I almost cried. Lily said ''we''ll find another.'' She found it. Behind the third rock."],"choices":[{"id":"a","label":"Another heart puddle!","reaction":["It''s lopsided. It''s perfect. It''s ours.","We named it Puddle Two. Original, I know.","We visit it on Sundays. Lily brings snacks."]},{"id":"b","label":"Lily''s the best.","reaction":["She is. She really is. I tell her every day.","Some days twice. Some days in pebbles.","Every morning I thank the universe. Sometimes the puddle too."]}],"outro":null}'::jsonb),
('FN-P10','adventure_friend_fn','Pool',10,1,'{"id":"FN-P10","friendId":"adventure_friend_fn","phase":"Pool","seq":10,"familiarity":"Old Friend","type":"Callback","scene":null,"lines":["The pebble love castle is up to eighty-four stones.","Lily added a tiny door. I added a tiny welcome mat."],"choices":[{"id":"a","label":"Can I visit?","reaction":["Of course! Bring your partner. The door is too small, but come anyway.","We''ll squeeze. Love squeezes.","Bring pebbles. We need a roof, and roofs are hard."]},{"id":"b","label":"That''s adorable.","reaction":["It''s our project. Our forever project.","A castle is never finished. That''s the point.","It''s at eighty-four stones. Lily says ninety is the dream."]}],"outro":null}'::jsonb),
('FN-P11','adventure_friend_fn','Pool',11,1,'{"id":"FN-P11","friendId":"adventure_friend_fn","phase":"Pool","seq":11,"familiarity":"Old Friend","type":"Callback","scene":null,"lines":["You remember my four-page speech? I cut it down to two lines.","''I love you. Walk with me?'' Lily said yes. Of course."],"choices":[{"id":"a","label":"Short and perfect.","reaction":["I thought the long one was better. I was wrong.","Short is brave. Short means you mean it."]},{"id":"b","label":"I miss the long one.","reaction":["I''ll read it to you someday. With a cape.","The cape is non-negotiable.","I''ll read it on our fiftieth puddle-versary."]}],"outro":null}'::jsonb),
('FN-P12','adventure_friend_fn','Pool',12,1,'{"id":"FN-P12","friendId":"adventure_friend_fn","phase":"Pool","seq":12,"familiarity":"Old Friend","type":"Callback","scene":null,"lines":["The clover crown is on its third version. Lily still wears it.","She says it''s lucky. I say it''s love. Same thing."],"choices":[{"id":"a","label":"Lucky and loved.","reaction":["Both. Always both.","I might make a matching one for you. For luck.","I''d make you one too. Daisy for luck, clover for love."]},{"id":"b","label":"Nine hours well spent.","reaction":["Eleven now. I added a daisy. It took forever.","Lily cried. A good cry. Again.","She dried the old one. It''s on our wall now."]}],"outro":null}'::jsonb),
('FN-P13','adventure_friend_fn','Pool',13,1,'{"id":"FN-P13","friendId":"adventure_friend_fn","phase":"Pool","seq":13,"familiarity":"Old Friend","type":"HotTake","scene":null,"lines":["Hot take: signs are made up, but they''re fun.","Love is choosing the sign. Every day. On purpose."],"choices":[{"id":"a","label":"That''s wise.","reaction":["I stole it from Lily. She says it better.","But I say it with more pebbles.","Lily''s version has fewer pebbles and more wisdom."]},{"id":"b","label":"Signs are real.","reaction":["They are to me! A hug from the universe!","Don''t tell Lily I said ''made up.''","I swear the universe winks sometimes. Don''t tell Lily."]}],"outro":null}'::jsonb),
('FN-P14','adventure_friend_fn','Pool',14,1,'{"id":"FN-P14","friendId":"adventure_friend_fn","phase":"Pool","seq":14,"familiarity":"Old Friend","type":"HotTake","scene":null,"lines":["Hot take: it''s okay to be a little extra.","If someone loves you, they love the extra. Maybe even the extra extra."],"choices":[{"id":"a","label":"Extra is lovely.","reaction":["Thank you! I''m the extra extra.","Lily says I''m her favorite kind of loud.","Lily says extra is my brand. I''m putting it on a pebble."]},{"id":"b","label":"Sometimes extra is tiring.","reaction":["True. I know. I''m learning when to dial it down.","Lily taps my arm. Two taps. It means ''gentle, babe.''"]}],"outro":null}'::jsonb),
('FN-P15','adventure_friend_fn','Pool',15,1,'{"id":"FN-P15","friendId":"adventure_friend_fn","phase":"Pool","seq":15,"familiarity":"Old Friend","type":"HotTake","scene":null,"lines":["Hot take: say the mushy thing now. Not later.","Later has a way of never arriving. Ribbit."],"choices":[{"id":"a","label":"You''re right.","reaction":["I know! I''m basically a philosopher. A damp one.","Go say a mushy thing. I''ll wait.","Say it softly. Say it twice. Then eat something."]},{"id":"b","label":"What if it''s awkward?","reaction":["Awkward is just honesty in a funny hat.","Wear the hat. Say it.","Awkward is the fastest road to something real."]}],"outro":null}'::jsonb),
('FN-P16','adventure_friend_fn','Pool',16,1,'{"id":"FN-P16","friendId":"adventure_friend_fn","phase":"Pool","seq":16,"familiarity":"Old Friend","type":"AskBack","scene":null,"lines":["Do you and your partner have a first-date story?","I want every detail. Even the dumb ones."],"choices":[{"id":"a","label":"It was awkward but sweet.","reaction":["Awkward but sweet is the best genre.","I''m picturing it with violins. Frog violins.","I''d love to hear every detail. Bring snacks next time."]},{"id":"b","label":"We got lost on the way.","reaction":["Lost together is a great start.","You found each other. That''s the plot.","Lost together is basically a movie."]}],"outro":null}'::jsonb),
('FN-P17','adventure_friend_fn','Pool',17,1,'{"id":"FN-P17","friendId":"adventure_friend_fn","phase":"Pool","seq":17,"familiarity":"Old Friend","type":"AskBack","scene":null,"lines":["What''s a sign your partner loves you? Not a big one. A tiny one.","Fenn needs tiny signs."],"choices":[{"id":"a","label":"They remember my coffee order.","reaction":["Remembering the order is so romantic!","My heart hurts. In a good way.","Lily does that. I save every note she writes."]},{"id":"b","label":"They save me the last bite.","reaction":["The last bite! The ultimate sacrifice!","I''d cry. Then eat it. Then cry again.","I''d frame the last bite. I''m that dramatic."]}],"outro":null}'::jsonb),
('FN-P18','adventure_friend_fn','Pool',18,1,'{"id":"FN-P18","friendId":"adventure_friend_fn","phase":"Pool","seq":18,"familiarity":"Old Friend","type":"AskBack","scene":null,"lines":["If you could re-live one moment with your partner, which would it be?","I''d pick our first puddle. Obviously."],"choices":[{"id":"a","label":"Our first trip together.","reaction":["Ooh. A first trip. I love a first trip.","Every first is a little sign.","Firsts are the loudest memories. I''d relive mine hourly."]},{"id":"b","label":"A random Tuesday.","reaction":["A random Tuesday! That''s so real.","Ordinary days are the best days. I''m writing that on a pebble."]}],"outro":null}'::jsonb),
('FN-P19','adventure_friend_fn','Pool',19,0.25,'{"id":"FN-P19","friendId":"adventure_friend_fn","phase":"Pool","seq":19,"familiarity":"Old Friend","type":"Rare","scene":"Fenn is perfectly still, looking up at a faint beam of light through the ceiling.","lines":["Do you see that? The light is hitting the pond in a perfect line.","Lily and I stood right there on our first date.","No words. No speech. I just wanted you to see it."],"choices":[{"id":"a","label":"It''s beautiful.","reaction":["It is. Thank you for seeing it with me.","Some signs are quiet. This is one.","I''ll bring Lily here soon. She''ll love it."]},{"id":"b","label":"Take a moment with Fenn.","reaction":["...Thank you. This is the best kind of silence.","I''ll remember this one. Pebble and all.","We stood there a long time. It was enough."]}],"outro":null}'::jsonb),
('FN-P20','adventure_friend_fn','Pool',20,0.25,'{"id":"FN-P20","friendId":"adventure_friend_fn","phase":"Pool","seq":20,"familiarity":"Old Friend","type":"Rare","scene":"Fenn is holding a small box, trembling slightly.","lines":["Okay. Don''t laugh. I made Lily a ring. Out of grass and one shiny bead.","I want to ask her to be mine forever. Not a big deal. Just forever.","What if she says no?"],"choices":[{"id":"a","label":"She''ll say yes.","reaction":["You think? Okay. Okay, okay, okay.","If she says yes, I''ll name a puddle after you.","If she says yes, I''ll cry into the pond."]},{"id":"b","label":"You''re brave.","reaction":["Brave? I''m shaking like a leaf.","But I''m going. Wish me luck. And pebbles.","Wish me luck. And please hold the bead."]}],"outro":null}'::jsonb)
