('adventure_gift_399',coalesce((select value from public.app_config where key='app_major_update_content_revision'),'burrow-v1-placeholder'),'souvenir','adventure_gifts','Lilac Olive',null,false,array['adventure_v2_gift'],'{"renderer":"r2","key":"burrow/adventure-gifts/v1/399-bb043669f796972e.webp","url":"https://media.novameapp.com/burrow/adventure-gifts/v1/399-bb043669f796972e.webp","width":600,"height":600}'::jsonb,'{"giftCategory":"Seashells","giftCategoryCode":"C12","friendId":"adventure_friend_fn","sourceId":399}'::jsonb,false),
('adventure_gift_400',coalesce((select value from public.app_config where key='app_major_update_content_revision'),'burrow-v1-placeholder'),'souvenir','adventure_gifts','Patterned Cone',null,false,array['adventure_v2_gift'],'{"renderer":"r2","key":"burrow/adventure-gifts/v1/400-7c360317593f8942.webp","url":"https://media.novameapp.com/burrow/adventure-gifts/v1/400-7c360317593f8942.webp","width":600,"height":600}'::jsonb,'{"giftCategory":"Seashells","giftCategoryCode":"C12","friendId":"adventure_friend_fn","sourceId":400}'::jsonb,false)
insert into public.friend_definitions(stable_id,revision_id,name,subtitle,art,metadata,is_placeholder) values('adventure_friend_os',coalesce((select value from public.app_config where key='app_major_update_content_revision'),'burrow-v1-placeholder'),'Oswin','Okay, hear me out.','{"renderer":"bundled","key":"Owl"}'::jsonb,'{"adventureV2":true,"code":"OS","gender":"he","species":"Owl"}'::jsonb,false) on conflict(stable_id) do update set name=excluded.name,subtitle=excluded.subtitle,art=excluded.art,metadata=excluded.metadata,status='active',updated_at=now();
insert into public.adventure_dialogues_v2(id,friend_id,phase,seq,weight,content) values
('OS-01','adventure_friend_os','Intro',1,1,'{"id":"OS-01","friendId":"adventure_friend_os","phase":"Intro","seq":1,"familiarity":"Stranger","type":"Statement","scene":"Oswin blinks slowly at you from a low branch of roots.","lines":["You''re awake. Good. Nobody''s awake at this hour.","Okay, hear me out. Juno said ''fine'' at dinner. Just ''fine''.","I''ve replayed it thirty-one times."],"choices":[{"id":"a","label":"Did they say it nicely?","reaction":["...Honestly? Yes. Very nicely.","I think my brain is the problem."]},{"id":"b","label":"Maybe ask them?","reaction":["Ask? Out loud? Like a creature?","Hm. Okay. Tomorrow. Maybe."]},{"id":"c","label":"Sit down next to Oswin.","reaction":["Oh. You''re staying.","That helps more than you''d think."]}],"outro":null}'::jsonb),
('OS-02','adventure_friend_os','Intro',2,1,'{"id":"OS-02","friendId":"adventure_friend_os","phase":"Intro","seq":2,"familiarity":"Familiar Face","type":"Statement","scene":null,"lines":["You came back! It''s still dark. Perfect.","I asked Juno about the ''fine.'' She said, ''I was tired. And the soup was fine.''","The SOUP. I analyzed the soup for six hours."],"choices":[{"id":"a","label":"The soup was fine.","reaction":["Yes. It was. It was a fine soup.","I should apologize to the soup."]},{"id":"b","label":"Sounds like a relief.","reaction":["It is. A huge one. Also kind of embarrassing.","Juno laughed so hard she hiccuped."]},{"id":"c","label":"Laugh softly.","reaction":["Go ahead. I''d laugh too, if I weren''t so tired.","Soup is a mystery. Lesson learned."]}],"outro":null}'::jsonb),
('OS-03','adventure_friend_os','Intro',3,1,'{"id":"OS-03","friendId":"adventure_friend_os","phase":"Intro","seq":3,"familiarity":"Acquaintance","type":"Statement","scene":"Oswin is surrounded by small scribbled notes, looking guilty.","lines":["Okay, hear me out. I made a chart of Juno''s text replies.","Short reply on Monday. Long reply on Tuesday. Emoji on Wednesday.","I know it''s too much. It''s just... it''s data."],"choices":[{"id":"a","label":"What does the chart say?","reaction":["That Juno is a person with moods. Shocking.","Also that Wednesdays are the best. Emojis everywhere."]},{"id":"b","label":"Maybe retire the chart?","reaction":["Hm. Retire. Dignity. Maybe a gentle ending.","I''ll keep one page. For sentimental reasons."]},{"id":"c","label":"Pat his wing.","reaction":["Thank you. That helps more than the chart ever did.","I''m going to hug this feeling for a while."]}],"outro":null}'::jsonb),
('OS-04','adventure_friend_os','Intro',4,1,'{"id":"OS-04","friendId":"adventure_friend_os","phase":"Intro","seq":4,"familiarity":"Acquaintance","type":"Statement","scene":null,"lines":["Juno told me, ''You think too loud.'' Not mean. Just fond.","I''ve been thinking about it for three days.","Is thinking too loud a bad thing? Or is that just me?"],"choices":[{"id":"a","label":"It sounds fond to me.","reaction":["Fond. Yes. That''s what I''m choosing.","Fond and loud. Like a happy fire alarm."]},{"id":"b","label":"Maybe a little of both.","reaction":["Yeah. Both. I contain multitudes. Mostly worries.","I''ll try to think a little softer. For Juno."]},{"id":"c","label":"Smile and shrug.","reaction":["Smile and shrug. A wise approach.","I''m going to try that. Right now. ...It''s hard."]}],"outro":null}'::jsonb),
('OS-05','adventure_friend_os','Intro',5,1,'{"id":"OS-05","friendId":"adventure_friend_os","phase":"Intro","seq":5,"familiarity":"Friend","type":"Ask","scene":null,"lines":["Honest question. When your partner goes quiet, do you ask what''s wrong, or give them space?","I always do the wrong one."],"choices":[{"id":"a","label":"I ask, softly.","reaction":["Softly. Okay. Mine is more like an interrogation.","I''ll practice. ''Hey. You okay?'' See? Soft."]},{"id":"b","label":"I give space first.","reaction":["Space. Hm. That feels so hard when my brain is loud.","But maybe space is a way of saying ''I trust you.''"]},{"id":"c","label":"Honestly, I''m still figuring it out.","reaction":["Oh thank goodness. So is everyone.","I feel a hundred percent less alone."]}],"outro":null}'::jsonb),
('OS-06','adventure_friend_os','Intro',6,1,'{"id":"OS-06","friendId":"adventure_friend_os","phase":"Intro","seq":6,"familiarity":"Friend","type":"Statement","scene":"Oswin is humming a tune that doesn''t quite finish.","lines":["Juno and I stayed up all night talking. Not about anything. Just talking.","At four a.m., she said, ''I like how your brain works.''","I didn''t overthink it. For a full minute."],"choices":[{"id":"a","label":"A full minute!","reaction":["A WHOLE minute. A record. I''m going to cry.","Then I overthought the minute. But still."]},{"id":"b","label":"That''s so sweet.","reaction":["It is. She said it like it was obvious. Like water is wet.","I keep it in my feathers."]},{"id":"c","label":"Yawn in solidarity.","reaction":["Ha! Sleepy club. We''re the best club.","The owls and the owl-adjacent."]}],"outro":null}'::jsonb),
('OS-07','adventure_friend_os','Intro',7,1,'{"id":"OS-07","friendId":"adventure_friend_os","phase":"Intro","seq":7,"familiarity":"Close Friend","type":"Confide","scene":"Oswin lowers his voice, though no one is around.","lines":["Can I confess something? It''s a quiet one.","Sometimes I think Juno deserves someone calmer. Someone who doesn''t spiral at night.","And then I spiral about that. It''s a whole spiral."],"choices":[{"id":"a","label":"Juno chose you.","reaction":["...She did. On purpose. With full knowledge of the spirals.","That''s actually kind of beautiful."]},{"id":"b","label":"Have you told Juno?","reaction":["A little. She said, ''I like your spirals. They''re cozy.''","Cozy spirals. I can live with that."]},{"id":"c","label":"Stay quiet and listen.","reaction":["Thank you. I think I needed to say it out loud.","Out loud, it sounds smaller. Funny how that works."]}],"outro":null}'::jsonb),
('OS-08','adventure_friend_os','Intro',8,1,'{"id":"OS-08","friendId":"adventure_friend_os","phase":"Intro","seq":8,"familiarity":"Close Friend","type":"Statement","scene":null,"lines":["We made a rule. If I start spiraling, Juno says ''moth.''","It''s our safe word. Because I like moths. And because it''s funny.","She said it last night. I laughed so hard I stopped spiraling."],"choices":[{"id":"a","label":"Moth is perfect.","reaction":["It is! Moths are underrated. Soft, quiet, love the light.","Kind of like us."]},{"id":"b","label":"Does it always work?","reaction":["Not always. But it helps me remember to breathe.","Sometimes I say it to myself. Moth. Okay. Moth."]},{"id":"c","label":"Whisper ''moth.''","reaction":["Oh no. I''m calm. How dare you.","Do it again. ...Never mind. I''m good."]}],"outro":null}'::jsonb),
('OS-09','adventure_friend_os','Intro',9,1,'{"id":"OS-09","friendId":"adventure_friend_os","phase":"Intro","seq":9,"familiarity":"Best Friend","type":"Companion","scene":"Oswin spreads his wings slightly, making room for you to sit under them.","lines":["No topic tonight. I just want company.","Juno''s asleep. The tunnel is quiet. My brain is only at fifty percent.","Stay for a bit?"],"choices":[{"id":"a","label":"Of course.","reaction":["Thanks. Not everyone likes the dark.","I like that you do. Or at least pretend to."]},{"id":"b","label":"Look at the dark with Oswin.","reaction":["See? It''s not scary. It''s just... soft.","Juno says the dark is a blanket. I steal that."]},{"id":"c","label":"Hum quietly.","reaction":["Is that a lullaby? It''s nice.","Keep going. I won''t overthink it. ...Okay, a little."]}],"outro":null}'::jsonb),
('OS-10','adventure_friend_os','Intro',10,1,'{"id":"OS-10","friendId":"adventure_friend_os","phase":"Intro","seq":10,"familiarity":"Old Friend","type":"Milestone","scene":null,"lines":["Ten times. I counted. Then I recounted. Still ten.","Juno said, ''You''re making a friend. I''m proud of you.'' I didn''t overthink it. Much.","Okay, hear me out. I like you. Plainly.","Your turn. How are you and your partner doing? Honest."],"choices":[{"id":"a","label":"We''re good. Still learning.","reaction":["Still learning. Same. Always.","Come by sometime. Juno makes night tea. I make worries."]},{"id":"b","label":"We had a rough week, honestly.","reaction":["Rough weeks are loud for me. I''m sorry.","If it helps, say ''moth.'' It''s yours now."]},{"id":"c","label":"Better since I talked it out.","reaction":["Talking it out. Out loud. With a mouth.","Look at us. Growing like moss at midnight."]}],"outro":null}'::jsonb),
('OS-P01','adventure_friend_os','Pool',1,1,'{"id":"OS-P01","friendId":"adventure_friend_os","phase":"Pool","seq":1,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["Juno left me on ''read'' for ten minutes. I made a plan for the worst.","She was just cooking. Her phone was upside down."],"choices":[{"id":"a","label":"Ten minutes is nothing.","reaction":["I know. I KNOW. But my brain doesn''t.","Juno sent a heart and a soup photo. I calmed down."]},{"id":"b","label":"Phones are weird.","reaction":["They really are. Tiny anxiety boxes.","I put mine in a drawer. For eight whole minutes.","Juno gave me a gold star for surviving."]}],"outro":null}'::jsonb),
('OS-P02','adventure_friend_os','Pool',2,1,'{"id":"OS-P02","friendId":"adventure_friend_os","phase":"Pool","seq":2,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["We went on a midnight walk. Juno held my wing the whole time.","I forgot to count my worries. For half an hour."],"choices":[{"id":"a","label":"That sounds lovely.","reaction":["It was. The stars were doing a lot.","I''m keeping that walk forever.","Juno held my wing like it was no big deal. It was."]},{"id":"b","label":"Half an hour is good.","reaction":["It''s my personal best. Unofficially.","Juno gave me a medal. Made of acorn caps.","Juno pinned the medal to my feather. I cried a bit."]}],"outro":null}'::jsonb),
('OS-P03','adventure_friend_os','Pool',3,1,'{"id":"OS-P03","friendId":"adventure_friend_os","phase":"Pool","seq":3,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["I tried to plan a surprise for Juno. Three backup plans. Four backups for the backups.","It rained. Plan seventeen. We ate crackers under a leaf."],"choices":[{"id":"a","label":"Crackers under a leaf!","reaction":["Peak romance. Rain on the leaf. Juno laughing.","I forgot every plan. It was perfect.","Juno said it was the best date she''d ever had."]},{"id":"b","label":"Plans can be too much.","reaction":["Yes. Plans are fine. Leaves are better.","I''m trying to pack one plan, not twenty.","Juno now suggests one plan, one backup, one snack."]}],"outro":null}'::jsonb),
('OS-P04','adventure_friend_os','Pool',4,1,'{"id":"OS-P04","friendId":"adventure_friend_os","phase":"Pool","seq":4,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["Juno asked if I''m happy. I said ''yes'' but my face did something weird.","I explained. She laughed. Then she said, ''Me too.''"],"choices":[{"id":"a","label":"Happy faces are weird.","reaction":["Mine looks like a surprised pillow.","Juno says it''s the best face I have.","Juno takes a photo of it every time."]},{"id":"b","label":"That''s sweet.","reaction":["It is. Quiet, easy sweet.","I''ll replay it. But in a good way.","I whispered ''me too'' back. She fell asleep smiling."]}],"outro":null}'::jsonb),
('OS-P05','adventure_friend_os','Pool',5,1,'{"id":"OS-P05","friendId":"adventure_friend_os","phase":"Pool","seq":5,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["I accidentally said ''love you'' to a delivery moth.","I was tired. The moth was polite about it."],"choices":[{"id":"a","label":"Did Juno find out?","reaction":["Yes. She put it on a banner. ''Moth Lover.''","It''s hanging in our burrow now.","The moth wasn''t mad. Just very confused."]},{"id":"b","label":"Moths are loveable.","reaction":["They are! The moth wrote back. A small thank-you.","I think we''re friends now.","I leave a tiny lamp for it now, out of respect."]}],"outro":null}'::jsonb),
('OS-P06','adventure_friend_os','Pool',6,1,'{"id":"OS-P06","friendId":"adventure_friend_os","phase":"Pool","seq":6,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["We tried a ''no overthinking'' day. Rules: no analysis, no replays.","I lasted until lunch. Juno lasted until bedtime. She''s better at this."],"choices":[{"id":"a","label":"Lunch is a good start.","reaction":["Lunch is a strong start. Next time, lunch plus snacks.","I''ll be a professional non-thinker by winter.","Dinner next time. Then maybe the whole weekend."]},{"id":"b","label":"Juno''s amazing.","reaction":["She really is. She didn''t even gloat.","She gave me a cookie for effort.","She said I''m allowed to try again tomorrow."]}],"outro":null}'::jsonb),
('OS-P07','adventure_friend_os','Pool',7,1,'{"id":"OS-P07","friendId":"adventure_friend_os","phase":"Pool","seq":7,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["I bought Juno a book. Then spent three days wondering if it was the right book.","She loved it. She''s on chapter nine already."],"choices":[{"id":"a","label":"Right book, right time.","reaction":["I think so. Thank goodness.","She read me a paragraph. I forgot to worry.","She underlined a line for me. I''m saving it."]},{"id":"b","label":"You did great.","reaction":["Thank you. I''ll tell my brain you said that.","It might not believe you. But it''ll try.","Juno rolled her eyes. Fondly. I counted it."]}],"outro":null}'::jsonb),
('OS-P08','adventure_friend_os','Pool',8,1,'{"id":"OS-P08","friendId":"adventure_friend_os","phase":"Pool","seq":8,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["Juno asked me to stop saying sorry for everything.","I said, ''Sorry.'' Then we both burst out laughing."],"choices":[{"id":"a","label":"Classic.","reaction":["I''m a sorry machine. A very polite owl.","We made a jar. Every sorry costs a cookie.","Juno now says ''sorry'' back to mock me. Lovingly."]},{"id":"b","label":"Sorry for what?","reaction":["Everything. The weather. The moon.","I''m working on it.","We settled on one sorry a day. The rest is hugs."]}],"outro":null}'::jsonb),
('OS-P09','adventure_friend_os','Pool',9,1,'{"id":"OS-P09","friendId":"adventure_friend_os","phase":"Pool","seq":9,"familiarity":"Old Friend","type":"Callback","scene":null,"lines":["Remember the soup? Juno made it again.","I tasted it very calmly. And said, ''Fine.'' She gasped."],"choices":[{"id":"a","label":"Revenge of the soup.","reaction":["A joke! A joke at last! My first, I think.","She laughed so hard she hiccuped again.","She''s asked me to make it on Sundays. I accepted."]},{"id":"b","label":"Fine soup forever.","reaction":["The best ''fine'' of my life.","We named the recipe ''Fine Soup.'' It''s on the wall.","It''s our private joke now. Soup, but ironic."]}],"outro":null}'::jsonb),
('OS-P10','adventure_friend_os','Pool',10,1,'{"id":"OS-P10","friendId":"adventure_friend_os","phase":"Pool","seq":10,"familiarity":"Old Friend","type":"Callback","scene":null,"lines":["The chart? Juno found it. She framed it.","It''s in the hallway. ''Oswin''s Data Era.''"],"choices":[{"id":"a","label":"That''s adorable.","reaction":["She said it shows I care. Which is true.","I''m trying to be less scientific about love.","Under it she wrote: ''Oswin, still our favorite scientist.''"]},{"id":"b","label":"Hang it proudly.","reaction":["I will. Next to the soup photo.","A museum of my silliness.","Visitors stop to read it. I blush every time."]}],"outro":null}'::jsonb),
('OS-P11','adventure_friend_os','Pool',11,1,'{"id":"OS-P11","friendId":"adventure_friend_os","phase":"Pool","seq":11,"familiarity":"Old Friend","type":"Callback","scene":null,"lines":["I said ''moth'' to myself during a spiral. It worked.","I laughed alone in the dark like a lunatic."],"choices":[{"id":"a","label":"Moth magic.","reaction":["It''s the best word in the world.","Juno is thrilled. She taught me well.","I whispered it so many times. It''s my lucky word."]},{"id":"b","label":"Laughing alone is okay.","reaction":["It is. At night, especially.","The dark doesn''t judge.","Juno heard me. She laughed, then whispered it back."]}],"outro":null}'::jsonb),
('OS-P12','adventure_friend_os','Pool',12,1,'{"id":"OS-P12","friendId":"adventure_friend_os","phase":"Pool","seq":12,"familiarity":"Old Friend","type":"Callback","scene":null,"lines":["Remember my four a.m. talks with Juno? We did another.","This time I was the one who said, ''I like how your brain works.''"],"choices":[{"id":"a","label":"Full circle.","reaction":["Yes. A circle with a moth in the middle.","Juno went silent. Then said ''Thank you.'' Perfect.","We stared at the ceiling after. It felt right."]},{"id":"b","label":"That''s lovely.","reaction":["I think so too. Small, quiet, honest.","I held that sentence the whole next day.","It didn''t need decorating. Just quiet and honesty."]}],"outro":null}'::jsonb),
('OS-P13','adventure_friend_os','Pool',13,1,'{"id":"OS-P13","friendId":"adventure_friend_os","phase":"Pool","seq":13,"familiarity":"Old Friend","type":"HotTake","scene":null,"lines":["Hot take: you can''t think your way out of a feeling.","You can only sit with it. Like a stubborn cat."],"choices":[{"id":"a","label":"That''s wise.","reaction":["It took me years. And a very patient Juno.","Cats help. Cats are good.","Juno says feelings are weather. I carry an umbrella now."]},{"id":"b","label":"I overthink too.","reaction":["Welcome. Pull up a root.","We''ll overthink together. In harmony.","We sat for an hour. The feeling eventually wandered off."]}],"outro":null}'::jsonb),
('OS-P14','adventure_friend_os','Pool',14,1,'{"id":"OS-P14","friendId":"adventure_friend_os","phase":"Pool","seq":14,"familiarity":"Old Friend","type":"HotTake","scene":null,"lines":["Hot take: ''we need to talk'' is the scariest phrase.","Say ''I want to share something'' instead. Much softer."],"choices":[{"id":"a","label":"Totally agree.","reaction":["Right? It''s like a drum roll for doom.","Try ''got a minute for a feeling?'' Cute and clear."]},{"id":"b","label":"What if it''s serious?","reaction":["Then it''s still better soft.","Serious doesn''t mean harsh.","Gentle doesn''t mean unimportant. It means safe to hear."]}],"outro":null}'::jsonb),
('OS-P15','adventure_friend_os','Pool',15,1,'{"id":"OS-P15","friendId":"adventure_friend_os","phase":"Pool","seq":15,"familiarity":"Old Friend","type":"HotTake","scene":null,"lines":["Hot take: love at 3 a.m. is the realest love.","No one''s performing. No filters. Just two tired creatures."],"choices":[{"id":"a","label":"3 a.m. is magic.","reaction":["It really is. Honest hour.","Something about the dark makes people brave.","Even the moths are quiet then. It''s lovely."]},{"id":"b","label":"I prefer mornings.","reaction":["Mornings are fine. Mornings are cheerful.","But I''ll take your honesty at any hour.","Morning me is a different bird. Equally anxious, with coffee."]}],"outro":null}'::jsonb),
('OS-P16','adventure_friend_os','Pool',16,1,'{"id":"OS-P16","friendId":"adventure_friend_os","phase":"Pool","seq":16,"familiarity":"Old Friend","type":"AskBack","scene":null,"lines":["What do you and your partner do when you can''t sleep?","I''m collecting ideas. Juno snores."],"choices":[{"id":"a","label":"We talk in the dark.","reaction":["Dark talks are the best. I''m so jealous.","Do you whisper? I whisper.","Whispers feel like secrets. I''d trade a month of sleep for them."]},{"id":"b","label":"We cuddle.","reaction":["Cuddling. Yes. Excellent plan.","My wings are good for that. Warm, slightly dusty.","Wings are warm, if dusty. Juno never complains."]}],"outro":null}'::jsonb),
('OS-P17','adventure_friend_os','Pool',17,1,'{"id":"OS-P17","friendId":"adventure_friend_os","phase":"Pool","seq":17,"familiarity":"Old Friend","type":"AskBack","scene":null,"lines":["How do you tell your partner you need a minute? Without making it a thing?","I always make it a thing."],"choices":[{"id":"a","label":"I just say it plainly.","reaction":["Plainly. Wow. Radical.","I''ll try: ''Hey, I need a minute.'' Hm. Doable.","I''ll try it at dinner, probably with a nervous cough."]},{"id":"b","label":"We have a signal.","reaction":["A signal! Like a lamp? A hum?","Oh, I love that. Moth. Always moth.","A little lamp on the shelf means ''not now, but I love you.''"]}],"outro":null}'::jsonb),
('OS-P18','adventure_friend_os','Pool',18,1,'{"id":"OS-P18","friendId":"adventure_friend_os","phase":"Pool","seq":18,"familiarity":"Old Friend","type":"AskBack","scene":null,"lines":["What''s the smallest thing your partner did that made you feel safe?","The tiny stuff matters most to me."],"choices":[{"id":"a","label":"They left a light on.","reaction":["Leaving a light on. Oh. That''s the best.","Juno does that. I almost cry every time.","Juno leaves a moth-shaped lamp on. I tear up every time."]},{"id":"b","label":"They said ''I''m here.''","reaction":["''I''m here.'' Simple. Strong.","It''s the best sentence in the world.","It''s the sentence I replay when my brain gets loud."]}],"outro":null}'::jsonb),
('OS-P19','adventure_friend_os','Pool',19,0.25,'{"id":"OS-P19","friendId":"adventure_friend_os","phase":"Pool","seq":19,"familiarity":"Old Friend","type":"Rare","scene":"Oswin is perched very high, wings spread wide. For once, the room is bright.","lines":["Okay. I want you to see something.","I''ve stopped making charts. Completely. I threw the last one away.","I feel lighter. I think Juno would be proud."],"choices":[{"id":"a","label":"I''m proud too.","reaction":["Thank you. That means more than a chart.","I''m going to carry that around. Quietly.","I''ll tell Juno tonight. She''ll cry, then make cocoa."]},{"id":"b","label":"Take a deep breath with Oswin.","reaction":["In. Out. Moth.","Okay. We did it. It''s quiet in here.","I even slept. Eleven minutes. A real nap."]}],"outro":null}'::jsonb),
('OS-P20','adventure_friend_os','Pool',20,0.25,'{"id":"OS-P20","friendId":"adventure_friend_os","phase":"Pool","seq":20,"familiarity":"Old Friend","type":"Rare","scene":"Oswin is holding a tiny letter and looks both scared and happy.","lines":["Juno wrote me a letter. I haven''t opened it. For three days.","I''m scared that if I read it, it''ll be over. The feeling.","Or it''ll be better than I imagined. And that''s scary too."],"choices":[{"id":"a","label":"Open it together.","reaction":["Okay. Together. Slowly. ...''Dear Oswin, you overthink, and I adore it.''","...That''s all it says. That''s everything.","It''s folded in four, like a tiny map home."]},{"id":"b","label":"Wait until you''re ready.","reaction":["Ready. I''m never ready. But maybe tonight.","Thank you for waiting with me.","I''ll read it when the moon is out. For luck."]}],"outro":null}'::jsonb)
