insert into public.friend_definitions(stable_id,revision_id,name,subtitle,art,metadata,is_placeholder) values('adventure_friend_br',coalesce((select value from public.app_config where key='app_major_update_content_revision'),'burrow-v1-placeholder'),'Bruno','Big feelings. Big hugs.','{"renderer":"bundled","key":"Bear"}'::jsonb,'{"adventureV2":true,"code":"BR","gender":"he","species":"Bear"}'::jsonb,false) on conflict(stable_id) do update set name=excluded.name,subtitle=excluded.subtitle,art=excluded.art,metadata=excluded.metadata,status='active',updated_at=now();
insert into public.adventure_dialogues_v2(id,friend_id,phase,seq,weight,content) values
('BR-01','adventure_friend_br','Intro',1,1,'{"id":"BR-01","friendId":"adventure_friend_br","phase":"Intro","seq":1,"familiarity":"Stranger","type":"Statement","scene":"Bruno is carrying a tiny blanket and trying not to cry.","lines":["Hi! Hello! Sorry. I''m fine. I''m just holding a blanket.","Clover and I are having cubs. In spring.","We''re so happy. We''re also terrified. Both. At the same time."],"choices":[{"id":"a","label":"Congrats! That''s huge.","reaction":["It IS huge! Say it again.","Okay, that helped. Big feelings."]},{"id":"b","label":"Are you ready?","reaction":["Not even a little.","But Clover says nobody is. So... maybe that''s the point?"]},{"id":"c","label":"Offer a hug.","reaction":["Oh no. I''m crying.","Big hugs. Always."]}],"outro":null}'::jsonb),
('BR-02','adventure_friend_br','Intro',2,1,'{"id":"BR-02","friendId":"adventure_friend_br","phase":"Intro","seq":2,"familiarity":"Familiar Face","type":"Statement","scene":null,"lines":["You''re back! I''m better today. Slightly less blanket.","Clover and I started a name list. It has forty names.","Thirty-nine are about honey. I think I have a theme."],"choices":[{"id":"a","label":"What''s the fortieth name?","reaction":["Clover. As a middle name. For the cub.","I teared up writing it. Then I added another honey."]},{"id":"b","label":"Honey names are cute.","reaction":["Right?! Honeybee. Honeycomb. Honey Bunches.","Clover says no to the last one. Fair."]},{"id":"c","label":"Nod and smile.","reaction":["Thank you for the calm energy. I needed a calm one.","I''m vibrating at a very high frequency."]}],"outro":null}'::jsonb),
('BR-03','adventure_friend_br','Intro',3,1,'{"id":"BR-03","friendId":"adventure_friend_br","phase":"Intro","seq":3,"familiarity":"Acquaintance","type":"Statement","scene":"Bruno is surrounded by a pile of tiny socks, hats, and one enormous paw-print.","lines":["I bought way too many baby things. I got excited at the market.","I now own eleven tiny hats. For three cubs. Possibly.","Clover said, ''We have a lot of hats.'' Gently. With love."],"choices":[{"id":"a","label":"Eleven hats is a lot.","reaction":["It''s a LOT. I know. I''m a hat guy now.","We''re donating five. Maybe four. I''m attached."]},{"id":"b","label":"Do cubs need that many?","reaction":["No. But I need them. For emotional support.","Don''t tell Clover. She knows."]},{"id":"c","label":"Try on a tiny hat.","reaction":["It fits your ear! Perfect!","I''m calling it. Best photo of the year."]}],"outro":null}'::jsonb),
('BR-04','adventure_friend_br','Intro',4,1,'{"id":"BR-04","friendId":"adventure_friend_br","phase":"Intro","seq":4,"familiarity":"Acquaintance","type":"Statement","scene":null,"lines":["Clover gets tired a lot lately. She naps in the afternoon.","I cook now. Badly. But with feeling.","Last night I made soup. She said, ''Is that... a mushroom?'' It was a sock."],"choices":[{"id":"a","label":"A sock?!","reaction":["A tiny one. I dropped it in. Accident.","We ate it anyway. The broth was great."]},{"id":"b","label":"You''re doing great.","reaction":["Thank you. I cling to that.","Clover says my soup is love in a bowl. Slightly crunchy."]},{"id":"c","label":"Offer to help stir.","reaction":["Yes! Please! A second spoon is a miracle.","You''re hired. Payment in soup."]}],"outro":null}'::jsonb),
('BR-05','adventure_friend_br','Intro',5,1,'{"id":"BR-05","friendId":"adventure_friend_br","phase":"Intro","seq":5,"familiarity":"Friend","type":"Ask","scene":null,"lines":["Quick question. How do you and your partner share the big decisions?","Like names, rooms, schedules, snacks. Everything feels huge right now."],"choices":[{"id":"a","label":"We talk it out.","reaction":["Talk it out. Yes. Always.","I make lists. Clover makes tea. Together it works."]},{"id":"b","label":"One of us decides.","reaction":["Hm. Interesting. Clover and I take turns.","She picked the nursery color. I picked the lamp."]},{"id":"c","label":"We flip a coin.","reaction":["A coin! Bold. Honestly, I''m tempted.","Heads for honey. Tails for blueberry."]}],"outro":null}'::jsonb),
('BR-06','adventure_friend_br','Intro',6,1,'{"id":"BR-06","friendId":"adventure_friend_br","phase":"Intro","seq":6,"familiarity":"Friend","type":"Statement","scene":"Bruno is holding a small wooden crib piece and a very confusing diagram.","lines":["I''m building the cradle. The instructions have forty pictures and zero words.","I''ve been at it for three hours. It''s now a very strange chair.","Clover is laughing. In the nicest way."],"choices":[{"id":"a","label":"A strange chair is still a chair.","reaction":["Exactly! Cradles are just chairs that dream.","Clover sat in it. It didn''t collapse. Win."]},{"id":"b","label":"Need a second pair of paws?","reaction":["Yes. Please. Hold this. No, THAT. Okay, good.","See? Teamwork. I''m already a better dad."]},{"id":"c","label":"Cheer him on.","reaction":["Thank you. I''m drawing strength from your cheer.","It''s a lot. But I''m proud of the chair."]}],"outro":null}'::jsonb),
('BR-07','adventure_friend_br','Intro',7,1,'{"id":"BR-07","friendId":"adventure_friend_br","phase":"Intro","seq":7,"familiarity":"Close Friend","type":"Confide","scene":"Bruno sits down heavily, the blanket drooping in his paws.","lines":["Can I tell you something? It''s a big one.","I''m scared I won''t be a good dad. My dad wasn''t around much.","What if I''m like that? What if I forget how to hug?"],"choices":[{"id":"a","label":"You already hug a lot.","reaction":["...I do, don''t I?","Maybe the fear is proof I care. That''s what Clover says."]},{"id":"b","label":"Have you told Clover?","reaction":["I did. She said, ''We''ll learn together.''","Then she put my paw on her belly. I felt a kick."]},{"id":"c","label":"Sit beside Bruno.","reaction":["Thank you. It''s easier with someone next to me.","Big feelings are heavy. They''re lighter with company."]}],"outro":null}'::jsonb),
('BR-08','adventure_friend_br','Intro',8,1,'{"id":"BR-08","friendId":"adventure_friend_br","phase":"Intro","seq":8,"familiarity":"Close Friend","type":"Statement","scene":null,"lines":["I felt the cub kick. Actually felt it. A tiny thump.","I said, ''Hello!'' very loudly. Clover said, ''They can hear you from inside.''","I whispered after that. Mostly."],"choices":[{"id":"a","label":"That''s magical.","reaction":["It IS. I''m still floating.","I wrote ''thump'' on the wall. In honey."]},{"id":"b","label":"Say hi again.","reaction":["Hi, little one. It''s Dad. I have hats.","Clover laughed. The cub kicked back. Hat approval."]},{"id":"c","label":"Smile at him.","reaction":["Thanks. I''m all tears and honey.","I might need to sit. Again."]}],"outro":null}'::jsonb),
('BR-09','adventure_friend_br','Intro',9,1,'{"id":"BR-09","friendId":"adventure_friend_br","phase":"Intro","seq":9,"familiarity":"Best Friend","type":"Companion","scene":"Bruno pats the ground next to him. A blanket is spread out, with two tiny paw-print slippers.","lines":["Clover''s napping. I''m practicing lullabies. Want to hear?","I only know one song. It''s about honey.","It''s very, very bad."],"choices":[{"id":"a","label":"Sing it.","reaction":["Okay. ''Honey, honey, in the tree...'' It gets worse.","Thank you for listening. It''s my first audience."]},{"id":"b","label":"Hum along.","reaction":["Oh! You found a tune! It''s better than mine.","Together we''re sort of a choir. A slightly sleepy one."]},{"id":"c","label":"Just sit with him.","reaction":["Okay. Just sitting. It''s my favorite song.","Big hugs. Quiet ones."]}],"outro":null}'::jsonb),
('BR-10','adventure_friend_br','Intro',10,1,'{"id":"BR-10","friendId":"adventure_friend_br","phase":"Intro","seq":10,"familiarity":"Old Friend","type":"Milestone","scene":null,"lines":["Ten visits. I put a honey dot on the wall for each one.","Clover said, ''Bruno''s made a friend.'' I cried into a hat.","Big feelings. Big hugs. Thank you.","Your turn. How are you and your partner doing? Honest."],"choices":[{"id":"a","label":"We''re good. Still learning.","reaction":["Still learning. Yes. Forever.","Come see the nursery. It''s a strange chair, but ours."]},{"id":"b","label":"We had a rough week, honestly.","reaction":["Rough weeks are real. Clover and I have them.","Big hug. Bring your partner to tea."]},{"id":"c","label":"Better since I started saying things sooner.","reaction":["Sooner. Gentler. Yes!","Okay, I need a hat. For the tears."]}],"outro":null}'::jsonb),
('BR-P01','adventure_friend_br','Pool',1,1,'{"id":"BR-P01","friendId":"adventure_friend_br","phase":"Pool","seq":1,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["Clover wants pickles and honey on the same cracker.","I tried one. It was... confusing. Then delicious."],"choices":[{"id":"a","label":"Cravings are wild.","reaction":["She says the cub picked it. I believe her.","We now own four jars. Maybe five.","Clover tried one too. She made a face, then took another."]},{"id":"b","label":"Brave of you to try.","reaction":["Love is eating the weird cracker.","She smiled so big I''d eat ten.","She says I''m the bravest bear. I disagree, lovingly."]}],"outro":null}'::jsonb),
('BR-P02','adventure_friend_br','Pool',2,1,'{"id":"BR-P02","friendId":"adventure_friend_br","phase":"Pool","seq":2,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["We practiced bath time with a stuffed hedgehog. I dropped it. In the water.","Clover laughed until she snorted. I laughed too."],"choices":[{"id":"a","label":"Hedgehog rescue!","reaction":["He''s fine. He''s drying by the fire.","Practice makes perfect. Eventually.","We named him Sir Splash. He''s retired now."]},{"id":"b","label":"Cute.","reaction":["We''re both a mess. A cute mess.","I think we''ll be okay.","We hugged in the puddle. The towels were not enough."]}],"outro":null}'::jsonb),
('BR-P03','adventure_friend_br','Pool',3,1,'{"id":"BR-P03","friendId":"adventure_friend_br","phase":"Pool","seq":3,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["Clover told me she''s scared too. She just never says it.","I held her paw all night. Neither of us slept."],"choices":[{"id":"a","label":"That''s so tender.","reaction":["It really was. I felt closer than ever.","We cried a bit. Then ate cake.","I cried happy tears into her fur. She patted me."]},{"id":"b","label":"Fear is shared.","reaction":["Yes. Shared fear is smaller fear.","Plus, cake.","Cake didn''t fix everything, but it made the night softer."]}],"outro":null}'::jsonb),
('BR-P04','adventure_friend_br','Pool',4,1,'{"id":"BR-P04","friendId":"adventure_friend_br","phase":"Pool","seq":4,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["We argued about the nursery color. She wanted green. I wanted yellow.","Compromise: a green wall with a yellow moon."],"choices":[{"id":"a","label":"Green and yellow sounds lovely.","reaction":["It does! We painted it together. Messy.","Clover has paint on her nose. I have paint everywhere.","She has green on her nose. I have yellow on my ear."]},{"id":"b","label":"Good compromise.","reaction":["Yes! She calls it ''teamwork.'' I call it ''surrender.''","We''re both right.","Both colors work. Together they look like spring."]}],"outro":null}'::jsonb),
('BR-P05','adventure_friend_br','Pool',5,1,'{"id":"BR-P05","friendId":"adventure_friend_br","phase":"Pool","seq":5,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["I read a book about baby sleep. It said ''everything is a phase.''","Clover said, ''So is this book.'' I laughed very loud."],"choices":[{"id":"a","label":"Phases pass.","reaction":["I like that. Phases pass. Hugs stay.","I''m going to put that on a hat.","She hung a note on the wall: ''This is a phase.''"]},{"id":"b","label":"Clover''s funny.","reaction":["She''s the funniest. She doesn''t even try.","It''s my favorite thing about her.","I wrote that down. I''m making a quote wall."]}],"outro":null}'::jsonb),
('BR-P06','adventure_friend_br','Pool',6,1,'{"id":"BR-P06","friendId":"adventure_friend_br","phase":"Pool","seq":6,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["Clover felt me tearing up during a lullaby. She said, ''It''s okay to cry.''","I cried. A lot. We went through four hats."],"choices":[{"id":"a","label":"Crying is okay.","reaction":["I know that now. Big feelings, big tears.","Hats are very absorbent.","Clover tucked a handkerchief in my paw. She''s prepared."]},{"id":"b","label":"Tears are good.","reaction":["Honest ones, yes. Messy ones, always.","Clover says I''m a softie. I say I''m a bear.","We keep a spare hat for crying emergencies."]}],"outro":null}'::jsonb),
('BR-P07','adventure_friend_br','Pool',7,1,'{"id":"BR-P07","friendId":"adventure_friend_br","phase":"Pool","seq":7,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["I made a small chair for the cub. It''s the size of a loaf.","Clover said, ''It''s perfect.'' I think it''s crooked."],"choices":[{"id":"a","label":"Crooked is charming.","reaction":["Crooked is the cub''s first lesson in love.","Imperfect, sturdy, ours.","Clover tucked a tiny pillow in it. It looks perfect."]},{"id":"b","label":"It sounds perfect.","reaction":["Thank you. I''ll sand it. A little. Then stop.","If I keep sanding, it''ll be sawdust.","I stopped sanding when she hugged me. Priorities."]}],"outro":null}'::jsonb),
('BR-P08','adventure_friend_br','Pool',8,1,'{"id":"BR-P08","friendId":"adventure_friend_br","phase":"Pool","seq":8,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["Clover and I had our first quiet date in weeks.","We talked about everything except the cub. For one hour."],"choices":[{"id":"a","label":"Sounds lovely.","reaction":["It was. We remembered we''re also us.","Not just parents. Us. Two bears.","We ate crackers and talked about our first date."]},{"id":"b","label":"Date nights matter.","reaction":["They do. We''re keeping them. Even small ones.","Even if it''s soup on the floor.","I wrote ''Clover Tuesdays'' on the calendar. In honey."]}],"outro":null}'::jsonb),
('BR-P09','adventure_friend_br','Pool',9,1,'{"id":"BR-P09","friendId":"adventure_friend_br","phase":"Pool","seq":9,"familiarity":"Old Friend","type":"Callback","scene":null,"lines":["The sock soup? Clover asked for it again.","I said, ''On purpose?'' She said, ''Yes.'' I almost fainted."],"choices":[{"id":"a","label":"Sock soup lives on.","reaction":["It''s now a family recipe. Extra crunchy.","I''m really proud and a little confused.","She makes me stir. I add the sock. It''s a ritual."]},{"id":"b","label":"That''s so sweet.","reaction":["She said it reminds her of the day we found out.","I sobbed. Into the soup. Salty.","She squeezed my paw. We sat in the salty steam."]}],"outro":null}'::jsonb),
('BR-P10','adventure_friend_br','Pool',10,1,'{"id":"BR-P10","friendId":"adventure_friend_br","phase":"Pool","seq":10,"familiarity":"Old Friend","type":"Callback","scene":null,"lines":["Eleven hats! I gave five away. Clover cried at the pile.","We kept the little yellow one. It''s the cub''s first."],"choices":[{"id":"a","label":"The yellow one is perfect.","reaction":["It really is. It''s soft and slightly crooked.","Just like us.","Clover embroidered a tiny honey drop on it."]},{"id":"b","label":"Giving was kind.","reaction":["It felt good. Other cubs, other paws.","Big hugs to all of them.","Clover wrote a card for every hat. I read them all."]}],"outro":null}'::jsonb),
('BR-P11','adventure_friend_br','Pool',11,1,'{"id":"BR-P11","friendId":"adventure_friend_br","phase":"Pool","seq":11,"familiarity":"Old Friend","type":"Callback","scene":null,"lines":["My awful honey lullaby? Clover hums it in her sleep.","I didn''t know. I woke up and heard it. It''s so bad. It''s perfect."],"choices":[{"id":"a","label":"Aww.","reaction":["I know. I''m a puddle again.","Keep this between us. And the honey.","I''ll sing it every night, even if the cub groans."]},{"id":"b","label":"It''s a classic now.","reaction":["The Honey Song. Top of the charts, tunnels.","I''ll teach it to the cub. In a whisper.","Clover hums the second verse. It has no second verse."]}],"outro":null}'::jsonb),
('BR-P12','adventure_friend_br','Pool',12,1,'{"id":"BR-P12","friendId":"adventure_friend_br","phase":"Pool","seq":12,"familiarity":"Old Friend","type":"Callback","scene":null,"lines":["The strange chair is now a plant stand. Clover''s ferns love it.","It''s the best thing I''ve ever built by accident."],"choices":[{"id":"a","label":"Ferns are happy.","reaction":["They really are. Look at those leaves.","It''s become a tiny garden throne.","Clover calls it the Throne of Leaves. I''m king, apparently."]},{"id":"b","label":"Accidents are great.","reaction":["They are. Don''t tell the cradle.","The cradle is jealous.","The cradle sulks, but the chair is proud."]}],"outro":null}'::jsonb),
('BR-P13','adventure_friend_br','Pool',13,1,'{"id":"BR-P13","friendId":"adventure_friend_br","phase":"Pool","seq":13,"familiarity":"Old Friend","type":"HotTake","scene":null,"lines":["Hot take: you can be thrilled and terrified. They don''t cancel out.","They hold paws. Like a weird couple."],"choices":[{"id":"a","label":"That''s so true.","reaction":["I know! I could write a book. A damp one.","Chapter one: Hat.","I wrote it on a hat. Clover wore it all day."]},{"id":"b","label":"I feel that too.","reaction":["Then we''re in the same club. Big feelings, big hugs.","Membership is free.","We can hold paws about it. Big feelings, big hugs."]}],"outro":null}'::jsonb),
('BR-P14','adventure_friend_br','Pool',14,1,'{"id":"BR-P14","friendId":"adventure_friend_br","phase":"Pool","seq":14,"familiarity":"Old Friend","type":"HotTake","scene":null,"lines":["Hot take: the best gift for a partner is a nap.","Not a gift card. A guarded nap."],"choices":[{"id":"a","label":"Naps are love.","reaction":["Yes! And a blanket. And a pillow fort.","Clover napped four hours. I guarded. Nobody dared.","Clover woke up smiling and said I''m her hero."]},{"id":"b","label":"A snack too?","reaction":["Yes. A snack beside the nap. Chef''s kiss.","I''m a professional now.","Honey toast, obviously. Cut into little hearts."]}],"outro":null}'::jsonb),
('BR-P15','adventure_friend_br','Pool',15,1,'{"id":"BR-P15","friendId":"adventure_friend_br","phase":"Pool","seq":15,"familiarity":"Old Friend","type":"HotTake","scene":null,"lines":["Hot take: saying ''I''m overwhelmed'' is a power move.","It lets everyone breathe. Including me."],"choices":[{"id":"a","label":"Agreed.","reaction":["I say it daily. Clover says, ''Me too.'' We hug.","It works every time.","Clover pats my belly. We both laugh. It helps."]},{"id":"b","label":"It''s hard to say.","reaction":["It is. I practice in the mirror.","''I''m overwhelmed.'' See? Bear voice.","In the mirror it sounds like a confession. It''s freeing."]}],"outro":null}'::jsonb),
('BR-P16','adventure_friend_br','Pool',16,1,'{"id":"BR-P16","friendId":"adventure_friend_br","phase":"Pool","seq":16,"familiarity":"Old Friend","type":"AskBack","scene":null,"lines":["How do you and your partner make time for each other when life is busy?","I need ideas. Seriously. I''m drowning in hats."],"choices":[{"id":"a","label":"We do tiny rituals.","reaction":["Tiny rituals! I love that.","Clover and I share a honey spoon every night.","Tonight we''ll swap a spoonful and a story."]},{"id":"b","label":"We schedule it.","reaction":["Scheduling. Practical. Okay.","I''ll put ''Clover time'' on the wall. In honey.","Maybe I''ll add ''hug'' to the calendar. In bold."]}],"outro":null}'::jsonb),
('BR-P17','adventure_friend_br','Pool',17,1,'{"id":"BR-P17","friendId":"adventure_friend_br","phase":"Pool","seq":17,"familiarity":"Old Friend","type":"AskBack","scene":null,"lines":["What''s the best surprise your partner has given you?","I''m gathering joy for the cub''s story."],"choices":[{"id":"a","label":"A handwritten note.","reaction":["A note! In their handwriting! Oh, my heart.","I keep every note Clover leaves. In a jar.","Clover tucks them in my boots. I smile all day."]},{"id":"b","label":"A weekend away.","reaction":["A weekend away! Dreamy. I''d cry at the train.","We might do that, someday.","I''d bring the blanket. And forty hats, just in case."]}],"outro":null}'::jsonb),
('BR-P18','adventure_friend_br','Pool',18,1,'{"id":"BR-P18","friendId":"adventure_friend_br","phase":"Pool","seq":18,"familiarity":"Old Friend","type":"AskBack","scene":null,"lines":["When do you feel closest to your partner?","I think for me it''s in the quiet moments."],"choices":[{"id":"a","label":"When we''re cooking together.","reaction":["Cooking together! That''s real. Elbows and spoons.","I''m happy when Clover tastes my soup. Even the sock one."]},{"id":"b","label":"When we''re falling asleep.","reaction":["Falling asleep. The best. Warm paws and slow breathing.","I could say that every night.","Her breathing slows, and my worries do too."]}],"outro":null}'::jsonb),
('BR-P19','adventure_friend_br','Pool',19,0.25,'{"id":"BR-P19","friendId":"adventure_friend_br","phase":"Pool","seq":19,"familiarity":"Old Friend","type":"Rare","scene":"Bruno is sitting very still, a paw resting on his chest, eyes shining.","lines":["Clover said something tonight. I can''t stop thinking about it.","''We''re going to be okay.'' Just that.","I believed her. All the way down."],"choices":[{"id":"a","label":"She''s right.","reaction":["I think so too. Big, quiet certainty.","I''m putting that in my heart. Next to the honey.","I''ll tuck that in my heart, next to the honey."]},{"id":"b","label":"That''s beautiful.","reaction":["It is. Some sentences are bigger than hats.","Thanks for hearing it.","I''ll tell her tomorrow, probably with a hat on my head."]}],"outro":null}'::jsonb),
('BR-P20','adventure_friend_br','Pool',20,0.25,'{"id":"BR-P20","friendId":"adventure_friend_br","phase":"Pool","seq":20,"familiarity":"Old Friend","type":"Rare","scene":"Bruno is whispering to a tiny blanket bundle that is mostly a pillow.","lines":["Shh. I''m practicing a bedtime story.","''Once upon a time, there was a bear, and a bunny, and a very large amount of honey...''","Is it too weird to rehearse with a pillow?"],"choices":[{"id":"a","label":"It''s perfect.","reaction":["Thank you. The pillow is a tough audience.","It yawned. Which is a compliment.","I may add a dragon. Clover wants a dragon too."]},{"id":"b","label":"Keep going.","reaction":["Okay. ''And they all lived happily. The end.'' ...Too short?","I''ll add a dragon. A honey dragon.","Next I''ll try a lullaby. Maybe a rock lullaby."]}],"outro":null}'::jsonb)
