insert into public.friend_definitions(stable_id,revision_id,name,subtitle,art,metadata,is_placeholder) values('adventure_friend_ru',coalesce((select value from public.app_config where key='app_major_update_content_revision'),'burrow-v1-placeholder'),'Rue','I''m good. ...Are you?','{"renderer":"bundled","key":"Wolf"}'::jsonb,'{"adventureV2":true,"code":"RU","gender":"she","species":"Wolf"}'::jsonb,false) on conflict(stable_id) do update set name=excluded.name,subtitle=excluded.subtitle,art=excluded.art,metadata=excluded.metadata,status='active',updated_at=now();
insert into public.adventure_dialogues_v2(id,friend_id,phase,seq,weight,content) values
('RU-01','adventure_friend_ru','Intro',1,1,'{"id":"RU-01","friendId":"adventure_friend_ru","phase":"Intro","seq":1,"familiarity":"Stranger","type":"Statement","scene":"Rue is leaning against the wall, arms crossed, pretending not to wait for someone.","lines":["I''m good. Just standing here. On my own.","Sky is late. Which is fine. I don''t need to be walked home.","...I did save him a spot, though."],"choices":[{"id":"a","label":"You waited for them.","reaction":["Don''t say it like that.","...Yeah. I did."]},{"id":"b","label":"Want some company?","reaction":["I''m good. ...Okay, a little.","Stay till Sky shows up. No big deal."]},{"id":"c","label":"Say nothing and sit nearby.","reaction":["Hm. Okay.","This is nice. Don''t tell anyone."]}],"outro":null}'::jsonb),
('RU-02','adventure_friend_ru','Intro',2,1,'{"id":"RU-02","friendId":"adventure_friend_ru","phase":"Intro","seq":2,"familiarity":"Familiar Face","type":"Statement","scene":null,"lines":["Oh. You again. I''m good.","Sky was late because he got me soup. From across the tunnels. Uninvited.","I told him I didn''t need soup. I ate all of it."],"choices":[{"id":"a","label":"Sounds like love.","reaction":["It''s... a lot of soup. But yeah.","Don''t tell him I said it was good."]},{"id":"b","label":"You didn''t need soup?","reaction":["Right. Technically I didn''t. I wanted it.","Wanting is different from needing. I''m learning."]},{"id":"c","label":"Grin quietly.","reaction":["Stop. I can see you grinning.","Okay, fine. It was the best soup."]}],"outro":null}'::jsonb),
('RU-03','adventure_friend_ru','Intro',3,1,'{"id":"RU-03","friendId":"adventure_friend_ru","phase":"Intro","seq":3,"familiarity":"Acquaintance","type":"Statement","scene":"Rue is sharpening a stick with no particular purpose.","lines":["I''ve always done things alone. It''s a wolf thing.","Sky keeps offering to help. I keep saying ''I''m good.''","He stopped offering last week. That felt weird."],"choices":[{"id":"a","label":"Did you miss the offers?","reaction":["...A little. Which is dumb. I said no.","I think I wanted to be asked anyway."]},{"id":"b","label":"Maybe say yes sometime?","reaction":["Yes. Out loud. With my mouth.","I can try. Small ones first."]},{"id":"c","label":"Hand her a smoother stick.","reaction":["Hm. Thanks. That''s better.","See? Help isn''t terrible."]}],"outro":null}'::jsonb),
('RU-04','adventure_friend_ru','Intro',4,1,'{"id":"RU-04","friendId":"adventure_friend_ru","phase":"Intro","seq":4,"familiarity":"Acquaintance","type":"Statement","scene":null,"lines":["Sky asked me to come to a dinner. With his family.","I said ''I''m good.'' He said ''I know. I want you there anyway.''","Why did that hit so hard?"],"choices":[{"id":"a","label":"Because he wants you there.","reaction":["...Yeah. Wants. Not needs.","Wanting is easier to accept. Somehow."]},{"id":"b","label":"You should go.","reaction":["I''m going. I bought a nice leaf. For the table.","Don''t laugh. It''s a very nice leaf."]},{"id":"c","label":"Tell her it sounds nice.","reaction":["It does. It sounds really nice.","Okay. I''m going to say yes."]}],"outro":null}'::jsonb),
('RU-05','adventure_friend_ru','Intro',5,1,'{"id":"RU-05","friendId":"adventure_friend_ru","phase":"Intro","seq":5,"familiarity":"Friend","type":"Ask","scene":null,"lines":["Quick question. Do you and your partner ever not need each other?","Like, doing separate things? Is that okay?"],"choices":[{"id":"a","label":"Yes, we do our own things.","reaction":["Good. That''s what I thought. Separate is healthy.","I just want to be sure I''m allowed to like it."]},{"id":"b","label":"We mostly do things together.","reaction":["Together. Hm. That sounds nice, but loud.","I''d need a lot of quiet breaks."]},{"id":"c","label":"It depends on the day.","reaction":["Depends. Okay. That feels honest.","Some days I want him. Some days I want a tree."]}],"outro":null}'::jsonb),
('RU-06','adventure_friend_ru','Intro',6,1,'{"id":"RU-06","friendId":"adventure_friend_ru","phase":"Intro","seq":6,"familiarity":"Friend","type":"Statement","scene":"Rue is holding two mugs, one half-empty, and glancing at the door.","lines":["Sky left his mug here. I washed it. Don''t know why.","Then I realized I know exactly why.","I... like having his stuff around. Is that weird?"],"choices":[{"id":"a","label":"Not weird at all.","reaction":["Good. I thought it''d make me soft.","I''m soft. A little. Secretly."]},{"id":"b","label":"That''s sweet.","reaction":["Stop. Don''t say sweet. Say... ''fine.''","Okay. It''s sweet. I''m allowed one."]},{"id":"c","label":"Take a sip from his mug.","reaction":["Hey. That''s Sky''s. ...Eh, go ahead.","He wouldn''t mind. He''s generous like that."]}],"outro":null}'::jsonb),
('RU-07','adventure_friend_ru','Intro',7,1,'{"id":"RU-07","friendId":"adventure_friend_ru","phase":"Intro","seq":7,"familiarity":"Close Friend","type":"Confide","scene":"Rue crosses her arms, then drops them. It seems important.","lines":["Can I tell you something? Don''t make it a thing.","I grew up on my own. Nobody checked on me. Ever.","Sky checks on me. Every day. I don''t know where to put it."],"choices":[{"id":"a","label":"Maybe put it somewhere warm.","reaction":["...Somewhere warm. Okay. I can try.","I think my chest is warm. It''s just very unused."]},{"id":"b","label":"Does he know that?","reaction":["He knows I''m not great at it. He says, ''We''ll practice.''","I like that. Practice."]},{"id":"c","label":"Sit beside Rue.","reaction":["Thanks. No fixing. Just sitting.","I think I can say it out loud now."]}],"outro":null}'::jsonb),
('RU-08','adventure_friend_ru','Intro',8,1,'{"id":"RU-08","friendId":"adventure_friend_ru","phase":"Intro","seq":8,"familiarity":"Close Friend","type":"Statement","scene":null,"lines":["I told Sky I needed him. Out loud. At the picnic.","He dropped his sandwich. A full dropped sandwich.","Then he said, ''Say it again.'' So I did."],"choices":[{"id":"a","label":"That''s huge.","reaction":["It was a big, scary, small sentence.","Four words. ''I need you, Sky.'' I''m still shaking."]},{"id":"b","label":"Sandwich down?","reaction":["Sandwich down. Heart up. Ants happy.","It was the best picnic of my life."]},{"id":"c","label":"Smile and clap quietly.","reaction":["Don''t. I''ll cry. A wolf crying is bad for my brand.","...Okay, clap a little."]}],"outro":null}'::jsonb),
('RU-09','adventure_friend_ru','Intro',9,1,'{"id":"RU-09","friendId":"adventure_friend_ru","phase":"Intro","seq":9,"familiarity":"Best Friend","type":"Companion","scene":"Rue pats the ground beside her without looking at you.","lines":["Sky''s out late. I''m not worried. I''m just... awake.","Stay a minute. We don''t need to talk.","Company without conversation is the best kind."],"choices":[{"id":"a","label":"Of course.","reaction":["Thanks. I''m good. But better with you here.","Don''t read into that."]},{"id":"b","label":"Look at the stars with her.","reaction":["Those are the same ones he''s looking at, probably.","It makes me feel closer. Don''t tell him."]},{"id":"c","label":"Sit in silence.","reaction":["Perfect. This is my love language.","I''m calm. For once."]}],"outro":null}'::jsonb),
('RU-10','adventure_friend_ru','Intro',10,1,'{"id":"RU-10","friendId":"adventure_friend_ru","phase":"Intro","seq":10,"familiarity":"Old Friend","type":"Milestone","scene":null,"lines":["Ten times. I kept track. In my head. Not on a wall. Don''t laugh.","Sky said I''ve been smiling more. I said I haven''t. He didn''t believe me.","You help. I think. Thanks.","Your turn. How are you and your partner doing? Honest."],"choices":[{"id":"a","label":"We''re good. Still learning.","reaction":["Learning is the whole job, I think.","Come by. Sky cooks. I pretend I''m not hungry."]},{"id":"b","label":"We had a rough week, honestly.","reaction":["Rough weeks happen. I''m sorry.","Say it out loud to them. I know it''s hard. I''m learning too."]},{"id":"c","label":"Better since I let them help.","reaction":["Letting them help. Huh. That''s the thing.","Look at us. Two growing wolves."]}],"outro":null}'::jsonb),
('RU-P01','adventure_friend_ru','Pool',1,1,'{"id":"RU-P01","friendId":"adventure_friend_ru","phase":"Pool","seq":1,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["Sky built me a little chair by the window. Without asking.","I said I didn''t need it. I sat in it for six hours."],"choices":[{"id":"a","label":"Six hours?!","reaction":["Five and a half. I got up for water.","It''s the best chair I''ve ever sat in.","He saw me in it and smirked. I let him."]},{"id":"b","label":"Aww.","reaction":["Don''t say aww. Say... ''adequate.''","It''s the most adequate chair ever.","I''ll deny this later. Remember that I said it."]}],"outro":null}'::jsonb),
('RU-P02','adventure_friend_ru','Pool',2,1,'{"id":"RU-P02","friendId":"adventure_friend_ru","phase":"Pool","seq":2,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["I asked Sky for help carrying a rock. A big one.","He carried it. I walked beside him. It was kind of nice."],"choices":[{"id":"a","label":"Teamwork!","reaction":["Yeah. I carried the snacks. It was balanced.","We didn''t need the rock. We just wanted the walk."]},{"id":"b","label":"Good for you.","reaction":["Thanks. It took me an hour to ask.","The rock is on our porch now. It''s a nice rock."]}],"outro":null}'::jsonb),
('RU-P03','adventure_friend_ru','Pool',3,1,'{"id":"RU-P03","friendId":"adventure_friend_ru","phase":"Pool","seq":3,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["Sky got sick for two days. I made him soup. First time ever.","It tasted like leaves. He ate every drop."],"choices":[{"id":"a","label":"Leaf soup love.","reaction":["That''s what he called it. ''Leaf soup love.''","He''s still teasing me. I''m still blushing.","I''m not saying I liked the nickname. I''m saying I''m keeping it."]},{"id":"b","label":"Did he get better?","reaction":["Yes. Thanks to the soup, he says. I think it was the nap.","But I''ll take the credit."]}],"outro":null}'::jsonb),
('RU-P04','adventure_friend_ru','Pool',4,1,'{"id":"RU-P04","friendId":"adventure_friend_ru","phase":"Pool","seq":4,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["We had a big argument about space. I said ''I need to be alone.'' He said ''Okay.''","Then he stayed two feet away. All night. Quietly. That helped."],"choices":[{"id":"a","label":"Two feet is respectful.","reaction":["Exactly. Close, but not crowding.","I came back and put my head on his shoulder.","That night I closed the gap myself. No words."]},{"id":"b","label":"Sounds healthy.","reaction":["I think so. We''re learning how to need and not need.","Both can exist.","We said goodnight at the same time. It was funny."]}],"outro":null}'::jsonb),
('RU-P05','adventure_friend_ru','Pool',5,1,'{"id":"RU-P05","friendId":"adventure_friend_ru","phase":"Pool","seq":5,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["Sky''s mother hugged me. Out of nowhere. For a full minute.","I froze. Then I hugged back. Awkwardly."],"choices":[{"id":"a","label":"Hugging is hard.","reaction":["It really is. But it felt... like belonging.","I might do it again. Slowly.","She hugged me again. I hugged back faster. Progress."]},{"id":"b","label":"That''s sweet.","reaction":["It was. I cried in the bushes after.","Sky found me. He didn''t say a thing.","Sky only said, ''You okay?'' I said, ''I''m good.'' He knew."]}],"outro":null}'::jsonb),
('RU-P06','adventure_friend_ru','Pool',6,1,'{"id":"RU-P06","friendId":"adventure_friend_ru","phase":"Pool","seq":6,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["I wrote Sky a note and left it in his boot. Three words: ''Proud of you.''","He found it at work. He called me. He couldn''t talk. Just breathing."],"choices":[{"id":"a","label":"That''s beautiful.","reaction":["I know. I didn''t expect it to matter that much.","Words are strong. I''m learning.","I wrote it with my best pencil. The boot smelled terrible."]},{"id":"b","label":"Short and perfect.","reaction":["Short is my specialty.","Sky says short is better. Fewer words to doubt.","I might do it again. Different words, same boot."]}],"outro":null}'::jsonb),
('RU-P07','adventure_friend_ru','Pool',7,1,'{"id":"RU-P07","friendId":"adventure_friend_ru","phase":"Pool","seq":7,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["I accidentally said ''we'' instead of ''I'' three times today.","''We should go.'' ''We''re out of bread.'' ''We''re okay.''"],"choices":[{"id":"a","label":"We!","reaction":["I know! The little word! It slipped out.","It feels nice. Better than I thought.","Sky noticed too. He grinned and didn''t say a word."]},{"id":"b","label":"Getting comfy.","reaction":["Yeah. A wolf in a pair. Who knew.","Not a pack. Just two.","We''re a pair. A mismatched, slightly clumsy pair."]}],"outro":null}'::jsonb),
('RU-P08','adventure_friend_ru','Pool',8,1,'{"id":"RU-P08","friendId":"adventure_friend_ru","phase":"Pool","seq":8,"familiarity":"Old Friend","type":"Update","scene":null,"lines":["Sky and I went on our first trip. Just us. A day. Three tunnels away.","I packed light. He packed everything. We balanced out."],"choices":[{"id":"a","label":"Perfect combo.","reaction":["He brought a spare sweater for me. I needed it.","I won''t say that to him. I''ll just wear it."]},{"id":"b","label":"Sounds adventurous.","reaction":["It was. We got lost for twenty minutes. We laughed.","That''s what I remember most.","We took no photos. We just stored it all in our heads."]}],"outro":null}'::jsonb),
('RU-P09','adventure_friend_ru','Pool',9,1,'{"id":"RU-P09","friendId":"adventure_friend_ru","phase":"Pool","seq":9,"familiarity":"Old Friend","type":"Callback","scene":null,"lines":["The nice leaf? He pressed it. It''s on our wall now.","He said it was the best thing anyone''s brought to dinner."],"choices":[{"id":"a","label":"That leaf!","reaction":["Yeah. A very nice leaf.","Never underestimate a leaf.","Sky''s mother wants to frame it, but he refused."]},{"id":"b","label":"That''s so sweet.","reaction":["Stop. Okay. It is. It''s very sweet.","I''m learning to say that out loud.","He heard me say it. His ears went pink."]}],"outro":null}'::jsonb),
('RU-P10','adventure_friend_ru','Pool',10,1,'{"id":"RU-P10","friendId":"adventure_friend_ru","phase":"Pool","seq":10,"familiarity":"Old Friend","type":"Callback","scene":null,"lines":["I still think about the sandwich. The dropped one.","Sky wrote ''Say it again'' on a rock. Keeps it by the bed."],"choices":[{"id":"a","label":"Aww.","reaction":["I told you not to say aww. ...Thanks.","It''s a good rock.","He tucked the rock under the pillow. Weird. Perfect."]},{"id":"b","label":"He means it.","reaction":["He does. Every day. I''m getting used to it.","Slowly. Very slowly.","I let him say it. I don''t even flinch now."]}],"outro":null}'::jsonb),
('RU-P11','adventure_friend_ru','Pool',11,1,'{"id":"RU-P11","friendId":"adventure_friend_ru","phase":"Pool","seq":11,"familiarity":"Old Friend","type":"Callback","scene":null,"lines":["Remember the mug? We have matching ones now.","Mine says ''I''m good.'' His says ''I''m also good.''"],"choices":[{"id":"a","label":"Perfect set.","reaction":["They look great together. Like a joke only we get.","Sky laughs every morning.","He puts hot cocoa in mine. I pretend not to notice."]},{"id":"b","label":"Cute.","reaction":["Okay, it''s cute. A small amount.","I''m at peace with it.","Okay, very cute. Don''t tell anyone I said so."]}],"outro":null}'::jsonb),
('RU-P12','adventure_friend_ru','Pool',12,1,'{"id":"RU-P12","friendId":"adventure_friend_ru","phase":"Pool","seq":12,"familiarity":"Old Friend","type":"Callback","scene":null,"lines":["The stick I was sharpening? It''s now our walking stick.","He carved our initials. Mine''s a little crooked."],"choices":[{"id":"a","label":"Crooked is charming.","reaction":["It is. I like crooked. It''s honest.","Sky says he did it on purpose. He didn''t.","He pretended to complain. Then he used it for a week."]},{"id":"b","label":"A walking stick for two?","reaction":["For two. We take turns. It''s a rule.","He gets the downhill. I get the up.","On the long hills, we both lean on it."]}],"outro":null}'::jsonb),
('RU-P13','adventure_friend_ru','Pool',13,1,'{"id":"RU-P13","friendId":"adventure_friend_ru","phase":"Pool","seq":13,"familiarity":"Old Friend","type":"HotTake","scene":null,"lines":["Hot take: you can love being alone and love someone too.","Not either-or. Both. Different dinners."],"choices":[{"id":"a","label":"Totally.","reaction":["I thought it was wrong. It''s not.","I''m good. And I''m his. Both.","Alone-time is a gift we give each other."]},{"id":"b","label":"Doesn''t that clash?","reaction":["Sometimes. But we figure it out.","Clash, then cuddle.","A little. But clash is just a fancy word for ''talk.''"]}],"outro":null}'::jsonb),
('RU-P14','adventure_friend_ru','Pool',14,1,'{"id":"RU-P14","friendId":"adventure_friend_ru","phase":"Pool","seq":14,"familiarity":"Old Friend","type":"HotTake","scene":null,"lines":["Hot take: asking for help is tougher than helping.","Anyone can lift a rock. Try saying ''I can''t.''"],"choices":[{"id":"a","label":"So true.","reaction":["Right? It''s the bravest sentence.","I say it now. Three times a week.","I still pretend it''s not hard. Sky pretends too."]},{"id":"b","label":"I''m bad at it too.","reaction":["Welcome. We''ll practice together.","Try: ''Can you hold this?'' Easy start.","We''ll practice with small stones. Then boulders."]}],"outro":null}'::jsonb),
('RU-P15','adventure_friend_ru','Pool',15,1,'{"id":"RU-P15","friendId":"adventure_friend_ru","phase":"Pool","seq":15,"familiarity":"Old Friend","type":"HotTake","scene":null,"lines":["Hot take: grand gestures are fine, but small check-ins win.","A text. A look. ''You good?'' ''I''m good.'' ''Me too.''"],"choices":[{"id":"a","label":"Check-ins are everything.","reaction":["Right? Tiny, steady, real.","Sky does it every hour. I love it. Quietly.","He texts a leaf emoji. I reply with a rock."]},{"id":"b","label":"I like grand gestures.","reaction":["Those are fun. They just don''t last without the small ones.","Do both. Like me, eventually.","Grand gestures are shiny. Small ones are the glue."]}],"outro":null}'::jsonb),
('RU-P16','adventure_friend_ru','Pool',16,1,'{"id":"RU-P16","friendId":"adventure_friend_ru","phase":"Pool","seq":16,"familiarity":"Old Friend","type":"AskBack","scene":null,"lines":["What''s something you do alone that your partner doesn''t mind?","I''m collecting examples. For my sanity."],"choices":[{"id":"a","label":"Long walks.","reaction":["Long walks. Same. Solo walks are therapy.","Sky waits at the end with water.","He brings water. I bring silence. Perfect trade."]},{"id":"b","label":"Reading in silence.","reaction":["Reading. Quiet. Perfect. Do you share bits?","I read Sky one line sometimes. He loves it.","He reads two pages. I read one line. We meet in the middle."]}],"outro":null}'::jsonb),
('RU-P17','adventure_friend_ru','Pool',17,1,'{"id":"RU-P17","friendId":"adventure_friend_ru","phase":"Pool","seq":17,"familiarity":"Old Friend","type":"AskBack","scene":null,"lines":["How do you ask for help? Without feeling small?","Mine comes out like a growl."],"choices":[{"id":"a","label":"I just say it plainly.","reaction":["Plainly. Okay. ''Can you help me?'' Not bad.","A growl with manners.","Try it. A growl with manners goes a long way."]},{"id":"b","label":"I use a joke first.","reaction":["A joke first. That''s smart. Soften the landing.","I''ll try. ''I''m good. Mostly. Help?''","Softened landings help. A joke and a hug, usually."]}],"outro":null}'::jsonb),
('RU-P18','adventure_friend_ru','Pool',18,1,'{"id":"RU-P18","friendId":"adventure_friend_ru","phase":"Pool","seq":18,"familiarity":"Old Friend","type":"AskBack","scene":null,"lines":["What''s the best thing about being half of a pair?","I want to hear a nice answer."],"choices":[{"id":"a","label":"Someone to share the quiet.","reaction":["Share the quiet. Oh. That''s exactly it.","I''m using that line. Don''t sue me.","It''s the one thing I wasn''t expecting. It''s the best."]},{"id":"b","label":"Someone to laugh with.","reaction":["Laughter. Yes. Sky snorts. It''s the best.","I''d trade ten rocks for that snort.","His laugh is a bark. It never gets old."]}],"outro":null}'::jsonb),
('RU-P19','adventure_friend_ru','Pool',19,0.25,'{"id":"RU-P19","friendId":"adventure_friend_ru","phase":"Pool","seq":19,"familiarity":"Old Friend","type":"Rare","scene":"Rue stands at the entrance, the wind pushing her fur. She smiles, unguarded.","lines":["I''m good. Actually good. For the first time in a long while.","I don''t have a big reason. Just a lot of small ones.","Sky, soup, a chair. You."],"choices":[{"id":"a","label":"Small reasons count.","reaction":["They''re the only reasons that stay.","I''m going to remember today. Without a rock.","Thank you for staying. I didn''t think I''d say that."]},{"id":"b","label":"I''m glad you''re good.","reaction":["Me too. Thanks for asking. You did, in your own way.","Stay a minute. The wind''s nice.","Sit. The wind has something to tell us."]}],"outro":null}'::jsonb),
('RU-P20','adventure_friend_ru','Pool',20,0.25,'{"id":"RU-P20","friendId":"adventure_friend_ru","phase":"Pool","seq":20,"familiarity":"Old Friend","type":"Rare","scene":"Rue is holding a small, folded note, staring at it as if it might bite.","lines":["Sky left me a note this morning. I haven''t read it.","What if it''s sweet? I''ll melt. What if it''s nothing? I''ll sulk.","Read it with me? Don''t look at the words. Just stay."],"choices":[{"id":"a","label":"Of course.","reaction":["...''Rue. You''re never too much. I''m here. Always. Sky.''","...Okay. I''m not crying. The wind is.","Sky''s handwriting always looks like it''s smiling."]},{"id":"b","label":"Wait until you''re ready.","reaction":["Ready. Hm. Never. But maybe now.","Thanks for the pause.","I''ll open it tonight, with him beside me."]}],"outro":null}'::jsonb)
